    struct PageImage
    {
        int width{};
        int height{};
        std::vector<std::uint8_t> bgra;
        mutable HBITMAP dib{};

        PageImage() = default;
        ~PageImage() { ResetDib(); }

        PageImage(PageImage const& other)
            : width(other.width), height(other.height), bgra(other.bgra)
        {
        }

        PageImage& operator=(PageImage const& other)
        {
            if (this != &other)
            {
                ResetDib();
                width = other.width;
                height = other.height;
                bgra = other.bgra;
            }
            return *this;
        }

        PageImage(PageImage&& other) noexcept
            : width(other.width), height(other.height), bgra(std::move(other.bgra)), dib(other.dib)
        {
            other.width = 0;
            other.height = 0;
            other.dib = nullptr;
        }

        PageImage& operator=(PageImage&& other) noexcept
        {
            if (this != &other)
            {
                ResetDib();
                width = other.width;
                height = other.height;
                bgra = std::move(other.bgra);
                dib = other.dib;
                other.width = 0;
                other.height = 0;
                other.dib = nullptr;
            }
            return *this;
        }

        void ResetDib() const
        {
            if (dib)
            {
                DeleteObject(dib);
                dib = nullptr;
            }
        }

        size_t PixelBytes() const
        {
            if (width <= 0 || height <= 0) return 0;
            return static_cast<size_t>(width) * static_cast<size_t>(height) * 4ull;
        }

        size_t CacheBytes() const
        {
            return (dib ? PixelBytes() : 0) + bgra.size();
        }

        void ReleasePixels()
        {
            std::vector<std::uint8_t>().swap(bgra);
        }

        std::uint8_t* AllocateDibPixels()
        {
            ResetDib();
            if (width <= 0 || height <= 0) return nullptr;

            BITMAPINFO info{};
            info.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
            info.bmiHeader.biWidth = width;
            info.bmiHeader.biHeight = -height;
            info.bmiHeader.biPlanes = 1;
            info.bmiHeader.biBitCount = 32;
            info.bmiHeader.biCompression = BI_RGB;

            void* bits = nullptr;
            dib = CreateDIBSection(nullptr, &info, DIB_RGB_COLORS, &bits, nullptr, 0);
            if (!dib || !bits)
            {
                ResetDib();
                return nullptr;
            }
            return static_cast<std::uint8_t*>(bits);
        }

    };

