    COLORREF HueColor(double hue)
    {
        hue -= std::floor(hue);
        double scaled = hue * 6.0;
        int sector = static_cast<int>(std::floor(scaled));
        double fraction = scaled - sector;
        constexpr double saturation = 0.82;
        constexpr double value = 0.92;
        double p = value * (1.0 - saturation);
        double q = value * (1.0 - saturation * fraction);
        double t = value * (1.0 - saturation * (1.0 - fraction));
        double r = value;
        double g = t;
        double b = p;
        switch (sector % 6)
        {
        case 1: r = q; g = value; b = p; break;
        case 2: r = p; g = value; b = t; break;
        case 3: r = p; g = q; b = value; break;
        case 4: r = t; g = p; b = value; break;
        case 5: r = value; g = p; b = q; break;
        default: break;
        }
        return RGB(
            static_cast<int>(r * 255.0 + 0.5),
            static_cast<int>(g * 255.0 + 0.5),
            static_cast<int>(b * 255.0 + 0.5));
    }

    constexpr COLORREF AnnotationPalette[] = {
        RGB(255, 236, 0), RGB(49, 211, 68), RGB(82, 174, 232),
        RGB(244, 97, 142), RGB(156, 120, 229), RGB(255, 157, 50)
    };

    COLORREF AnnotationColor(PdfAnnotation const& annotation)
    {
        if (annotation.hasCustomColor) return annotation.customColor;
        int index = std::clamp(annotation.colorIndex, 0, static_cast<int>(std::size(AnnotationPalette)) - 1);
        return AnnotationPalette[index];
    }

    bool ExactAnnotationPaletteColor(float r, float g, float b, int& index)
    {
        int rr = std::clamp<int>(static_cast<int>(r * 255.0f + 0.5f), 0, 255);
        int gg = std::clamp<int>(static_cast<int>(g * 255.0f + 0.5f), 0, 255);
        int bb = std::clamp<int>(static_cast<int>(b * 255.0f + 0.5f), 0, 255);
        for (int i = 0; i < static_cast<int>(std::size(AnnotationPalette)); ++i)
        {
            COLORREF color = AnnotationPalette[i];
            if (GetRValue(color) == rr && GetGValue(color) == gg && GetBValue(color) == bb)
            {
                index = i;
                return true;
            }
        }
        return false;
    }

    int AnnotationColorIndexFromRgb(float r, float g, float b)
    {
        int rr = std::clamp<int>(static_cast<int>(r * 255.0f + 0.5f), 0, 255);
        int gg = std::clamp<int>(static_cast<int>(g * 255.0f + 0.5f), 0, 255);
        int bb = std::clamp<int>(static_cast<int>(b * 255.0f + 0.5f), 0, 255);
        int best = 0;
        int bestDistance = INT_MAX;
        for (int i = 0; i < static_cast<int>(std::size(AnnotationPalette)); ++i)
        {
            COLORREF c = AnnotationPalette[i];
            int dr = rr - GetRValue(c);
            int dg = gg - GetGValue(c);
            int db = bb - GetBValue(c);
            int distance = dr * dr + dg * dg + db * db;
            if (distance < bestDistance)
            {
                bestDistance = distance;
                best = i;
            }
        }
        return best;
    }

