    std::wstring FormatTimeMs(long long ms)
    {
        std::time_t seconds = static_cast<std::time_t>(ms / 1000);
        std::tm local{};
        localtime_s(&local, &seconds);
        wchar_t buffer[32]{};
        wcsftime(buffer, std::size(buffer), L"%Y/%m/%d %H:%M:%S", &local);
        return buffer;
    }

