    void ApplyPdfThemeFor(int theme, std::uint8_t& b, std::uint8_t& g, std::uint8_t& r)
    {
        int clampedTheme = std::clamp(theme, 0, static_cast<int>(std::size(g_themes)) - 1);
        if (clampedTheme >= 0 && clampedTheme <= 2) return;
        if (clampedTheme >= 5 && clampedTheme <= 6) return;

        if (clampedTheme == 4)
        {
            // Match SumatraPDF's page-bitmap recoloring model: one linear
            // channel mapping includes text, vectors, scans and images.
            COLORREF text = g_themes[clampedTheme].text;
            COLORREF paper = RGB(245, 250, 246);
            auto recolor = [](std::uint8_t sample, std::uint8_t ink, std::uint8_t background)
            {
                int value = static_cast<int>(ink) +
                    (static_cast<int>(sample) * (static_cast<int>(background) - static_cast<int>(ink)) + 127) / 255;
                return static_cast<std::uint8_t>(std::clamp(value, 0, 255));
            };
            b = recolor(b, GetBValue(text), GetBValue(paper));
            g = recolor(g, GetGValue(text), GetGValue(paper));
            r = recolor(r, GetRValue(text), GetRValue(paper));
            return;
        }

        int lum = Luma(r, g, b);
        // Keep near-white image areas on the same paper as the page surface.
        // The green document mode uses a shared page background instead of a
        // separate white paper color, otherwise image rectangles remain
        // visibly brighter than text-only areas.
        COLORREF paper = clampedTheme == 4 ? RGB(245, 250, 246) : g_themes[clampedTheme].paper;

        if (lum > 185)
        {
            double t = static_cast<double>(lum - 185) / 70.0;
            r = MixByte(r, static_cast<std::uint8_t>(GetRValue(paper)), t);
            g = MixByte(g, static_cast<std::uint8_t>(GetGValue(paper)), t);
            b = MixByte(b, static_cast<std::uint8_t>(GetBValue(paper)), t);
        }
    }

    int PdfRenderThemeForUiTheme(int theme)
    {
        if (theme == 3) return 3;
        if (theme == 4) return 4;
        return 0;
    }

    int PdfRenderTheme()
    {
        return PdfRenderThemeForUiTheme(g_theme);
    }

    void ApplyPdfTheme(std::uint8_t& b, std::uint8_t& g, std::uint8_t& r)
    {
        ApplyPdfThemeFor(PdfRenderTheme(), b, g, r);
    }

    COLORREF PdfPageBackgroundColor(int renderTheme = -1)
    {
        int theme = renderTheme >= 0 ? renderTheme : PdfRenderTheme();
        // This is the white-pixel destination of the浅草绿 Plus-style
        // document palette.  Fallback painting must use the same color as a
        // completed page, otherwise a missing render briefly flashes white.
        if (theme == 3) return RGB(255, 249, 233);
        if (theme == 4) return RGB(245, 250, 246);
        return RGB(255, 255, 255);
    }

