    void RefreshReaderHitGeometry(HWND hwnd)
    {
        if (!hwnd) return;
        // Hit testing must use the same scale as the most recent paint. The
        // WM_DPICHANGED handler updates g_dpi and invalidates the window; doing
        // another DPI change inside a mouse event can mix old painted rows with
        // newly scaled geometry and make an otherwise visible row miss.
        RECT client{};
        GetClientRect(hwnd, &client);
        int top = g_immersive ? 0 : S(76);
        int bottom = (g_immersive || !g_statusPinned) ? 0 : S(34);
        int side = SidebarTotalWidth();
        int rail = side ? std::min<int>(S(44), side) : 0;
        g_sidebar = RECT{ rail, top, side, client.bottom - bottom };
        g_sidebarContentCloseRect = SidebarVisible()
            ? RECT{ side - S(31), top + S(3), side - S(1), top + S(33) }
            : RECT{};
        g_stage = RECT{ side + (side ? std::max(1, S(1)) : 0), top, client.right, client.bottom - bottom };
    }

    bool FindOutlineHitAtPoint(HWND hwnd, int x, int y, int& rowId, bool& toggle)
    {
        rowId = -1;
        toggle = false;
        PdfTab* tab = Active();
        if (!tab || !tab->outlineMetadataLoaded || tab->outline.empty()) return false;

        RefreshReaderHitGeometry(hwnd);
        if (g_sideMode != 0 || !SidebarVisible() ||
            x < g_sidebar.left || x >= g_sidebar.right ||
            y < g_sidebar.top || y >= g_sidebar.bottom)
            return false;

        // The scrollbar occupies the right edge of the sidebar and overlaps
        // the row's horizontal extent. Let the dedicated scrollbar handler
        // receive those clicks instead of treating them as outline rows.
        if (g_sideMode == 0 || g_sideMode == 1)
        {
            UpdateSidebarScrollRects();
            if (Hit(g_sidebarScrollTrackRect, x, y)) return false;
        }

        HDC dc = GetDC(hwnd);
        if (!dc) return false;
        HFONT outlineFont = Font(EffectiveOutlineFont());
        HGDIOBJ oldFont = SelectObject(dc, outlineFont);
        EnsureOutlineLayout(dc, *tab, g_sidebar.right - g_sidebar.left);

        int scrollTop = SidebarScrollRect().top;
        int visibleHeight = std::max<int>(1, g_sidebar.bottom - scrollTop);
        int maxScroll = std::max<int>(0, g_sidebarContentHeight - visibleHeight);
        int scrollY = std::clamp(g_sidebarScrollY, 0, maxScroll);
        for (auto const& layoutRow : tab->outlineLayout)
        {
            if (layoutRow.top + layoutRow.height < scrollY) continue;
            if (layoutRow.top > scrollY + visibleHeight + S(8)) break;

            int rowTop = scrollTop + layoutRow.top - scrollY;
            RECT row{ g_sidebar.left + S(3), rowTop,
                g_sidebar.right - S(3), rowTop + layoutRow.height };
            // Include the small visual gap between adjacent rows in the hit
            // target so a boundary click cannot fall through.
            RECT hitRow = row;
            hitRow.top = std::max<int>(scrollTop, hitRow.top - S(2));
            hitRow.bottom = std::min<int>(g_sidebar.bottom, hitRow.bottom + S(2));
            if (!Hit(hitRow, x, y)) continue;

            rowId = layoutRow.id;
            if (layoutRow.hasChildren)
            {
                int lineX = g_sidebar.left + S(10 + layoutRow.depth * 18);
                TEXTMETRICW tm{};
                GetTextMetricsW(dc, &tm);
                int textH = layoutRow.textHeight;
                int textTop = row.top + (layoutRow.height - textH) / 2;
                int firstLineCenterY = textTop + std::max<int>(1, tm.tmHeight) / 2;
                RECT twist{ lineX - S(5), firstLineCenterY - S(5),
                    lineX + S(5), firstLineCenterY + S(5) };
                toggle = Hit(twist, x, y);
            }
            SelectObject(dc, oldFont);
            DeleteObject(outlineFont);
            ReleaseDC(hwnd, dc);
            return true;
        }

        SelectObject(dc, oldFont);
        DeleteObject(outlineFont);
        ReleaseDC(hwnd, dc);
        return false;
    }

    bool HandleOutlineClick(HWND hwnd, int x, int y)
    {
        PdfTab* tab = Active();
        if (!tab) return false;

        auto applyClick = [&](int rowId, bool toggle) -> bool
        {
            if (rowId < 0 || rowId >= static_cast<int>(tab->outline.size())) return false;
            if (toggle)
            {
                if (g_collapsedOutlineRows.find(rowId) != g_collapsedOutlineRows.end())
                    g_collapsedOutlineRows.erase(rowId);
                else
                    g_collapsedOutlineRows.insert(rowId);
                ++tab->outlineCollapseVersion;
                g_sidebarScrollY = ClampSidebarScrollValue(g_sidebarScrollY);
                InvalidateRect(hwnd, &g_sidebar, FALSE);
                return true;
            }
            // A directory jump is a new viewport transaction. Any pending
            // wheel/drag state must be stopped before publishing the target,
            // otherwise a late scroll frame can put the old viewport back.
            CancelStageMotion(hwnd);
            g_sidebarKeyboardFocus = false;
            g_selectedOutlineRow = rowId;
            tab->selectedOutlineRow = rowId;
            ScrollToOutline(*tab, rowId);
            TouchRecentProgress(*tab, false);
            UpdateVertScrollBar(hwnd);
            InvalidateRect(hwnd, &g_sidebar, FALSE);
            // Keep the last complete viewport on screen while the target page
            // renders. The sidebar selection and scrollbar are refreshed now;
            // the target replaces the reader atomically after it is complete.
            RequestPageNavigationRepaint(hwnd, *tab, true);
            return true;
        };

        // Resolve against the current layout only. This intentionally avoids
        // the old painted-row cache, whose coordinates can belong to the
        // previous DPI, sidebar width, scroll position, or active tab.
        int directRowId = -1;
        bool directToggle = false;
        if (FindOutlineHitAtPoint(hwnd, x, y, directRowId, directToggle))
        {
            return applyClick(directRowId, directToggle);
        }
        return false;
    }

    void DrawBookmarkIcon(HDC dc, RECT r, COLORREF color, bool filled)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        Gdiplus::Color c = GdiColor(color);
        Gdiplus::Pen pen(c, std::max<Gdiplus::REAL>(1.05f, S(1.0f)));
        pen.SetStartCap(Gdiplus::LineCapRound);
        pen.SetEndCap(Gdiplus::LineCapRound);
        pen.SetLineJoin(Gdiplus::LineJoinRound);
        Gdiplus::SolidBrush brush(c);
        Gdiplus::GraphicsPath path;
        auto rr = Rf(r);
        float x = rr.X + 0.8f;
        float y = rr.Y + 0.8f;
        float w = std::max(2.0f, rr.Width - 1.6f);
        float h = std::max(2.0f, rr.Height - 1.6f);
        float radius = std::min(std::max(2.0f, w * 0.24f), h * 0.26f);
        float bottomY = y + h - 0.4f;
        float notchY = y + h * 0.70f;
        float centerX = x + w * 0.5f;
        path.StartFigure();
        path.AddLine(x + radius, y, x + w - radius, y);
        path.AddBezier(x + w - radius, y, x + w - radius * 0.36f, y, x + w, y + radius * 0.36f, x + w, y + radius);
        path.AddLine(x + w, y + radius, x + w, bottomY);
        path.AddBezier(x + w, bottomY, x + w * 0.86f, bottomY - h * 0.04f, centerX + w * 0.16f, notchY, centerX, notchY);
        path.AddBezier(centerX, notchY, centerX - w * 0.16f, notchY, x + w * 0.14f, bottomY - h * 0.04f, x, bottomY);
        path.AddLine(x, bottomY, x, y + radius);
        path.AddBezier(x, y + radius, x, y + radius * 0.36f, x + radius * 0.36f, y, x + radius, y);
        path.CloseFigure();
        if (filled) g.FillPath(&brush, &path);
        g.DrawPath(&pen, &path);
    }

    void DrawFavoriteIcon(HDC dc, RECT r, COLORREF color, bool filled)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        g.SetPixelOffsetMode(Gdiplus::PixelOffsetModeHalf);
        // Match 收藏.svg's soft star points. A rounded polygon keeps the icon
        // vector-sharp at every DPI while preserving the hollow toolbar form.
        Gdiplus::Pen pen(GdiColor(color, 218), std::max<Gdiplus::REAL>(1.0f, S(0.9f)));
        pen.SetStartCap(Gdiplus::LineCapRound);
        pen.SetEndCap(Gdiplus::LineCapRound);
        pen.SetLineJoin(Gdiplus::LineJoinRound);
        Gdiplus::SolidBrush brush(GdiColor(color));
        auto rr = Rf(r);
        float cx = rr.X + rr.Width * 0.5f;
        float cy = rr.Y + rr.Height * 0.51f;
        float outer = std::min(rr.Width, rr.Height) * 0.37f;
        float inner = outer * 0.46f;
        Gdiplus::GraphicsPath path;
        Gdiplus::PointF points[10]{};
        for (int i = 0; i < 10; ++i)
        {
            double angle = -3.14159265358979323846 / 2.0 +
                i * 3.14159265358979323846 / 5.0;
            float radius = (i % 2 == 0) ? outer : inner;
            points[i] = Gdiplus::PointF(
                cx + static_cast<float>(std::cos(angle) * radius),
                cy + static_cast<float>(std::sin(angle) * radius));
        }
        Gdiplus::PointF entry[10]{};
        Gdiplus::PointF exit[10]{};
        constexpr float corner = 0.16f;
        for (int i = 0; i < 10; ++i)
        {
            Gdiplus::PointF const& prev = points[(i + 9) % 10];
            Gdiplus::PointF const& current = points[i];
            Gdiplus::PointF const& next = points[(i + 1) % 10];
            entry[i] = Gdiplus::PointF(
                current.X + (prev.X - current.X) * corner,
                current.Y + (prev.Y - current.Y) * corner);
            exit[i] = Gdiplus::PointF(
                current.X + (next.X - current.X) * corner,
                current.Y + (next.Y - current.Y) * corner);
        }
        path.AddLine(exit[9], entry[0]);
        for (int i = 0; i < 10; ++i)
        {
            Gdiplus::PointF const& current = points[i];
            Gdiplus::PointF c1{
                entry[i].X + (current.X - entry[i].X) * (2.0f / 3.0f),
                entry[i].Y + (current.Y - entry[i].Y) * (2.0f / 3.0f) };
            Gdiplus::PointF c2{
                exit[i].X + (current.X - exit[i].X) * (2.0f / 3.0f),
                exit[i].Y + (current.Y - exit[i].Y) * (2.0f / 3.0f) };
            path.AddBezier(entry[i], c1, c2, exit[i]);
            path.AddLine(exit[i], entry[(i + 1) % 10]);
        }
        path.CloseFigure();
        if (filled) g.FillPath(&brush, &path);
        g.DrawPath(&pen, &path);
    }

    void SetFavoriteContextForPage(int page, FavoriteKind kind, int outlineRow)
    {
        g_favoriteContextPage = page;
        g_favoriteContextOutlineRow = outlineRow;
        g_favoriteContextKind = kind;
        g_favoriteContextNorm = {};
        g_favoriteContextHasNorm = false;
        g_favoriteContextValid = Active() && page >= 0;
    }

    void SetFavoriteContextFromSelection()
    {
        if (!Active() || !g_hasContentSelection || g_selectionPage < 0) return;
        SetFavoriteContextForPage(
            g_selectionPage,
            g_selectionIsImage ? FavoriteKind::Image : FavoriteKind::Text);
        g_favoriteContextNorm = g_selectionNorm;
        g_favoriteContextHasNorm = !g_selectionIsImage ? !g_selectionQuads.empty() : true;
    }

    void AddFavoriteFromContext(HWND hwnd)
    {
        PdfTab* tab = Active();
        if (!tab || !g_favoriteContextValid || g_favoriteContextPage < 0 ||
            g_favoriteContextPage >= tab->pageCount)
            return;

        FavoriteItem item;
        item.path = tab->path;
        item.page = g_favoriteContextPage;
        item.outlineRow = g_favoriteContextOutlineRow;
        item.scrollY = g_scrollY;
        item.zoom = tab->zoom;
        item.hasPageOffset = g_continuousRead;
        item.pageOffsetY = item.hasPageOffset ? PageOffsetFromScroll(*tab, item.page, g_scrollY) : 0;
        item.kind = g_favoriteContextKind;
        item.norm = g_favoriteContextNorm;
        item.hasNorm = g_favoriteContextHasNorm;
        item.createdAt = NowMs();
        if (item.kind == FavoriteKind::Outline && item.outlineRow >= 0 && item.outlineRow < static_cast<int>(tab->outline.size()))
            item.title = tab->outline[static_cast<size_t>(item.outlineRow)].title;
        if (item.title.empty()) item.title = FavoriteTitleForPage(item.path, item.page, item.kind);

        auto duplicate = std::find_if(g_favorites.begin(), g_favorites.end(), [&](FavoriteItem const& existing)
        {
            return SameFavoritePosition(existing, item);
        });
        if (duplicate == g_favorites.end())
        {
            g_favorites.push_back(std::move(item));
            if (g_favorites.size() > 200) g_favorites.erase(g_favorites.begin());
            SaveState();
        }
        g_hoverFavoriteItem = -1;
        InvalidateRect(hwnd, nullptr, FALSE);
    }

    void CloseFavoriteList(HWND hwnd)
    {
        RECT oldRect = g_favoriteListRect;
        if (!IsRectEmpty(&oldRect))
        {
            // DrawRoundedShadow expands beyond the popup bounds. Include the
            // complete shadow footprint or its pale rounded edge can remain
            // until an unrelated mouse move repaints that area.
            InflateRect(&oldRect, S(10), S(10));
        }
        // The pointer can remain over a bookmark row after the popup closes.
        // The popup suppresses bookmark hover while it is open, so repainting
        // only the popup bounds would restore just part of that row. Include
        // the whole content panel in this one-shot cleanup region.
        RECT cleanupRect = oldRect;
        if (!IsRectEmpty(&g_sidebar))
        {
            RECT combined{};
            if (IsRectEmpty(&cleanupRect))
                cleanupRect = g_sidebar;
            else if (UnionRect(&combined, &cleanupRect, &g_sidebar))
                cleanupRect = combined;
        }
        g_favoriteListOpen = false;
        g_draggingFavoriteListScroll = false;
        g_hoverFavoriteItem = -1;
        // The popup is an in-canvas overlay, not a child window. Clear its
        // hit-test snapshot at the same time as the open flag so a subsequent
        // click cannot see stale rows while the old pixels are being erased.
        g_favoriteListRect = {};
        g_favoriteListScrollTrackRect = {};
        g_favoriteListScrollThumbRect = {};
        g_favoriteItemRects.clear();
        g_favoriteItemIds.clear();
        g_favoriteListContentHeight = 0;
        g_favoriteListVisibleHeight = 0;
        if (!IsRectEmpty(&cleanupRect))
        {
            if (IsRectEmpty(&g_favoriteListStaleRect))
                g_favoriteListStaleRect = cleanupRect;
            else
            {
                RECT combined{};
                UnionRect(&combined, &g_favoriteListStaleRect, &cleanupRect);
                g_favoriteListStaleRect = combined;
            }
            RedrawWindow(hwnd, &cleanupRect, nullptr,
                RDW_INVALIDATE | RDW_UPDATENOW | RDW_NOERASE);
        }
        else
        {
            InvalidateRect(hwnd, nullptr, FALSE);
        }
    }

    void ActivateFavorite(HWND hwnd, int index)
    {
        if (index < 0 || index >= static_cast<int>(g_favorites.size())) return;
        FavoriteItem const item = g_favorites[static_cast<size_t>(index)];
        // Close the in-canvas popup before activating another Tab. Tab
        // activation can present a cached frame synchronously; leaving the
        // popup open until after that presentation redraws it over the new
        // bookmark panel and leaves a visible rounded-panel ghost.
        CloseFavoriteList(hwnd);
        OpenOrActivatePdf(hwnd, item.path);
        PdfTab* tab = Active();
        if (!tab || !SamePath(tab->path, item.path)) return;

        tab->zoom = std::clamp(item.zoom, 0.0833, 64.0);
        int targetPage = std::clamp(item.page, 0, std::max(0, tab->pageCount - 1));
        bool outlineTarget = item.kind == FavoriteKind::Outline &&
            item.outlineRow >= 0 && item.outlineRow < static_cast<int>(tab->outline.size());
        if (outlineTarget)
        {
            g_selectedOutlineRow = item.outlineRow;
            tab->selectedOutlineRow = item.outlineRow;
            if (g_continuousRead)
                ScrollToOutline(*tab, item.outlineRow);
            else
                ScrollToPage(*tab, targetPage);
        }
        else
        {
            tab->currentPage = targetPage;
            if (g_continuousRead)
            {
                g_contentHeight = ContinuousContentHeight(*tab);
                int stageHeight = std::max<int>(1, static_cast<int>(g_stage.bottom - g_stage.top));
                int maxScroll = std::max<int>(0, g_contentHeight - stageHeight);
                int target = item.hasPageOffset
                    ? PageTopScroll(*tab, targetPage) + item.pageOffsetY
                    : item.scrollY;
                if (item.hasNorm)
                    target = PageTopScroll(*tab, targetPage) +
                        static_cast<int>(std::clamp(item.norm.y0, 0.0f, 1.0f) * PageH(*tab, targetPage)) -
                        std::max<int>(0, static_cast<int>(g_stage.bottom - g_stage.top) / 3);
                g_scrollY = std::clamp(target, 0, maxScroll);
            }
            else
            {
                g_scrollY = 0;
            }
        }
        TouchRecentProgress(*tab, false);
        UpdateVertScrollBar(hwnd);
        // Favorite navigation must update the viewport immediately. Missing
        // target pixels can be filled by the existing committed-page fallback
        // while the requested page continues rendering in the background.
        RequestPageNavigationRepaint(hwnd, *tab, false);
    }

    bool HandleFavoriteClick(HWND hwnd, int x, int y)
    {
        if (g_favoriteListOpen && Hit(g_favoriteButtonRect, x, y))
        {
            CloseFavoriteList(hwnd);
            return true;
        }
        if (!g_favoriteListOpen) return false;
        if (Hit(g_favoriteListScrollThumbRect, x, y))
        {
            g_draggingFavoriteListScroll = true;
            g_favoriteListDragOffset = y - g_favoriteListScrollThumbRect.top;
            SetCapture(hwnd);
            InvalidateRect(hwnd, &g_favoriteListRect, FALSE);
            return true;
        }
        if (Hit(g_favoriteListScrollTrackRect, x, y))
        {
            int trackH = std::max<int>(1,
                g_favoriteListScrollTrackRect.bottom - g_favoriteListScrollTrackRect.top);
            int thumbH = std::max<int>(1,
                g_favoriteListScrollThumbRect.bottom - g_favoriteListScrollThumbRect.top);
            int travel = std::max<int>(1, trackH - thumbH);
            int thumbTop = std::clamp<int>(y - thumbH / 2,
                g_favoriteListScrollTrackRect.top,
                g_favoriteListScrollTrackRect.bottom - thumbH);
                ScrollFavoriteListTo(hwnd, MulDiv(
                 thumbTop - g_favoriteListScrollTrackRect.top,
                 std::max<int>(0, g_favoriteListContentHeight -
                     std::max<int>(1, g_favoriteListVisibleHeight)), travel));
                return true;
        }
        for (size_t i = 0; i < g_favoriteItemRects.size(); ++i)
        {
            if (Hit(g_favoriteItemRects[i], x, y))
            {
                int favoriteIndex = i < g_favoriteItemIds.size()
                    ? g_favoriteItemIds[i]
                    : static_cast<int>(g_favorites.size() - 1 - i);
                ActivateFavorite(hwnd, favoriteIndex);
                return true;
            }
        }
        if (!Hit(g_favoriteListRect, x, y) && !Hit(g_favoriteButtonRect, x, y))
        {
            CloseFavoriteList(hwnd);
            return false;
        }
        return true;
    }

    void PaintFavoriteList(HDC dc)
    {
        g_favoriteItemRects.clear();
        g_favoriteItemIds.clear();
        g_favoriteListRect = {};
        g_favoriteListScrollTrackRect = {};
        g_favoriteListScrollThumbRect = {};
        g_favoriteListContentHeight = 0;
        g_favoriteListVisibleHeight = 0;
        if (!g_favoriteListOpen || !SidebarVisible()) return;

        PdfTab* activeTab = Active();
        if (!activeTab) return;

        int availableWidth = std::max<int>(S(1),
            static_cast<int>(g_stage.right - g_sidebar.left - S(8)));
        int width = std::min<int>(S(300), availableWidth);
        width = std::max<int>(S(220), width);
        int rowH = S(34);
        int headerH = S(30);
        int panelTop = !IsRectEmpty(&g_favoriteButtonRect)
            ? g_favoriteButtonRect.bottom + S(6)
            : g_sidebar.top + S(68);
        int maxBodyHeight = std::max<int>(rowH,
            g_sidebar.bottom - panelTop - headerH - S(8));
        std::vector<int> favoriteOrder;
        favoriteOrder.reserve(g_favorites.size());
        for (int index = 0; index < static_cast<int>(g_favorites.size()); ++index)
        {
            if (FavoriteBelongsToActiveTab(g_favorites[static_cast<size_t>(index)]))
                favoriteOrder.push_back(index);
        }
        int bodyHeight = favoriteOrder.empty()
            ? S(32)
            : std::min<int>(maxBodyHeight,
                std::max<int>(rowH, static_cast<int>(favoriteOrder.size()) * rowH));
        int anchorX = !IsRectEmpty(&g_favoriteButtonRect)
            ? (g_favoriteButtonRect.left + g_favoriteButtonRect.right) / 2
            : g_sidebar.left + S(30);
        int panelLeft = anchorX - width / 2;
        int leftLimit = g_sidebar.left + S(4);
        int rightLimit = g_stage.right - S(4);
        panelLeft = std::max(panelLeft, leftLimit);
        if (panelLeft + width > rightLimit)
            panelLeft = std::max(leftLimit, rightLimit - width);
        RECT panel{
            panelLeft, panelTop,
            panelLeft + width, panelTop + headerH + bodyHeight + S(8) };
        if (panel.right <= panel.left) return;
        g_favoriteListRect = panel;
        HFONT favoriteFont = Font(9);
        HGDIOBJ oldFavoriteFont = SelectObject(dc, favoriteFont);
        if (!IsDarkTheme())
            DrawRoundedShadow(dc, panel, S(8), S(1), S(4), S(4), 18);
        RoundFill(dc, panel, S(8), MenuPopupFill(), MenuPopupBorder());

        RECT heading{ panel.left + S(12), panel.top + S(7), panel.right - S(12), panel.top + headerH };
        Text(dc, L"收藏", heading, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().text);
        if (favoriteOrder.empty())
        {
            RECT empty{ panel.left + S(12), panel.top + S(36), panel.right - S(12), panel.bottom - S(8) };
            Text(dc, L"暂无收藏", empty, DT_CENTER | DT_VCENTER | DT_SINGLELINE, T().muted);
            SelectObject(dc, oldFavoriteFont);
            DeleteObject(favoriteFont);
            return;
        }

        RECT content{ panel.left + S(5), panel.top + headerH,
            panel.right - S(5), panel.bottom - S(8) };
        g_favoriteListContentHeight = static_cast<int>(favoriteOrder.size()) * rowH;
        g_favoriteListVisibleHeight = std::max<int>(1, content.bottom - content.top);
        bool needsScroll = g_favoriteListContentHeight > content.bottom - content.top;
        if (needsScroll)
            content.right -= S(10);
        if (needsScroll)
        {
            g_favoriteListScrollTrackRect = RECT{
                panel.right - S(10), content.top,
                panel.right - S(6), content.bottom };
        }
        g_favoriteListScrollY = ClampFavoriteListScrollValue(g_favoriteListScrollY);

        int saved = SaveDC(dc);
        IntersectClipRect(dc, content.left, content.top, content.right, content.bottom);
        std::stable_sort(favoriteOrder.begin(), favoriteOrder.end(),
            [&](int left, int right)
            {
                return g_favorites[static_cast<size_t>(left)].page <
                    g_favorites[static_cast<size_t>(right)].page;
            });
        int y = content.top - g_favoriteListScrollY;
        for (int i = 0; i < static_cast<int>(favoriteOrder.size()); ++i)
        {
            if (y + rowH >= content.top && y <= content.bottom)
            {
                int favoriteIndex = favoriteOrder[static_cast<size_t>(i)];
                FavoriteItem const& item = g_favorites[static_cast<size_t>(favoriteIndex)];
                RECT row{ content.left, y, content.right, y + rowH };
                int visibleIndex = static_cast<int>(g_favoriteItemRects.size());
                g_favoriteItemRects.push_back(row);
                g_favoriteItemIds.push_back(favoriteIndex);
                bool hovered = g_hoverFavoriteItem == visibleIndex;
                if (hovered) RoundFill(dc, row, S(5), MenuPopupHoverFill(), MenuPopupHoverFill());
                RECT iconRect{ row.left + S(8), row.top + S(8), row.left + S(26), row.bottom - S(8) };
                DrawFavoriteIcon(dc, iconRect, hovered ? T().accent : T().muted, false);
                RECT page{ row.right - S(52), row.top, row.right - S(8), row.bottom };
                RECT title{ row.left + S(34), row.top, page.left - S(8), row.bottom };
                Text(dc, item.title, title,
                    DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS, T().text);
                Text(dc, std::to_wstring(item.page + 1), page,
                    DT_RIGHT | DT_VCENTER | DT_SINGLELINE, T().text);
            }
            y += rowH;
        }
        RestoreDC(dc, saved);
        SelectObject(dc, oldFavoriteFont);
        DeleteObject(favoriteFont);

        if (needsScroll)
        {
            g_favoriteListScrollTrackRect = RECT{
                panel.right - S(10), content.top,
                panel.right - S(6), content.bottom };
            int trackH = std::max<int>(1,
                g_favoriteListScrollTrackRect.bottom - g_favoriteListScrollTrackRect.top);
            int visibleH = std::max<int>(1, content.bottom - content.top);
            int thumbH = std::clamp(MulDiv(visibleH, trackH,
                std::max(1, g_favoriteListContentHeight)), S(28), trackH);
            int maxScroll = std::max<int>(1, g_favoriteListContentHeight - visibleH);
            int travel = std::max<int>(0, trackH - thumbH);
            int thumbTop = g_favoriteListScrollTrackRect.top + MulDiv(
                g_favoriteListScrollY, travel, maxScroll);
            g_favoriteListScrollThumbRect = RECT{
                g_favoriteListScrollTrackRect.left, thumbTop,
                g_favoriteListScrollTrackRect.right, thumbTop + thumbH };
            bool active = g_draggingFavoriteListScroll ||
                Hit(g_favoriteListRect, g_mousePos.x, g_mousePos.y);
            int centerX = (g_favoriteListScrollTrackRect.left +
                g_favoriteListScrollTrackRect.right) / 2;
            int visualW = active ? S(4) : std::max(2, S(2));
            RECT thumb{
                centerX - visualW / 2, g_favoriteListScrollThumbRect.top,
                centerX + (visualW + 1) / 2,
                g_favoriteListScrollThumbRect.bottom };
            DrawScrollThumbAA(dc, thumb, S(5), ScrollThumbColor(active));
        }
    }

    std::wstring FormatDate(long long ms)
    {
        std::time_t seconds = static_cast<std::time_t>(ms / 1000);
        std::tm local{};
        localtime_s(&local, &seconds);
        wchar_t buffer[24]{};
        wcsftime(buffer, std::size(buffer), L"%Y-%m-%d", &local);
        return buffer;
    }

    std::wstring FormatFileSize(std::wstring const& path)
    {
        try
        {
            auto bytes = std::filesystem::file_size(path);
            double value = static_cast<double>(bytes);
            const wchar_t* units[] = { L"B", L"K", L"M", L"G" };
            int unit = 0;
            while (value >= 1024.0 && unit < 3)
            {
                value /= 1024.0;
                ++unit;
            }
            wchar_t buffer[32]{};
            if (unit == 0) swprintf_s(buffer, L"%llu%s", static_cast<unsigned long long>(bytes), units[unit]);
            else swprintf_s(buffer, L"%.2f%s", value, units[unit]);
            return buffer;
        }
        catch (...)
        {
            return L"-";
        }
    }

    void DrawStarIcon(HDC dc, RECT r, COLORREF color, bool filled)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        auto rr = Rf(r);
        float cx = rr.X + rr.Width * 0.5f;
        float cy = rr.Y + rr.Height * 0.52f;
        float outer = std::min(rr.Width, rr.Height) * 0.44f;
        float inner = outer * 0.48f;
        Gdiplus::GraphicsPath path;
        Gdiplus::PointF points[10]{};
        for (int i = 0; i < 10; ++i)
        {
            double angle = -3.14159265358979323846 / 2.0 + i * 3.14159265358979323846 / 5.0;
            float radius = (i % 2 == 0) ? outer : inner;
            points[i] = Gdiplus::PointF(
                cx + static_cast<float>(std::cos(angle) * radius),
                cy + static_cast<float>(std::sin(angle) * radius));
        }
        path.AddLines(points, 10);
        path.CloseFigure();
        Gdiplus::Pen pen(GdiColor(color), std::max<Gdiplus::REAL>(1.25f, S(1.1f)));
        pen.SetLineJoin(Gdiplus::LineJoinRound);
        Gdiplus::SolidBrush brush(GdiColor(color));
        if (filled) g.FillPath(&brush, &path);
        g.DrawPath(&pen, &path);
    }

    void DrawHomeIcon(HDC dc, RECT r, HomeAction action, COLORREF color, bool active = false)
    {
        if (action == HomeAction::Favorite)
        {
            DrawStarIcon(dc, r, active ? RGB(246, 190, 58) : color, active);
            return;
        }

        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        Gdiplus::Pen pen(GdiColor(color), std::max<Gdiplus::REAL>(1.65f, S(1.35f)));
        pen.SetStartCap(Gdiplus::LineCapRound);
        pen.SetEndCap(Gdiplus::LineCapRound);
        pen.SetLineJoin(Gdiplus::LineJoinRound);
        Gdiplus::SolidBrush brush(GdiColor(color));
        auto rr = Rf(r);
        float x = rr.X;
        float y = rr.Y;
        float w = rr.Width;
        float h = rr.Height;

        if (action == HomeAction::Pin)
        {
            Gdiplus::GraphicsPath path;
            Gdiplus::PointF points[] = {
                { x + w * 0.32f, y + h * 0.12f },
                { x + w * 0.68f, y + h * 0.12f },
                { x + w * 0.60f, y + h * 0.36f },
                { x + w * 0.78f, y + h * 0.56f },
                { x + w * 0.58f, y + h * 0.56f },
                { x + w * 0.52f, y + h * 0.88f },
                { x + w * 0.48f, y + h * 0.88f },
                { x + w * 0.42f, y + h * 0.56f },
                { x + w * 0.22f, y + h * 0.56f },
                { x + w * 0.40f, y + h * 0.36f }
            };
            path.AddLines(points, static_cast<INT>(std::size(points)));
            path.CloseFigure();
            if (active) g.FillPath(&brush, &path);
            g.DrawPath(&pen, &path);
        }
        else if (action == HomeAction::Folder)
        {
            Gdiplus::RectF body(x + w * 0.13f, y + h * 0.34f, w * 0.74f, h * 0.48f);
            Gdiplus::GraphicsPath path;
            path.AddLine(x + w * 0.14f, y + h * 0.34f, x + w * 0.37f, y + h * 0.34f);
            path.AddLine(x + w * 0.43f, y + h * 0.25f, x + w * 0.58f, y + h * 0.25f);
            path.AddLine(x + w * 0.65f, y + h * 0.34f, x + w * 0.86f, y + h * 0.34f);
            path.AddLine(x + w * 0.86f, y + h * 0.82f, x + w * 0.14f, y + h * 0.82f);
            path.CloseFigure();
            g.DrawPath(&pen, &path);
            if (active) g.FillRectangle(&brush, body);
        }
        else if (action == HomeAction::Remove)
        {
            float d = std::min(w, h) * 0.78f;
            Gdiplus::RectF dot(x + (w - d) * 0.5f, y + (h - d) * 0.5f, d, d);
            Gdiplus::SolidBrush red(GdiColor(color));
            Gdiplus::Pen white(GdiColor(RGB(255, 255, 255)), std::max<Gdiplus::REAL>(1.7f, S(1.55f)));
            white.SetStartCap(Gdiplus::LineCapRound);
            white.SetEndCap(Gdiplus::LineCapRound);
            g.FillEllipse(&red, dot);
            g.DrawLine(&white, dot.X + dot.Width * 0.28f, dot.Y + dot.Height * 0.50f, dot.X + dot.Width * 0.72f, dot.Y + dot.Height * 0.50f);
        }
        else if (action == HomeAction::ClearAll)
        {
            g.DrawLine(&pen, x + w * 0.30f, y + h * 0.28f, x + w * 0.72f, y + h * 0.28f);
            g.DrawLine(&pen, x + w * 0.43f, y + h * 0.20f, x + w * 0.58f, y + h * 0.20f);
            g.DrawRectangle(&pen, x + w * 0.34f, y + h * 0.36f, w * 0.34f, h * 0.42f);
            g.DrawLine(&pen, x + w * 0.45f, y + h * 0.44f, x + w * 0.45f, y + h * 0.70f);
            g.DrawLine(&pen, x + w * 0.57f, y + h * 0.44f, x + w * 0.57f, y + h * 0.70f);
        }
        else if (action == HomeAction::ToggleView)
        {
            if (g_homeListView)
            {
                for (int row = 0; row < 3; ++row)
                {
                    float yy = y + h * (0.24f + row * 0.25f);
                    g.DrawLine(&pen, x + w * 0.22f, yy, x + w * 0.30f, yy);
                    g.DrawLine(&pen, x + w * 0.42f, yy, x + w * 0.82f, yy);
                }
            }
            else
            {
                for (int yy = 0; yy < 2; ++yy)
                    for (int xx = 0; xx < 2; ++xx)
                        g.DrawRectangle(&pen, x + w * (0.22f + xx * 0.32f), y + h * (0.22f + yy * 0.32f), w * 0.18f, h * 0.18f);
            }
        }
    }

    void AddButton(int id, RECT r, std::wstring text, std::wstring tip = L"")
    {
        g_buttons.push_back(Button{ id, r, std::move(text), std::move(tip) });
    }

    bool IsBookmarkToolbarButton(int id)
    {
        return id == CmdOutlineToggleAll || id == CmdSidebarContentClose ||
            id == CmdFavoriteListToggle || id == CmdOutlineSmall ||
            id == CmdOutlineLarge;
    }

    void RemoveBookmarkToolbarButtons()
    {
        std::erase_if(g_buttons, [](Button const& button)
        {
            return IsBookmarkToolbarButton(button.id);
        });
    }

    void DrawButton(HDC dc, const Button& b)
    {
        bool hovered = g_hasHoverButton && EqualRect(&g_hoverButtonRect, &b.rect);
        bool pressed = g_hasPressedButton && EqualRect(&g_pressedButtonRect, &b.rect);
        COLORREF fill = pressed ? T().line : (hovered ? SidebarHoverFill() : T().panel2);
        COLORREF line = pressed ? T().accent : (hovered ? MixColor(T().line, T().accent, 0.22) : T().line);
        if (IsGlassTheme())
        {
            fill = pressed ? RGB(232, 236, 241) : (hovered ? RGB(255, 255, 255) : T().panel);
            line = pressed ? RGB(202, 210, 220) : (hovered ? RGB(228, 234, 241) : T().line);
        }
        RoundFill(dc, b.rect, S(8), fill, line);
        Text(dc, b.text, b.rect, DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS, pressed || hovered ? T().text : T().muted);
    }

    void DrawBookmarkToolbarFeedback(HDC dc, RECT r, bool hovered, bool pressed)
    {
        if (!hovered && !pressed) return;
        COLORREF fill = pressed
            ? MixColor(T().panel2, T().line, IsDarkTheme() ? 0.34 : 0.28)
            : SidebarHoverFill();
        RoundFill(dc, r, S(6), fill, fill);
    }

    void DrawFlatMenuItem(HDC dc, const Button& b)
    {
        bool hovered = g_hasHoverButton && EqualRect(&g_hoverButtonRect, &b.rect);
        bool pressed = g_hasPressedButton && EqualRect(&g_pressedButtonRect, &b.rect);
        if (IsGraphiteTheme())
        {
            if (pressed || hovered)
                RoundFill(dc, b.rect, S(8), pressed ? RGB(77, 83, 91) : RGB(44, 48, 53), RGB(48, 52, 58));
        }
        else if (IsAuroraTheme())
        {
            BYTE alpha = pressed ? 188 : (hovered ? 136 : 0);
            if (alpha > 0)
            {
                AlphaFill(dc, b.rect, T().stage, alpha);
                RoundFill(dc, b.rect, S(8),
                    pressed ? MixColor(T().panel2, T().accent, 0.12) : T().stage,
                    pressed ? MixColor(T().line, T().accent, 0.28) : MixColor(T().line, T().accent, 0.12));
            }
        }
        else if (IsGlassTheme())
        {
            BYTE alpha = pressed ? 180 : (hovered ? 128 : 0);
            if (alpha > 0)
            {
                AlphaFill(dc, b.rect, RGB(255, 255, 255), alpha);
                RoundFill(dc, b.rect, S(8),
                    pressed ? RGB(248, 251, 254) : RGB(255, 255, 255),
                    pressed ? RGB(208, 217, 226) : RGB(228, 234, 241));
            }
        }
        else if (pressed || hovered)
        {
            COLORREF fill = pressed
                ? MixColor(T().panel2, T().accent, IsDarkTheme() ? 0.26 : 0.12)
                : MixColor(T().panel2, T().paper, IsDarkTheme() ? 0.18 : 0.50);
            COLORREF line = pressed
                ? MixColor(T().line, T().accent, 0.36)
                : MixColor(T().line, T().text, 0.08);
            RoundFill(dc, b.rect, S(8), fill, line);
        }
        Text(dc, b.text, b.rect, DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS, pressed ? T().text : MixColor(T().text, T().muted, 0.08));
    }

    void DrawStatusHotArea(HDC dc, RECT r, int radius = 6)
    {
        if (Hit(r, g_mousePos.x, g_mousePos.y))
        {
            if (IsGlassTheme())
            {
                RoundFill(dc, r, S(radius), RGB(255, 255, 255), RGB(228, 234, 241));
            }
            else
            {
                RoundFill(dc, r, S(radius), T().panel2, T().line);
            }
        }
    }

