    void DrawDownCaret(HDC dc, int x, int y, COLORREF color)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        g.SetPixelOffsetMode(Gdiplus::PixelOffsetModeHalf);
        Gdiplus::Pen pen(GdiColor(color), std::max<Gdiplus::REAL>(1.0f, S(0.9f)));
        pen.SetStartCap(Gdiplus::LineCapRound);
        pen.SetEndCap(Gdiplus::LineCapRound);
        pen.SetLineJoin(Gdiplus::LineJoinRound);

        float cx = static_cast<float>(x);
        float cy = static_cast<float>(y) + S(0.35f);
        float halfWidth = S(3.0f);
        float halfHeight = S(1.8f);
        Gdiplus::PointF points[] = {
            { cx - halfWidth, cy - halfHeight },
            { cx, cy + halfHeight },
            { cx + halfWidth, cy - halfHeight }
        };
        g.DrawLines(&pen, points, static_cast<INT>(std::size(points)));
    }

    void DrawOutlineToggleGlyph(HDC dc, RECT r, bool collapse, COLORREF color)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        g.SetPixelOffsetMode(Gdiplus::PixelOffsetModeHalf);
        Gdiplus::Pen pen(GdiColor(color), std::max<Gdiplus::REAL>(1.35f, S(1.05f)));
        pen.SetStartCap(Gdiplus::LineCapRound);
        pen.SetEndCap(Gdiplus::LineCapRound);
        pen.SetLineJoin(Gdiplus::LineJoinRound);

        float cx = static_cast<float>(r.left + r.right) * 0.5f;
        float cy = static_cast<float>(r.top + r.bottom) * 0.5f;
        // Open the chevron by another roughly twenty degrees while keeping
        // its button footprint and stroke aligned with the close control.
        float dx = S(3.4f);
        float dy = S(1.9f);
        Gdiplus::PointF points[3]{};
        if (collapse)
        {
            points[0] = { cx - dx, cy - dy };
            points[1] = { cx, cy + dy };
            points[2] = { cx + dx, cy - dy };
        }
        else
        {
            points[0] = { cx - dx, cy + dy };
            points[1] = { cx, cy - dy };
            points[2] = { cx + dx, cy + dy };
        }
        g.DrawLines(&pen, points, static_cast<INT>(std::size(points)));
    }

    void DrawTabArrowGlyph(HDC dc, RECT r, bool right, COLORREF color)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        Gdiplus::Pen pen(GdiColor(color), std::max<Gdiplus::REAL>(1.4f, S(1.15f)));
        pen.SetStartCap(Gdiplus::LineCapRound);
        pen.SetEndCap(Gdiplus::LineCapRound);
        pen.SetLineJoin(Gdiplus::LineJoinRound);
        float cx = (r.left + r.right) * 0.5f;
        float cy = (r.top + r.bottom) * 0.5f;
        float dir = right ? 1.0f : -1.0f;
        float dx = S(3.9f);
        float dy = S(4.8f);
        g.DrawLine(&pen, cx - dir * dx, cy - dy, cx + dir * dx, cy);
        g.DrawLine(&pen, cx + dir * dx, cy, cx - dir * dx, cy + dy);
    }

    void DrawStatusIcon(HDC dc, RECT r, StatusIcon icon, COLORREF color)
    {
        int cx = (r.left + r.right) / 2;
        int cy = (r.top + r.bottom) / 2;
        if (icon == StatusIcon::First || icon == StatusIcon::Prev || icon == StatusIcon::Next || icon == StatusIcon::Last)
        {
            Gdiplus::Graphics g(dc);
            g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
            Gdiplus::Pen aaPen(GdiColor(color), std::max<Gdiplus::REAL>(1.35f, S(1.25f)));
            aaPen.SetStartCap(Gdiplus::LineCapRound);
            aaPen.SetEndCap(Gdiplus::LineCapRound);
            aaPen.SetLineJoin(Gdiplus::LineJoinRound);
            float x = static_cast<float>(cx);
            float y = static_cast<float>(cy);
            float w = S(4.6f);
            float h = S(5.5f);
            auto drawChevron = [&](bool left)
            {
                if (left)
                {
                    g.DrawLine(&aaPen, x + w * 0.5f, y - h, x - w * 0.5f, y);
                    g.DrawLine(&aaPen, x - w * 0.5f, y, x + w * 0.5f, y + h);
                }
                else
                {
                    g.DrawLine(&aaPen, x - w * 0.5f, y - h, x + w * 0.5f, y);
                    g.DrawLine(&aaPen, x + w * 0.5f, y, x - w * 0.5f, y + h);
                }
            };
            if (icon == StatusIcon::First || icon == StatusIcon::Prev)
            {
                if (icon == StatusIcon::First) g.DrawLine(&aaPen, x - S(6.0f), y - S(6.0f), x - S(6.0f), y + S(6.0f));
                x += icon == StatusIcon::First ? S(1.0f) : 0.0f;
                drawChevron(true);
            }
            else
            {
                x -= icon == StatusIcon::Last ? S(1.0f) : 0.0f;
                drawChevron(false);
                if (icon == StatusIcon::Last) g.DrawLine(&aaPen, x + S(6.0f), y - S(6.0f), x + S(6.0f), y + S(6.0f));
            }
            return;
        }
        HPEN pen = CreatePen(PS_SOLID, std::max(1, S(1)), color);
        HGDIOBJ oldPen = SelectObject(dc, pen);
        HGDIOBJ oldBrush = SelectObject(dc, GetStockObject(NULL_BRUSH));

        auto chevron = [&](int dir)
        {
            int w = S(4);
            int h = S(5);
            MoveToEx(dc, cx + dir * w / 2, cy - h, nullptr);
            LineTo(dc, cx - dir * w / 2, cy);
            LineTo(dc, cx + dir * w / 2, cy + h);
        };
        auto square = [&](int left, int top, int size)
        {
            Rectangle(dc, left, top, left + size, top + size);
        };

        switch (icon)
        {
        case StatusIcon::First:
            MoveToEx(dc, cx - S(6), cy - S(6), nullptr);
            LineTo(dc, cx - S(6), cy + S(6));
            cx += S(1);
            chevron(1);
            break;
        case StatusIcon::Prev:
            chevron(1);
            break;
        case StatusIcon::Next:
            chevron(-1);
            break;
        case StatusIcon::Last:
            cx -= S(1);
            chevron(-1);
            MoveToEx(dc, cx + S(6), cy - S(6), nullptr);
            LineTo(dc, cx + S(6), cy + S(6));
            break;
        case StatusIcon::RotateLeft:
            Arc(dc, cx - S(7), cy - S(7), cx + S(7), cy + S(7), cx - S(7), cy, cx, cy - S(7));
            MoveToEx(dc, cx - S(8), cy, nullptr);
            LineTo(dc, cx - S(10), cy - S(4));
            MoveToEx(dc, cx - S(8), cy, nullptr);
            LineTo(dc, cx - S(4), cy - S(3));
            break;
        case StatusIcon::RotateRight:
            Arc(dc, cx - S(7), cy - S(7), cx + S(7), cy + S(7), cx, cy - S(7), cx + S(7), cy);
            MoveToEx(dc, cx + S(8), cy, nullptr);
            LineTo(dc, cx + S(10), cy - S(4));
            MoveToEx(dc, cx + S(8), cy, nullptr);
            LineTo(dc, cx + S(4), cy - S(3));
            break;
        case StatusIcon::ColorMode:
        {
            SelectObject(dc, oldBrush);
            SelectObject(dc, oldPen);
            DeleteObject(pen);

            Gdiplus::Graphics g(dc);
            g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
            g.SetPixelOffsetMode(Gdiplus::PixelOffsetModeHighQuality);
            float gcx = static_cast<float>(cx);
            float gcy = static_cast<float>(cy);
            Gdiplus::Pen modePen(GdiColor(color, 238), std::max<Gdiplus::REAL>(1.25f, S(1.0f)));
            modePen.SetStartCap(Gdiplus::LineCapRound);
            modePen.SetEndCap(Gdiplus::LineCapRound);
            modePen.SetLineJoin(Gdiplus::LineJoinRound);

            if (IsDarkTheme())
            {
                float radius = S(3.8f);
                g.DrawEllipse(&modePen, gcx - radius, gcy - radius, radius * 2.0f, radius * 2.0f);
                for (int ray = 0; ray < 8; ++ray)
                {
                    constexpr float pi = 3.14159265358979323846f;
                    float angle = static_cast<float>(ray) * pi / 4.0f;
                    float inner = S(5.7f);
                    float outer = S(7.0f);
                    g.DrawLine(&modePen,
                        gcx + std::cos(angle) * inner, gcy + std::sin(angle) * inner,
                        gcx + std::cos(angle) * outer, gcy + std::sin(angle) * outer);
                }
            }
            else
            {
                // The supplied SVG's arc commands are expanded to cubic curves so
                // the original two-subpath geometry can be rendered natively.
                const float scale = S(0.014f);
                auto point = [&](float x, float y)
                {
                    return Gdiplus::PointF(
                        gcx + (x - 512.0f) * scale,
                        gcy + (y - 512.0f) * scale);
                };
                Gdiplus::GraphicsPath moon;
                moon.SetFillMode(Gdiplus::FillModeWinding);
                moon.StartFigure();
                moon.AddBezier(
                    point(511.886222f, 79.644444f), point(382.435953f, 79.635384f),
                    point(259.796139f, 137.645432f), point(177.688411f, 237.723867f));
                moon.AddBezier(
                    point(177.688411f, 237.723867f), point(95.580682f, 337.802302f),
                    point(62.649662f, 469.412475f), point(87.950222f, 596.366222f));
                moon.AddBezier(
                    point(87.950222f, 596.366222f), point(113.225382f, 723.287003f),
                    point(194.025382f, 832.212104f), point(308.155310f, 893.220940f));
                moon.AddBezier(
                    point(308.155310f, 893.220940f), point(422.285238f, 954.229776f),
                    point(557.742758f, 960.906428f), point(677.319111f, 911.416889f));
                moon.AddBezier(
                    point(677.319111f, 911.416889f), point(838.561008f, 844.629044f),
                    point(943.827248f, 687.436546f), point(944.184889f, 512.910222f));
                moon.AddBezier(
                    point(944.184889f, 512.910222f), point(944.432788f, 508.210674f),
                    point(944.432788f, 503.501326f), point(944.184889f, 498.801778f));
                moon.AddBezier(
                    point(944.184889f, 498.801778f), point(943.556764f, 487.668688f),
                    point(937.530241f, 477.544302f), point(928.043315f, 471.684397f));
                moon.AddBezier(
                    point(928.043315f, 471.684397f), point(918.556390f, 465.824492f),
                    point(906.805283f, 464.967952f), point(896.568889f, 469.390222f));
                moon.AddBezier(
                    point(896.568889f, 469.390222f), point(864.585545f, 483.146043f),
                    point(830.062526f, 490.008002f), point(795.249778f, 489.528889f));
                moon.AddBezier(
                    point(795.249778f, 489.528889f), point(707.916669f, 489.814885f),
                    point(627.100821f, 445.468904f), point(580.736044f, 372.131198f));
                moon.AddBezier(
                    point(580.736044f, 372.131198f), point(534.371267f, 298.793493f),
                    point(528.972065f, 206.768410f), point(566.442667f, 128.512000f));
                moon.AddBezier(
                    point(566.442667f, 128.512000f), point(571.502911f, 117.937854f),
                    point(570.782936f, 105.506767f), point(564.535770f, 95.587515f));
                moon.AddBezier(
                    point(564.535770f, 95.587515f), point(558.288605f, 85.668263f),
                    point(547.388347f, 79.648740f), point(535.665778f, 79.644444f));
                moon.AddLine(point(535.665778f, 79.644444f), point(511.886222f, 79.644444f));
                moon.CloseFigure();
                moon.StartFigure();
                moon.AddBezier(
                    point(794.567111f, 557.795556f), point(821.418667f, 558.136889f),
                    point(848.099555f, 555.064889f), point(874.040889f, 548.693333f));
                moon.AddBezier(
                    point(874.040889f, 548.693333f), point(863.663134f, 650.726435f),
                    point(810.746151f, 743.654988f), point(728.292306f, 804.645276f));
                moon.AddBezier(
                    point(728.292306f, 804.645276f), point(645.838461f, 865.635565f),
                    point(541.490812f, 889.034096f), point(440.888889f, 869.091556f));
                moon.AddBezier(
                    point(440.888889f, 869.091556f), point(333.965324f, 847.843658f),
                    point(242.195304f, 779.788249f), point(190.816115f, 683.640961f));
                moon.AddBezier(
                    point(190.816115f, 683.640961f), point(139.436926f, 587.493673f),
                    point(133.858890f, 473.378991f), point(175.616000f, 372.679111f));
                moon.AddBezier(
                    point(175.616000f, 372.679111f), point(228.357543f, 245.318441f),
                    point(348.504496f, 158.665533f), point(486.001778f, 148.821333f));
                moon.AddBezier(
                    point(486.001778f, 148.821333f), point(458.223089f, 245.643934f),
                    point(477.568646f, 349.892720f), point(538.236480f, 430.302208f));
                moon.AddBezier(
                    point(538.236480f, 430.302208f), point(598.904314f, 510.711694f),
                    point(693.838497f, 557.929918f), point(794.567111f, 557.795556f));
                moon.CloseFigure();
                // The SVG is a filled band (wider than the neighboring stroked
                // glyph), so a calibrated alpha gives it the same perceived
                // darkness on high-DPI displays.
                Gdiplus::SolidBrush moonBrush(GdiColor(color, 210));
                g.FillPath(&moonBrush, &moon);
            }
            return;
        }
        case StatusIcon::Theme:
        {
            float size = S(13.2f);
            float left = static_cast<float>(r.left) + S(3.4f);
            float top = static_cast<float>(cy) - size * 0.5f;
            SelectObject(dc, oldBrush);
            SelectObject(dc, oldPen);
            DeleteObject(pen);

            Gdiplus::Graphics g(dc);
            g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
            g.SetPixelOffsetMode(Gdiplus::PixelOffsetModeHighQuality);
            Gdiplus::Pen shirtPen(GdiColor(color, 238), std::max<Gdiplus::REAL>(1.25f, S(1.0f)));
            shirtPen.SetStartCap(Gdiplus::LineCapRound);
            shirtPen.SetEndCap(Gdiplus::LineCapRound);
            shirtPen.SetLineJoin(Gdiplus::LineJoinRound);
            float l = left + S(0.2f);
            float t = top + S(1.2f);
            float rr = left + size - S(0.2f);
            float b = top + size - S(1.0f);
            float mid = (l + rr) * 0.5f;
            Gdiplus::PointF shirt[] = {
                Gdiplus::PointF(mid - S(3.4f), t),
                Gdiplus::PointF(mid - S(1.7f), t),
                Gdiplus::PointF(mid - S(1.15f), t + S(1.45f)),
                Gdiplus::PointF(mid, t + S(1.95f)),
                Gdiplus::PointF(mid + S(1.15f), t + S(1.45f)),
                Gdiplus::PointF(mid + S(1.7f), t),
                Gdiplus::PointF(mid + S(3.4f), t),
                Gdiplus::PointF(rr, t + S(3.5f)),
                Gdiplus::PointF(rr - S(1.7f), t + S(5.3f)),
                Gdiplus::PointF(rr - S(2.5f), t + S(4.2f)),
                Gdiplus::PointF(rr - S(2.5f), b),
                Gdiplus::PointF(l + S(2.5f), b),
                Gdiplus::PointF(l + S(2.5f), t + S(4.2f)),
                Gdiplus::PointF(l + S(1.7f), t + S(5.3f)),
                Gdiplus::PointF(l, t + S(3.5f)),
                Gdiplus::PointF(mid - S(3.4f), t)
            };
            g.DrawLines(&shirtPen, shirt, static_cast<INT>(std::size(shirt)));
            DrawDownCaret(dc, static_cast<int>(left + S(20.0f)), cy, color);
            return;
        }
        case StatusIcon::View:
        {
            SelectObject(dc, oldBrush);
            SelectObject(dc, oldPen);
            DeleteObject(pen);

            Gdiplus::Graphics g(dc);
            g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
            g.SetPixelOffsetMode(Gdiplus::PixelOffsetModeHighQuality);
            Gdiplus::Pen aaPen(GdiColor(color, 235), std::max<Gdiplus::REAL>(1.25f, S(1.0f)));
            aaPen.SetStartCap(Gdiplus::LineCapRound);
            aaPen.SetEndCap(Gdiplus::LineCapRound);
            aaPen.SetLineJoin(Gdiplus::LineJoinRound);

            if (!g_continuousRead && (g_viewMode == 1 || g_viewMode == 2))
            {
                // These two glyphs follow the supplied Alibaba vector icons,
                // scaled into the same compact toolbar box as the other icons.
                const float glyphWidth = S(14.0f);
                const float glyphHeight = S(13.0f);
                const float originX = static_cast<float>(r.left) + S(4.0f);
                const float originY = static_cast<float>(cy) - glyphHeight * 0.5f;
                auto point = [&](float x, float y)
                {
                    return Gdiplus::PointF(
                        originX + x * glyphWidth / 1024.0f,
                        originY + y * glyphHeight / 1024.0f);
                };

                if (g_viewMode == 1)
                {
                    // 双页-01.svg contains two symmetric page contours. Keep
                    // the original two contours separate so no extra outer
                    // frame changes the supplied silhouette.
                    Gdiplus::GraphicsPath leftPage;
                    leftPage.StartFigure();
                    leftPage.AddLine(point(96.0f, 194.816f), point(96.0f, 829.12f));
                    leftPage.AddBezier(point(96.0f, 829.12f), point(96.0f, 848.32f),
                        point(111.616f, 864.0f), point(130.816f, 864.0f));
                    leftPage.AddLine(point(130.816f, 864.0f), point(480.0f, 864.0f));
                    leftPage.AddLine(point(480.0f, 864.0f), point(480.0f, 261.696f));
                    leftPage.AddBezier(point(480.0f, 261.696f), point(480.0f, 205.504f),
                        point(434.496f, 160.0f), point(378.304f, 160.0f));
                    leftPage.AddLine(point(378.304f, 160.0f), point(130.816f, 160.0f));
                    leftPage.AddBezier(point(130.816f, 160.0f), point(111.616f, 160.0f),
                        point(96.0f, 175.616f), point(96.0f, 194.816f));
                    leftPage.CloseFigure();
                    g.DrawPath(&aaPen, &leftPage);

                    Gdiplus::GraphicsPath rightPage;
                    rightPage.StartFigure();
                    rightPage.AddLine(point(544.0f, 261.696f), point(544.0f, 864.0f));
                    rightPage.AddLine(point(544.0f, 864.0f), point(893.184f, 864.0f));
                    rightPage.AddBezier(point(893.184f, 864.0f), point(912.384f, 864.0f),
                        point(927.872f, 848.32f), point(927.872f, 829.12f));
                    rightPage.AddLine(point(927.872f, 829.12f), point(927.872f, 194.816f));
                    rightPage.AddBezier(point(927.872f, 194.816f), point(927.872f, 175.616f),
                        point(912.384f, 160.0f), point(893.12f, 160.0f));
                    rightPage.AddLine(point(893.12f, 160.0f), point(645.696f, 160.0f));
                    rightPage.AddBezier(point(645.696f, 160.0f), point(589.504f, 160.0f),
                        point(544.0f, 205.504f), point(544.0f, 261.696f));
                    rightPage.CloseFigure();
                    g.DrawPath(&aaPen, &rightPage);
                }
                else
                {
                    // 书本.svg: rounded book frame, center rule, and the four
                    // right-page text rules from the supplied icon.
                    Gdiplus::GraphicsPath book;
                    float l = 65.8f;
                    float t = 64.2f;
                    float rr = 958.2f;
                    float b = 959.8f;
                    float radius = 97.0f;
                    float rectX = originX + l * glyphWidth / 1024.0f;
                    float rectY = originY + t * glyphHeight / 1024.0f;
                    float rectW = (rr - l) * glyphWidth / 1024.0f;
                    float rectH = (b - t) * glyphHeight / 1024.0f;
                    float radiusX = radius * glyphWidth / 1024.0f;
                    float radiusY = radius * glyphHeight / 1024.0f;
                    book.StartFigure();
                    book.AddArc(rectX, rectY, radiusX * 2.0f, radiusY * 2.0f, 180.0f, 90.0f);
                    book.AddLine(rectX + radiusX, rectY, rectX + rectW - radiusX, rectY);
                    book.AddArc(rectX + rectW - radiusX * 2.0f, rectY, radiusX * 2.0f, radiusY * 2.0f, 270.0f, 90.0f);
                    book.AddLine(rectX + rectW, rectY + radiusY, rectX + rectW, rectY + rectH - radiusY);
                    book.AddArc(rectX + rectW - radiusX * 2.0f, rectY + rectH - radiusY * 2.0f, radiusX * 2.0f, radiusY * 2.0f, 0.0f, 90.0f);
                    book.AddLine(rectX + rectW - radiusX, rectY + rectH, rectX + radiusX, rectY + rectH);
                    book.AddArc(rectX, rectY + rectH - radiusY * 2.0f, radiusX * 2.0f, radiusY * 2.0f, 90.0f, 90.0f);
                    book.AddLine(rectX, rectY + rectH - radiusY, rectX, rectY + radiusY);
                    book.CloseFigure();
                    g.DrawPath(&aaPen, &book);

                    g.DrawLine(&aaPen, point(451.13f, 185.21f), point(451.13f, 817.62f));
                    constexpr float lines[] = { 312.31f, 445.43f, 578.56f, 711.69f };
                    for (float y : lines)
                        g.DrawLine(&aaPen, point(557.58f, y), point(819.87f, y));
                }
                DrawDownCaret(dc, r.left + S(24), cy, color);
                return;
            }

            int size = S(12);
            int left = r.left + S(4);
            int top = cy - size / 2;
            Gdiplus::RectF box{
                static_cast<Gdiplus::REAL>(left) + S(0.5f),
                static_cast<Gdiplus::REAL>(top) + S(0.5f),
                static_cast<Gdiplus::REAL>(size) - S(1.0f),
                static_cast<Gdiplus::REAL>(size) - S(1.0f) };
            g.DrawRectangle(&aaPen, box.X, box.Y, box.Width, box.Height);

            float ix = box.X + S(3.0f);
            float iy = box.Y + S(3.0f);
            float iw = std::max(1.0f, box.Width - S(6.0f));
            float ih = std::max(1.0f, box.Height - S(6.0f));
            if (g_continuousRead)
            {
                g.DrawLine(&aaPen, ix, iy, ix + iw, iy);
                g.DrawLine(&aaPen, ix, iy + ih * 0.5f, ix + iw, iy + ih * 0.5f);
                g.DrawLine(&aaPen, ix, iy + ih, ix + iw, iy + ih);
            }
            else if (g_viewMode == 1)
            {
                float mid = box.X + box.Width * 0.5f;
                g.DrawLine(&aaPen, mid, box.Y + S(2.0f), mid, box.GetBottom() - S(2.0f));
                g.DrawLine(&aaPen, box.X + S(2.6f), iy + ih * 0.5f, mid - S(1.5f), iy + ih * 0.5f);
                g.DrawLine(&aaPen, mid + S(1.5f), iy + ih * 0.5f, box.GetRight() - S(2.6f), iy + ih * 0.5f);
            }
            else if (g_viewMode == 2)
            {
                float mid = box.X + box.Width * 0.5f;
                g.DrawLine(&aaPen, mid, box.Y + S(2.0f), mid, box.GetBottom() - S(2.0f));
                g.DrawLine(&aaPen, box.X + S(2.2f), box.Y + S(3.0f), mid - S(1.2f), box.Y + S(4.0f));
                g.DrawLine(&aaPen, mid + S(1.2f), box.Y + S(4.0f), box.GetRight() - S(2.2f), box.Y + S(3.0f));
                g.DrawLine(&aaPen, box.X + S(2.2f), box.GetBottom() - S(3.0f), mid - S(1.2f), box.GetBottom() - S(2.0f));
                g.DrawLine(&aaPen, mid + S(1.2f), box.GetBottom() - S(2.0f), box.GetRight() - S(2.2f), box.GetBottom() - S(3.0f));
            }
            else
            {
                g.DrawLine(&aaPen, ix, iy + ih * 0.5f, ix + iw, iy + ih * 0.5f);
            }
            DrawDownCaret(dc, static_cast<int>(left + S(20.0f)), cy, color);
            return;
        }
        case StatusIcon::Actual:
        case StatusIcon::FitPage:
        case StatusIcon::FitWidth:
        case StatusIcon::FitContent:
        case StatusIcon::CustomZoom:
        {
            int size = S(12);
            int left = r.left + S(4);
            int top = cy - size / 2;
            RECT iconBox{ left, top, left + size, top + size };
            SelectObject(dc, oldBrush);
            SelectObject(dc, oldPen);
            DeleteObject(pen);

            Gdiplus::Graphics g(dc);
            g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
            Gdiplus::Pen aaPen(GdiColor(color), std::max<Gdiplus::REAL>(1.25f, S(1.05f)));
            aaPen.SetStartCap(Gdiplus::LineCapRound);
            aaPen.SetEndCap(Gdiplus::LineCapRound);
            aaPen.SetLineJoin(Gdiplus::LineJoinRound);
            Gdiplus::RectF page{
                static_cast<Gdiplus::REAL>(iconBox.left) + S(1.0f),
                static_cast<Gdiplus::REAL>(iconBox.top) + S(0.8f),
                static_cast<Gdiplus::REAL>(iconBox.right - iconBox.left) - S(2.0f),
                static_cast<Gdiplus::REAL>(iconBox.bottom - iconBox.top) - S(1.6f) };

            if (icon == StatusIcon::Actual)
            {
                g.DrawRectangle(&aaPen, page.X, page.Y, page.Width, page.Height);
                HFONT f = Font(5);
                HGDIOBJ oldFont = SelectObject(dc, f);
                Text(dc, L"1:1", iconBox, DT_CENTER | DT_VCENTER | DT_SINGLELINE, color);
                SelectObject(dc, oldFont);
                DeleteObject(f);
            }
            else if (icon == StatusIcon::FitPage)
            {
                g.DrawRectangle(&aaPen, page.X, page.Y, page.Width, page.Height);
                g.DrawLine(&aaPen, page.X + S(2.0f), page.Y + S(2.0f), page.X + S(5.0f), page.Y + S(2.0f));
                g.DrawLine(&aaPen, page.GetRight() - S(2.0f), page.GetBottom() - S(2.0f), page.GetRight() - S(5.0f), page.GetBottom() - S(2.0f));
            }
            else if (icon == StatusIcon::FitWidth)
            {
                g.DrawRectangle(&aaPen, page.X, page.Y, page.Width, page.Height);
                float mid = (page.Y + page.GetBottom()) * 0.5f;
                g.DrawLine(&aaPen, page.X - S(1.2f), mid, page.X + S(3.0f), mid);
                g.DrawLine(&aaPen, page.GetRight() + S(1.2f), mid, page.GetRight() - S(3.0f), mid);
            }
            else if (icon == StatusIcon::FitContent)
            {
                g.DrawRectangle(&aaPen, page.X, page.Y, page.Width, page.Height);
                Gdiplus::RectF content{ page.X + S(2.8f), page.Y + S(2.7f), page.Width - S(5.6f), page.Height - S(5.4f) };
                g.DrawRectangle(&aaPen, content.X, content.Y, content.Width, content.Height);
            }
            else
            {
                float mx = (iconBox.left + iconBox.right) * 0.5f - S(1.4f);
                float my = (iconBox.top + iconBox.bottom) * 0.5f - S(1.3f);
                g.DrawEllipse(&aaPen, mx - S(4.5f), my - S(4.5f), S(9.0f), S(9.0f));
                g.DrawLine(&aaPen, mx + S(3.1f), my + S(3.1f), mx + S(7.0f), my + S(7.0f));
                g.DrawLine(&aaPen, mx - S(2.6f), my, mx + S(2.6f), my);
            }
            DrawDownCaret(dc, static_cast<int>(left + S(20.0f)), cy, color);
            return;
        }
        case StatusIcon::ZoomOut:
            MoveToEx(dc, cx - S(6), cy, nullptr);
            LineTo(dc, cx + S(6), cy);
            break;
        case StatusIcon::ZoomIn:
            MoveToEx(dc, cx - S(6), cy, nullptr);
            LineTo(dc, cx + S(6), cy);
            MoveToEx(dc, cx, cy - S(6), nullptr);
            LineTo(dc, cx, cy + S(6));
            break;
        case StatusIcon::Fullscreen:
        {
            int d = S(6);
            int l = cx - d, t = cy - d, rr = cx + d, b = cy + d;
            MoveToEx(dc, l, t + S(4), nullptr); LineTo(dc, l, t); LineTo(dc, l + S(4), t);
            MoveToEx(dc, rr - S(4), t, nullptr); LineTo(dc, rr, t); LineTo(dc, rr, t + S(4));
            MoveToEx(dc, rr, b - S(4), nullptr); LineTo(dc, rr, b); LineTo(dc, rr - S(4), b);
            MoveToEx(dc, l + S(4), b, nullptr); LineTo(dc, l, b); LineTo(dc, l, b - S(4));
            break;
        }
        case StatusIcon::Pin:
        {
            HPEN greenPen = CreatePen(PS_SOLID, std::max(1, S(1)), color);
            SelectObject(dc, greenPen);
            MoveToEx(dc, cx - S(5), cy - S(6), nullptr);
            LineTo(dc, cx + S(5), cy - S(6));
            MoveToEx(dc, cx - S(3), cy - S(6), nullptr);
            LineTo(dc, cx - S(3), cy + S(1));
            LineTo(dc, cx + S(3), cy + S(1));
            LineTo(dc, cx + S(3), cy - S(6));
            MoveToEx(dc, cx, cy + S(1), nullptr);
            LineTo(dc, cx, cy + S(8));
            SelectObject(dc, pen);
            DeleteObject(greenPen);
            break;
        }
        }

        SelectObject(dc, oldBrush);
        SelectObject(dc, oldPen);
        DeleteObject(pen);
    }

    void DrawSideTabIcon(HDC dc, RECT r, SideTabIcon icon, COLORREF color)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        COLORREF iconColor = color;
        Gdiplus::Pen pen(GdiColor(iconColor), std::max<Gdiplus::REAL>(1.55f, S(1)));
        pen.SetStartCap(Gdiplus::LineCapRound);
        pen.SetEndCap(Gdiplus::LineCapRound);
        pen.SetLineJoin(Gdiplus::LineJoinRound);
        Gdiplus::SolidBrush brush(GdiColor(iconColor));
        float cx = (r.left + r.right) * 0.5f;
        float cy = (r.top + r.bottom) * 0.5f;

        switch (icon)
        {
        case SideTabIcon::Outline:
        {
            Gdiplus::RectF outer{ cx - S(9.5f), cy - S(9.5f), S(19.0f), S(19.0f) };
            DrawGdiRoundRect(g, pen, outer, S(3.2f));
            float ys[] = { cy - S(5.6f), cy, cy + S(5.6f) };
            for (float y : ys)
            {
                Gdiplus::RectF dot{ cx - S(5.8f), y - S(1.1f), S(2.2f), S(2.2f) };
                FillGdiRoundRect(g, brush, dot, S(0.7f));
                Gdiplus::RectF bar{ cx - S(0.6f), y - S(0.9f), S(7.8f), S(1.8f) };
                FillGdiRoundRect(g, brush, bar, S(1.0f));
            }
            break;
        }
        case SideTabIcon::Thumbnails:
        {
            float s = S(6.8f);
            float gap = S(1.3f);
            DrawGdiRoundRect(g, pen, { cx - gap - s, cy - gap - s, s, s }, S(2.2f));
            DrawGdiRoundRect(g, pen, { cx + gap, cy - gap - s, s, s }, S(2.2f));
            DrawGdiRoundRect(g, pen, { cx - gap - s, cy + gap, s, s }, S(2.2f));
            DrawGdiRoundRect(g, pen, { cx + gap, cy + gap, s, s }, S(2.2f));
            break;
        }
        case SideTabIcon::Search:
        {
            g.DrawEllipse(&pen, cx - S(7.4f), cy - S(7.4f), S(13.0f), S(13.0f));
            Gdiplus::Pen handle(GdiColor(iconColor), std::max<Gdiplus::REAL>(1.7f, S(1)));
            handle.SetStartCap(Gdiplus::LineCapRound);
            handle.SetEndCap(Gdiplus::LineCapRound);
            g.DrawLine(&handle, cx + S(4.8f), cy + S(4.8f), cx + S(10.0f), cy + S(10.0f));
            break;
        }
        case SideTabIcon::Notes:
        {
            constexpr float iconScale = 0.96f;
            auto scaled = [&](float value) { return S(value * iconScale); };
            float l = cx - scaled(8.8f);
            float t = cy - scaled(8.3f);
            float rr = cx + scaled(8.7f);
            float b = cy + scaled(8.7f);
            float corner = scaled(2.0f);

            Gdiplus::GraphicsPath noteFrame;
            noteFrame.StartFigure();
            noteFrame.AddLine(cx - scaled(3.6f), t, l + corner, t);
            noteFrame.AddBezier(l + corner, t, l + scaled(0.9f), t, l, t + scaled(0.9f), l, t + corner);
            noteFrame.AddLine(l, t + corner, l, b - corner);
            noteFrame.AddBezier(l, b - corner, l, b - scaled(0.9f), l + scaled(0.9f), b, l + corner, b);
            noteFrame.AddLine(l + corner, b, rr - corner, b);
            noteFrame.AddBezier(rr - corner, b, rr - scaled(0.9f), b, rr, b - scaled(0.9f), rr, b - corner);
            noteFrame.AddLine(rr, b - corner, rr, cy + scaled(1.8f));
            g.DrawPath(&pen, &noteFrame);

            float pencilCx = cx + S(1.0f);
            float pencilCy = cy - S(1.0f);
            // Points on each side mirror across the 45-degree pencil axis.
            Gdiplus::PointF pencil[] = {
                Gdiplus::PointF(pencilCx - scaled(5.8f), pencilCy + scaled(5.8f)),
                Gdiplus::PointF(pencilCx - scaled(4.2f), pencilCy + scaled(0.4f)),
                Gdiplus::PointF(pencilCx + scaled(4.6f), pencilCy - scaled(8.4f)),
                Gdiplus::PointF(pencilCx + scaled(8.4f), pencilCy - scaled(4.6f)),
                Gdiplus::PointF(pencilCx - scaled(0.4f), pencilCy + scaled(4.2f))
            };
            Gdiplus::GraphicsPath pencilPath;
            pencilPath.AddPolygon(pencil, static_cast<INT>(std::size(pencil)));
            g.DrawPath(&pen, &pencilPath);
            break;
        }
        }
    }

    void DrawNoteToolIcon(HDC dc, RECT r, int id, COLORREF color)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        g.SetPixelOffsetMode(Gdiplus::PixelOffsetModeHalf);
        Gdiplus::Pen pen(GdiColor(color), std::max<Gdiplus::REAL>(1.15f, S(1.0f)));
        pen.SetStartCap(Gdiplus::LineCapRound);
        pen.SetEndCap(Gdiplus::LineCapRound);
        pen.SetLineJoin(Gdiplus::LineJoinRound);
        Gdiplus::SolidBrush brush(GdiColor(color));

        float cx = (r.left + r.right) * 0.5f;
        float cy = (r.top + r.bottom) * 0.5f;
        float box = std::min<float>(static_cast<float>(r.right - r.left), static_cast<float>(r.bottom - r.top));
        float u = box / 28.0f;

        auto drawTree = [&](bool expand)
        {
            Gdiplus::RectF mark{ cx - 8.5f * u, cy - 8.5f * u, 17.0f * u, 17.0f * u };
            DrawGdiRoundRect(g, pen, mark, 3.0f * u);

            float dir = expand ? 1.0f : -1.0f;
            float topY = cy - 4.5f * u * dir;
            float midY = cy;
            float bottomY = cy + 4.5f * u * dir;
            float wing = 4.2f * u;

            g.DrawLine(&pen, cx - wing, topY, cx, midY);
            g.DrawLine(&pen, cx + wing, topY, cx, midY);
            g.DrawLine(&pen, cx - wing, midY, cx, bottomY);
            g.DrawLine(&pen, cx + wing, midY, cx, bottomY);
        };
        auto drawArrowBox = [&](bool next)
        {
            Gdiplus::RectF mark{ cx - 8.5f * u, cy - 8.5f * u, 17.0f * u, 17.0f * u };
            DrawGdiRoundRect(g, pen, mark, 3.0f * u);
            float dir = next ? 1.0f : -1.0f;
            float ax = cx + dir * 4.0f * u;
            float bx = cx - dir * 3.5f * u;
            g.DrawLine(&pen, ax, cy, bx, cy - 5.0f * u);
            g.DrawLine(&pen, ax, cy, bx, cy + 5.0f * u);
            g.DrawLine(&pen, ax, cy, cx - dir * 5.0f * u, cy);
        };

        auto drawTrash = [&](bool badge)
        {
            float x = cx - 6.8f * u;
            float y = cy - 5.2f * u;
            Gdiplus::RectF body{ x, y, 13.6f * u, 13.0f * u };
            DrawGdiRoundRect(g, pen, body, 2.3f * u);
            g.DrawLine(&pen, x - 1.4f * u, y - 3.0f * u, x + 15.0f * u, y - 3.0f * u);
            g.DrawLine(&pen, cx - 3.2f * u, y - 5.8f * u, cx + 3.2f * u, y - 5.8f * u);
            g.DrawLine(&pen, cx - 2.8f * u, y - 5.8f * u, cx - 4.4f * u, y - 3.0f * u);
            g.DrawLine(&pen, cx + 2.8f * u, y - 5.8f * u, cx + 4.4f * u, y - 3.0f * u);
            g.DrawLine(&pen, cx - 3.4f * u, y + 2.0f * u, cx - 3.4f * u, y + 9.2f * u);
            g.DrawLine(&pen, cx, y + 2.0f * u, cx, y + 9.2f * u);
            g.DrawLine(&pen, cx + 3.4f * u, y + 2.0f * u, cx + 3.4f * u, y + 9.2f * u);

            if (badge)
            {
                Gdiplus::SolidBrush red(GdiColor(RGB(220, 77, 77)));
                Gdiplus::Pen white(GdiColor(RGB(255, 255, 255)), std::max<Gdiplus::REAL>(1.1f, S(0.9f)));
                white.SetStartCap(Gdiplus::LineCapRound);
                white.SetEndCap(Gdiplus::LineCapRound);
                Gdiplus::RectF dot{ cx + 3.3f * u, cy - 10.4f * u, 8.4f * u, 8.4f * u };
                g.FillEllipse(&red, dot);
                g.DrawLine(&white, dot.X + 2.5f * u, dot.Y + 2.5f * u, dot.X + 5.9f * u, dot.Y + 5.9f * u);
                g.DrawLine(&white, dot.X + 5.9f * u, dot.Y + 2.5f * u, dot.X + 2.5f * u, dot.Y + 5.9f * u);
            }
        };

        if (id == CmdNoteExpandAll) drawTree(!g_collapsedAnnotationPages.empty());
        else if (id == CmdNoteCollapseAll) drawTree(false);
        else if (id == CmdNotePrev) drawArrowBox(false);
        else if (id == CmdNoteNext) drawArrowBox(true);
        else if (id == CmdNoteDelete) drawTrash(false);
        else if (id == CmdNoteDeleteAll) drawTrash(true);
    }

    bool HitNoteToolButton(int x, int y, int& command, RECT* outRect = nullptr)
    {
        command = 0;
        if (g_sideMode != 3 || !SidebarVisible()) return false;
        int buttonTop = g_sidebar.top + S(33);
        int buttonSize = S(30);
        int buttonGap = S(3);
        int groupGap = S(11);
        int buttonLeft = g_sidebar.left + S(10);
        int available = std::max<int>(1, static_cast<int>(g_sidebar.right - g_sidebar.left) - S(20));
        int desired = buttonSize * 5 + buttonGap * 4 + groupGap * 2 + S(2);
        if (desired > available)
            buttonSize = std::max(S(24), (available - buttonGap * 4 - groupGap * 2 - S(2)) / 5);
        int ids[] = { CmdNoteExpandAll, CmdNotePrev, CmdNoteNext, CmdNoteDelete, CmdNoteDeleteAll };
        int bx = buttonLeft;
        for (int i = 0; i < static_cast<int>(std::size(ids)); ++i)
        {
            RECT r{ bx, buttonTop, bx + buttonSize, buttonTop + buttonSize };
            if (Hit(r, x, y))
            {
                command = ids[i];
                if (outRect) *outRect = r;
                return true;
            }
            bx += buttonSize;
            if (i == 0 || i == 2) bx += buttonGap + groupGap;
            else bx += buttonGap;
        }
        return false;
    }

    void DrawFilledCircle(HDC dc, int cx, int cy, float radius, COLORREF color)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        Gdiplus::SolidBrush brush(GdiColor(color));
        float d = radius * 2.0f;
        g.FillEllipse(&brush, static_cast<float>(cx) - radius, static_cast<float>(cy) - radius, d, d);
    }
    void DrawSearchGlyph(HDC dc, RECT r, COLORREF color)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        Gdiplus::Pen pen(GdiColor(color), std::max<Gdiplus::REAL>(1.25f, S(1.0f)));
        pen.SetStartCap(Gdiplus::LineCapRound);
        pen.SetEndCap(Gdiplus::LineCapRound);
        float cx = (r.left + r.right) * 0.5f - S(1.3f);
        float cy = (r.top + r.bottom) * 0.5f - S(1.0f);
        float rad = S(6.2f);
        g.DrawEllipse(&pen, cx - rad, cy - rad, rad * 2.0f, rad * 2.0f);
        g.DrawLine(&pen, cx + S(4.5f), cy + S(4.5f), cx + S(9.4f), cy + S(9.4f));
    }
    void DrawSoftGlowRect(HDC dc, RECT r, int radius, COLORREF color, BYTE maxAlpha)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        g.SetPixelOffsetMode(Gdiplus::PixelOffsetModeHighQuality);
        for (int i = 5; i >= 1; --i)
        {
            float spread = S(static_cast<float>(i));
            BYTE alpha = static_cast<BYTE>(maxAlpha * (6 - i) / 18);
            Gdiplus::Pen pen(GdiColor(color, alpha), std::max<Gdiplus::REAL>(1.0f, S(1.0f)));
            pen.SetLineJoin(Gdiplus::LineJoinRound);
            Gdiplus::RectF rr{
                static_cast<Gdiplus::REAL>(r.left) - spread + 0.5f,
                static_cast<Gdiplus::REAL>(r.top) - spread + 0.5f,
                static_cast<Gdiplus::REAL>(r.right - r.left) + spread * 2.0f - 1.0f,
                static_cast<Gdiplus::REAL>(r.bottom - r.top) + spread * 2.0f - 1.0f };
            DrawGdiRoundRect(g, pen, rr, S(static_cast<float>(radius)) + spread);
        }
    }

    void DrawSearchIconButton(HDC dc, int id, RECT hotRect, RECT iconRect, void(*drawIcon)(HDC, RECT, COLORREF), const std::wstring& tip)
    {
        bool hovered = g_hasHoverButton && EqualRect(&g_hoverButtonRect, &hotRect);
        bool pressed = g_hasPressedButton && EqualRect(&g_pressedButtonRect, &hotRect);
        if (hovered || pressed)
        {
            COLORREF fill = pressed
                ? MixColor(T().panel2, T().accent, IsDarkTheme() ? 0.24 : 0.14)
                : MixColor(T().panel2, T().paper, IsDarkTheme() ? 0.18 : 0.48);
            COLORREF line = pressed ? MixColor(T().line, T().accent, 0.34) : MixColor(T().line, T().text, 0.08);
            RoundFill(dc, hotRect, S(6), fill, line);
        }
        AddButton(id, hotRect, L"", tip);
        COLORREF iconColor = pressed ? T().accent : (hovered ? MixColor(T().muted, T().accent, 0.28) : T().muted);
        drawIcon(dc, iconRect, iconColor);
    }



    void DrawGearGlyph(HDC dc, RECT r, COLORREF color)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        Gdiplus::Pen pen(GdiColor(color), std::max<Gdiplus::REAL>(1.05f, S(0.9f)));
        pen.SetStartCap(Gdiplus::LineCapRound);
        pen.SetEndCap(Gdiplus::LineCapRound);
        pen.SetLineJoin(Gdiplus::LineJoinRound);
        float cx = (r.left + r.right) * 0.5f;
        float cy = (r.top + r.bottom) * 0.5f;
        float outer = S(5.8f);
        float inner = S(2.3f);
        for (int i = 0; i < 8; ++i)
        {
            double a = i * 3.14159265358979323846 / 4.0;
            float x1 = cx + std::cos(a) * S(7.5f);
            float y1 = cy + std::sin(a) * S(7.5f);
            float x2 = cx + std::cos(a) * S(6.25f);
            float y2 = cy + std::sin(a) * S(6.25f);
            g.DrawLine(&pen, x1, y1, x2, y2);
        }
        g.DrawEllipse(&pen, cx - outer, cy - outer, outer * 2.0f, outer * 2.0f);
        g.DrawEllipse(&pen, cx - inner, cy - inner, inner * 2.0f, inner * 2.0f);
    }

    void DrawCloseGlyph(HDC dc, RECT r, COLORREF color)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        Gdiplus::Pen pen(GdiColor(color), std::max<Gdiplus::REAL>(1.22f, S(0.92f)));
        pen.SetStartCap(Gdiplus::LineCapRound);
        pen.SetEndCap(Gdiplus::LineCapRound);
        float cx = (r.left + r.right) * 0.5f;
        float cy = (r.top + r.bottom) * 0.5f;
        float d = S(3.45f);
        g.DrawLine(&pen, cx - d, cy - d, cx + d, cy + d);
        g.DrawLine(&pen, cx + d, cy - d, cx - d, cy + d);
    }

    void DrawPlusGlyph(HDC dc, RECT r, COLORREF color)
    {
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        Gdiplus::Pen pen(GdiColor(color), std::max<Gdiplus::REAL>(1.6f, S(1.25f)));
        pen.SetStartCap(Gdiplus::LineCapRound);
        pen.SetEndCap(Gdiplus::LineCapRound);
        float cx = (r.left + r.right) * 0.5f;
        float cy = (r.top + r.bottom) * 0.5f;
        float d = S(5.4f);
        g.DrawLine(&pen, cx - d, cy, cx + d, cy);
        g.DrawLine(&pen, cx, cy - d, cx, cy + d);
    }

    void DrawSearchActionButton(HDC dc, int id, RECT r, const std::wstring& label)
    {
        bool hovered = g_hasHoverButton && EqualRect(&g_hoverButtonRect, &r);
        bool pressed = g_hasPressedButton && EqualRect(&g_pressedButtonRect, &r);
        bool primary = id == CmdSearchRun;
        COLORREF idleFill = primary ? MixColor(T().paper, T().accent, IsDarkTheme() ? 0.10 : 0.055) : T().paper;
        COLORREF fill = pressed
            ? MixColor(T().panel2, T().accent, IsDarkTheme() ? 0.24 : 0.14)
            : (hovered ? MixColor(idleFill, T().accent, IsDarkTheme() ? 0.10 : 0.06) : idleFill);
        COLORREF line = pressed
            ? MixColor(T().line, T().accent, 0.38)
            : (hovered || primary ? MixColor(T().line, T().accent, primary ? 0.16 : 0.10) : T().line);
        RoundFill(dc, r, S(6), fill, line);
        HFONT f = Font(9);
        HGDIOBJ oldFont = SelectObject(dc, f);
        COLORREF textColor = pressed || primary ? MixColor(T().text, T().accent, primary ? 0.32 : 0.18) : T().text;
        Text(dc, label, r, DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS, textColor);
        SelectObject(dc, oldFont);
        DeleteObject(f);
    }

    void DrawHighlightedSnippet(HDC dc, SearchResult const& result, RECT textRect, COLORREF textColor)
    {
        std::wstring const& snippet = result.snippet.empty() ? result.title : result.snippet;
        std::wstring before = snippet.substr(0, std::clamp(result.highlightStart, 0, static_cast<int>(snippet.size())));
        std::wstring hit = g_searchLastQuery.empty() ? g_searchQuery : g_searchLastQuery;
        if (hit.empty() || result.highlightLength <= 0)
        {
            Text(dc, snippet, textRect, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS, textColor);
            return;
        }
        SIZE beforeSize{};
        GetTextExtentPoint32W(dc, before.c_str(), static_cast<int>(before.size()), &beforeSize);
        SIZE hitSize{};
        GetTextExtentPoint32W(dc, hit.c_str(), static_cast<int>(hit.size()), &hitSize);

        RECT prefix{ textRect.left, textRect.top, textRect.right, textRect.bottom };
        Text(dc, before, prefix, DT_LEFT | DT_VCENTER | DT_SINGLELINE, textColor);

        int hx = textRect.left + beforeSize.cx;
        RECT mark{ hx - S(2), textRect.top + S(6), hx + hitSize.cx + S(4), textRect.bottom - S(6) };
        COLORREF markFill = IsDarkTheme() ? MixColor(T().panel2, RGB(245, 164, 72), 0.24) : RGB(255, 250, 235);
        COLORREF markLine = IsDarkTheme() ? MixColor(T().accent, RGB(245, 164, 72), 0.55) : RGB(239, 174, 70);
        RoundFill(dc, mark, S(4), markFill, markLine);
        RECT hitText{ hx, textRect.top, hx + hitSize.cx + S(2), textRect.bottom };
        Text(dc, hit, hitText, DT_LEFT | DT_VCENTER | DT_SINGLELINE, textColor);

        int suffixStart = std::min<int>(static_cast<int>(snippet.size()), result.highlightStart + result.highlightLength);
        std::wstring suffix = snippet.substr(static_cast<size_t>(suffixStart));
        RECT suffixRect{ hitText.right + S(2), textRect.top, textRect.right, textRect.bottom };
        Text(dc, suffix, suffixRect, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS, textColor);
    }

    void PaintHoverTip(HDC dc, RECT client)
    {
        if (!g_hasHoverTip || g_hoverTip.empty()) return;
        HFONT f = Font(9);
        HGDIOBJ oldFont = SelectObject(dc, f);
        SIZE sz{};
        GetTextExtentPoint32W(dc, g_hoverTip.c_str(), static_cast<int>(g_hoverTip.size()), &sz);
        int maxW = std::max<int>(S(80), static_cast<int>(client.right) - S(16));
        int w = std::min<int>(static_cast<int>(sz.cx) + S(20), maxW);
        int h = S(28);
        int x = (g_hoverTipRect.left + g_hoverTipRect.right - w) / 2;
        x = std::clamp<int>(x, S(8), std::max<int>(S(8), static_cast<int>(client.right) - w - S(8)));
        int y = g_hoverTipIsPdfLink ? g_hoverTipRect.bottom + S(6) : g_hoverTipRect.top - h - S(9);
        if (g_hoverTipIsPdfLink && y + h > client.bottom - S(8))
            y = g_hoverTipRect.top - h - S(6);
        else if (!g_hoverTipIsPdfLink && y < S(8))
            y = g_hoverTipRect.bottom + S(9);
        y = std::clamp<int>(y, S(8), static_cast<int>(client.bottom) - h - S(8));
        RECT box{ x, y, x + w, y + h };
        // Keep the actual painted bounds separate from the button/link anchor.
        // Zoom cleanup must invalidate this box, otherwise only the anchor is
        // repainted and the old tooltip can remain as a clipped half-panel.
        g_hoverTipPaintRect = box;
        COLORREF fillColor = g_hoverTipIsPdfLink
            ? (IsDarkTheme() ? MixColor(T().panel2, T().accent, 0.12) : RGB(255, 250, 222))
            : T().panel2;
        COLORREF lineColor = g_hoverTipIsPdfLink ? MixColor(fillColor, T().line, IsDarkTheme() ? 0.55 : 0.42) : T().line;
        RoundFill(dc, box, g_hoverTipIsPdfLink ? S(5) : S(9), fillColor, lineColor);
        RECT textBox{ box.left + S(10), box.top, box.right - S(10), box.bottom };
        Text(dc, g_hoverTip, textBox,
            (g_hoverTipIsPdfLink ? DT_LEFT : DT_CENTER) | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS,
            T().text);
        SelectObject(dc, oldFont);
        DeleteObject(f);
    }

