    std::filesystem::path RoamingStorageDir()
    {
        PWSTR appData = nullptr;
        if (FAILED(SHGetKnownFolderPath(FOLDERID_RoamingAppData, 0, nullptr, &appData)))
            return ExeDir() / L"Data";
        std::filesystem::path value = appData;
        CoTaskMemFree(appData);
        return value / L"QingYuePDF";
    }

    bool SameStoragePath(std::filesystem::path const& left, std::filesystem::path const& right)
    {
        std::error_code leftError, rightError;
        auto leftPath = std::filesystem::absolute(left, leftError).lexically_normal().wstring();
        auto rightPath = std::filesystem::absolute(right, rightError).lexically_normal().wstring();
        return !leftError && !rightError && _wcsicmp(leftPath.c_str(), rightPath.c_str()) == 0;
    }

    bool DirectoryIsWritable(std::filesystem::path const& directory)
    {
        std::error_code ec;
        std::filesystem::create_directories(directory, ec);
        if (ec) return false;
        auto probe = directory / (L".quietpdf-write-test-" + std::to_wstring(GetCurrentProcessId()) + L"-" + std::to_wstring(GetTickCount64()));
        HANDLE file = CreateFileW(probe.c_str(), GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
            nullptr, CREATE_NEW, FILE_ATTRIBUTE_TEMPORARY | FILE_FLAG_DELETE_ON_CLOSE, nullptr);
        if (file == INVALID_HANDLE_VALUE) return false;
        CloseHandle(file);
        return true;
    }

    bool FileIsNewerOrMissing(std::filesystem::path const& source, std::filesystem::path const& target)
    {
        std::error_code sourceError, targetError;
        if (!std::filesystem::exists(target, targetError)) return true;
        auto sourceTime = std::filesystem::last_write_time(source, sourceError);
        auto targetTime = std::filesystem::last_write_time(target, targetError);
        return !sourceError && !targetError && sourceTime > targetTime;
    }

    bool MigrateStorageFile(std::filesystem::path const& source, std::filesystem::path const& target)
    {
        std::error_code ec;
        if (!std::filesystem::is_regular_file(source, ec)) return true;
        std::filesystem::create_directories(target.parent_path(), ec);
        if (ec) return false;
        if (FileIsNewerOrMissing(source, target))
        {
            ec.clear();
            std::filesystem::copy_file(source, target, std::filesystem::copy_options::overwrite_existing, ec);
            if (ec) return false;
        }
        ec.clear();
        std::filesystem::remove(source, ec);
        return !ec;
    }

    bool MigrateStorageDirectory(std::filesystem::path const& source, std::filesystem::path const& target)
    {
        std::error_code ec;
        if (!std::filesystem::is_directory(source, ec)) return true;
        std::filesystem::create_directories(target, ec);
        if (ec) return false;
        bool copied = true;
        for (std::filesystem::recursive_directory_iterator it(source, ec), end; !ec && it != end; it.increment(ec))
        {
            auto relative = std::filesystem::relative(it->path(), source, ec);
            if (ec) { copied = false; break; }
            auto destination = target / relative;
            if (it->is_directory(ec))
            {
                std::filesystem::create_directories(destination, ec);
                if (ec) { copied = false; break; }
            }
            else if (it->is_regular_file(ec) && FileIsNewerOrMissing(it->path(), destination))
            {
                std::filesystem::create_directories(destination.parent_path(), ec);
                if (!ec) std::filesystem::copy_file(it->path(), destination, std::filesystem::copy_options::overwrite_existing, ec);
                if (ec) { copied = false; break; }
            }
        }
        if (!copied || ec) return false;
        std::filesystem::remove_all(source, ec);
        return !ec;
    }

    struct AppStoragePaths
    {
        std::filesystem::path data;
        std::filesystem::path homeThumbs;
    };

    AppStoragePaths const& StoragePaths()
    {
        static const AppStoragePaths paths = []
        {
            auto roaming = RoamingStorageDir();
            AppStoragePaths selected{ ExeDir() / L"Data", ExeDir() / L"Cache" / L"HomeThumbs" };
            auto roamingFallback = [&]
            {
                DirectoryIsWritable(roaming);
                DirectoryIsWritable(roaming / L"thumbs");
                return AppStoragePaths{ roaming, roaming / L"thumbs" };
            };
            if (!DirectoryIsWritable(selected.data) || !DirectoryIsWritable(selected.homeThumbs))
                return roamingFallback();

            if (!SameStoragePath(selected.data, roaming))
            {
                if (!MigrateStorageFile(roaming / L"state.txt", selected.data / L"state.txt"))
                    return roamingFallback();
                MigrateStorageDirectory(roaming / L"thumbs", selected.homeThumbs);
                std::error_code ec;
                std::filesystem::remove(roaming, ec);
            }
            return selected;
        }();
        return paths;
    }

    std::filesystem::path StatePath()
    {
        return StoragePaths().data / L"state.txt";
    }

    std::vector<std::string> SplitTabLine(std::string const& text)
    {
        std::vector<std::string> parts;
        size_t start = 0;
        for (;;)
        {
            size_t tab = text.find('\t', start);
            if (tab == std::string::npos)
            {
                parts.push_back(text.substr(start));
                break;
            }
            parts.push_back(text.substr(start, tab - start));
            start = tab + 1;
        }
        return parts;
    }

    std::wstring FavoriteKindName(FavoriteKind kind)
    {
        switch (kind)
        {
        case FavoriteKind::Outline: return L"书签";
        case FavoriteKind::Text: return L"文本";
        case FavoriteKind::Image: return L"图片";
        default: return L"页面";
        }
    }

    std::wstring FavoriteTitleForPage(std::wstring const& path, int page, FavoriteKind kind)
    {
        return std::filesystem::path(path).filename().wstring() + L" · " + FavoriteKindName(kind) +
            L" · 第 " + std::to_wstring(std::max(1, page + 1)) + L" 页";
    }

    bool SameFavoritePosition(FavoriteItem const& a, FavoriteItem const& b)
    {
        if (_wcsicmp(a.path.c_str(), b.path.c_str()) != 0 || a.page != b.page || a.kind != b.kind) return false;
        if (a.kind == FavoriteKind::Page || a.kind == FavoriteKind::Outline)
            return true;
        if (a.hasNorm != b.hasNorm) return false;
        if (!a.hasNorm) return true;
        constexpr double epsilon = 0.0005;
        return std::abs(a.norm.x0 - b.norm.x0) < epsilon && std::abs(a.norm.y0 - b.norm.y0) < epsilon &&
            std::abs(a.norm.x1 - b.norm.x1) < epsilon && std::abs(a.norm.y1 - b.norm.y1) < epsilon;
    }

    std::wstring FavoritePathForState(std::wstring const& value)
    {
        std::wstring result = value;
        for (wchar_t& ch : result)
            if (ch == L'\t' || ch == L'\r' || ch == L'\n') ch = L' ';
        return result;
    }

    void SortRecent()
    {
        std::stable_sort(g_recent.begin(), g_recent.end(), [](RecentItem const& a, RecentItem const& b)
        {
            if (a.pinned != b.pinned) return a.pinned;
            if (a.pinned && b.pinned && a.pinnedAt != b.pinnedAt) return a.pinnedAt > b.pinnedAt;
            return a.openedAt > b.openedAt;
        });
    }

    bool HomeRecentMatches(RecentItem const& item)
    {
        if (g_homeSearchQuery.empty()) return true;
        std::wstring query = LowerCopy(g_homeSearchQuery);
        std::wstring name = LowerCopy(item.name);
        std::wstring path = LowerCopy(item.path);
        return name.find(query) != std::wstring::npos || path.find(query) != std::wstring::npos;
    }

    std::vector<int> FilteredHomeRecentIds()
    {
        std::vector<int> ids;
        ids.reserve(g_recent.size());
        for (int i = 0; i < static_cast<int>(g_recent.size()); ++i)
        {
            if (HomeRecentMatches(g_recent[static_cast<size_t>(i)])) ids.push_back(i);
        }
        return ids;
    }

    void LoadState()
    {
        std::ifstream in(StatePath(), std::ios::binary);
        std::vector<std::string> lines;
        std::string line;
        while (std::getline(in, line)) lines.push_back(line);
        bool themeSchema4 = std::find(lines.begin(), lines.end(), "themeSchema=4") != lines.end();
        bool themeSchema3 = std::find(lines.begin(), lines.end(), "themeSchema=3") != lines.end();
        bool themeSchema2 = std::find(lines.begin(), lines.end(), "themeSchema=2") != lines.end();
        auto decodeThemeIndex = [&](int savedTheme)
        {
            if (themeSchema4)
                return std::clamp(savedTheme, 0, static_cast<int>(std::size(g_themes)) - 1);
            if (themeSchema3)
            {
                switch (std::clamp(savedTheme, 0, 6))
                {
                case 1: return 1; // soft gray
                case 2: return 3; // eye-care beige
                case 3: return 5; // night black
                case 4: return 6; // graphite black
                case 5: return 4; // aurora green
                case 6: return 2; // warm mist gray
                default: return 0; // mica white
                }
            }
            if (themeSchema2)
            {
                switch (std::clamp(savedTheme, 0, 5))
                {
                case 1: return 3; // eye-care beige
                case 2: return 5; // night black
                case 3: return 6; // graphite black
                case 4: return 4; // aurora green
                case 5: return 1; // soft gray
                default: return 0; // mica white
                }
            }
            switch (savedTheme)
            {
            case 1: return 5; // legacy dark mica -> night black
            case 2: return 4; // legacy aurora -> aurora green
            case 3: return 6; // legacy graphite -> graphite black
            case 4: return 3; // legacy eye-care paper -> eye-care beige
            case 5: return 0; // legacy frosted mica -> mica white
            default: return 0;
            }
        };
        bool sawLastLightTheme = false;
        bool sawLastDarkTheme = false;
        for (auto const& line : lines)
        {
            if (line.rfind("theme=", 0) == 0)
            {
                int savedTheme = std::atoi(line.c_str() + 6);
                g_theme = decodeThemeIndex(savedTheme);
            }
            else if (line.rfind("lastLightTheme=", 0) == 0)
            {
                g_lastLightTheme = decodeThemeIndex(std::atoi(line.c_str() + 15));
                sawLastLightTheme = true;
            }
            else if (line.rfind("lastDarkTheme=", 0) == 0)
            {
                g_lastDarkTheme = decodeThemeIndex(std::atoi(line.c_str() + 14));
                sawLastDarkTheme = true;
            }
            else if (line.rfind("sidebar=", 0) == 0)
            {
                int savedSidebar = std::clamp(std::atoi(line.c_str() + 8), SidebarMinimumWidth(), S(520));
                if (savedSidebar == 280) savedSidebar = 520;
                g_sidebarWidth = g_sidebarTargetWidth = g_sidebarExpandedWidth = savedSidebar;
            }
            else if (line.rfind("outline=", 0) == 0)
            {
                int savedOutline = std::clamp(std::atoi(line.c_str() + 8), 9, 22);
                if (savedOutline == 11) savedOutline = 10;
                g_outlineFont = savedOutline;
            }
            else if (line.rfind("view=", 0) == 0) g_viewMode = std::clamp(std::atoi(line.c_str() + 5), 0, 2);
            else if (line.rfind("homeList=", 0) == 0) g_homeListView = std::atoi(line.c_str() + 9) != 0;
            else if (line.rfind("continuous=", 0) == 0) g_continuousRead = std::atoi(line.c_str() + 11) != 0;
            else if (line.rfind("statusPinned=", 0) == 0) g_statusPinned = std::atoi(line.c_str() + 13) != 0;
            else if (line.rfind("immersiveSidebar=", 0) == 0) g_lastImmersiveSidebarOpen = std::atoi(line.c_str() + 17) != 0;
            else if (line.rfind("lastSessionActive=", 0) == 0) g_lastSessionActive = std::atoi(line.c_str() + 18);
            else if (line.rfind("lastSessionTab=", 0) == 0)
            {
                auto parts = SplitTabLine(line.substr(15));
                if (parts.size() >= 4)
                {
                    LastSessionItem item;
                    item.page = std::max(1, std::atoi(parts[0].c_str()));
                    item.scrollY = std::max(0, std::atoi(parts[1].c_str()));
                    item.zoom = std::clamp(std::atof(parts[2].c_str()), 0.0833, 64.0);
                    if (parts.size() >= 5)
                    {
                        item.pageOffsetY = std::atoi(parts[4].c_str());
                        item.hasPageOffset = true;
                    }
                    if (parts.size() >= 6) item.sidebarScrollY = std::max(0, std::atoi(parts[5].c_str()));
                    if (parts.size() >= 7) item.selectedOutlineRow = std::atoi(parts[6].c_str());
                    if (parts.size() >= 8) item.sidebarRailOpen = std::atoi(parts[7].c_str()) != 0;
                    if (parts.size() >= 9) item.sidebarContentOpen = std::atoi(parts[8].c_str()) != 0;
                    if (parts.size() >= 10) item.hasSidebarState = std::atoi(parts[9].c_str()) != 0;
                    if (parts.size() >= 11) item.sidebarWidth = std::max(0, std::atoi(parts[10].c_str()));
                    item.path = FromUtf8(parts[3]);
                    if (!item.path.empty()) g_lastSessionTabs.push_back(item);
                }
            }
            else if (line.rfind("recent=", 0) == 0)
            {
                auto parts = SplitTabLine(line.substr(7));
                if (parts.size() >= 3)
                {
                    RecentItem item;
                    item.openedAt = std::atoll(parts[0].c_str());
                    item.page = std::atoi(parts[1].c_str());
                    item.path = FromUtf8(parts[2]);
                    item.name = std::filesystem::path(item.path).filename().wstring();
                    if (parts.size() >= 4) item.favorite = std::atoi(parts[3].c_str()) != 0;
                    if (parts.size() >= 5) item.pinned = std::atoi(parts[4].c_str()) != 0;
                    if (parts.size() >= 6) item.pinnedAt = std::atoll(parts[5].c_str());
                    if (parts.size() >= 7) item.sidebarScrollY = std::max(0, std::atoi(parts[6].c_str()));
                    if (parts.size() >= 8) item.selectedOutlineRow = std::atoi(parts[7].c_str());
                    if (parts.size() >= 9)
                    {
                        item.scrollY = std::max(0, std::atoi(parts[8].c_str()));
                        item.hasExactPosition = true;
                    }
                    if (parts.size() >= 10) item.zoom = std::clamp(std::atof(parts[9].c_str()), 0.0833, 64.0);
                    if (parts.size() >= 11) item.pageOffsetY = std::atoi(parts[10].c_str());
                    if (parts.size() >= 12) item.hasPageOffset = std::atoi(parts[11].c_str()) != 0;
                    if (parts.size() >= 13) item.sidebarRailOpen = std::atoi(parts[12].c_str()) != 0;
                    if (parts.size() >= 14) item.sidebarContentOpen = std::atoi(parts[13].c_str()) != 0;
                    if (parts.size() >= 15) item.hasSidebarState = std::atoi(parts[14].c_str()) != 0;
                    if (parts.size() >= 16) item.sidebarWidth = std::max(0, std::atoi(parts[15].c_str()));
                    g_recent.push_back(item);
                }
            }
            else if (line.rfind("favorite=", 0) == 0)
            {
                auto parts = SplitTabLine(line.substr(9));
                if (parts.size() >= 14)
                {
                    FavoriteItem item;
                    item.createdAt = std::atoll(parts[0].c_str());
                    item.page = std::max(0, std::atoi(parts[1].c_str()));
                    item.outlineRow = std::atoi(parts[2].c_str());
                    item.scrollY = std::max(0, std::atoi(parts[3].c_str()));
                    item.zoom = std::clamp(std::atof(parts[4].c_str()), 0.0833, 64.0);
                    item.pageOffsetY = std::atoi(parts[5].c_str());
                    item.hasPageOffset = std::atoi(parts[6].c_str()) != 0;
                    item.kind = static_cast<FavoriteKind>(std::clamp(std::atoi(parts[7].c_str()), 0, 3));
                    item.hasNorm = std::atoi(parts[8].c_str()) != 0;
                    item.norm.x0 = static_cast<float>(std::atof(parts[9].c_str()));
                    item.norm.y0 = static_cast<float>(std::atof(parts[10].c_str()));
                    item.norm.x1 = static_cast<float>(std::atof(parts[11].c_str()));
                    item.norm.y1 = static_cast<float>(std::atof(parts[12].c_str()));
                    item.path = FromUtf8(parts[13]);
                    if (parts.size() >= 15) item.title = FromUtf8(parts[14]);
                    if (!item.path.empty())
                    {
                        if (item.title.empty()) item.title = FavoriteTitleForPage(item.path, item.page, item.kind);
                        g_favorites.push_back(std::move(item));
                    }
                }
            }
        }
        SortRecent();
        if (!sawLastLightTheme && IsLightThemeIndex(g_theme)) g_lastLightTheme = g_theme;
        if (!sawLastDarkTheme && IsDarkThemeIndex(g_theme)) g_lastDarkTheme = g_theme;
        g_lastLightTheme = LastLightTheme();
        g_lastDarkTheme = LastDarkTheme();
        if (g_recent.size() > 80) g_recent.resize(80);
        if (g_lastSessionActive < 0 || g_lastSessionActive >= static_cast<int>(g_lastSessionTabs.size()))
            g_lastSessionActive = g_lastSessionTabs.empty() ? -1 : 0;
        g_favorites.erase(
            std::remove_if(g_favorites.begin(), g_favorites.end(),
                [](FavoriteItem const& item)
                {
                    return item.kind != FavoriteKind::Outline;
                }),
            g_favorites.end());
        if (g_favorites.size() > 200) g_favorites.resize(200);
    }

    void SaveState()
    {
        std::ofstream out(StatePath(), std::ios::binary | std::ios::trunc);
        out << "themeSchema=4\n";
        out << "theme=" << g_theme << "\n";
        out << "lastLightTheme=" << LastLightTheme() << "\n";
        out << "lastDarkTheme=" << LastDarkTheme() << "\n";
        out << "sidebar=" << std::max(g_sidebarExpandedWidth, g_sidebarWidth) << "\n";
        out << "outline=" << g_outlineFont << "\n";
        out << "view=" << g_viewMode << "\n";
        out << "homeList=" << (g_homeListView ? 1 : 0) << "\n";
        out << "continuous=" << (g_continuousRead ? 1 : 0) << "\n";
        out << "statusPinned=" << (g_statusPinned ? 1 : 0) << "\n";
        out << "immersiveSidebar=" << (g_lastImmersiveSidebarOpen ? 1 : 0) << "\n";
        out << "lastSessionActive=" << g_lastSessionActive << "\n";
        for (auto const& item : g_lastSessionTabs)
        {
            out << "lastSessionTab=" << item.page << '\t' << item.scrollY << '\t' << item.zoom << '\t'
                << ToUtf8(item.path) << '\t' << item.pageOffsetY << '\t' << item.sidebarScrollY << '\t'
                << item.selectedOutlineRow << '\t' << (item.sidebarRailOpen ? 1 : 0) << '\t'
                << (item.sidebarContentOpen ? 1 : 0) << '\t' << (item.hasSidebarState ? 1 : 0) << '\t'
                << item.sidebarWidth << "\n";
        }
        for (auto const& item : g_recent)
        {
            out << "recent=" << item.openedAt << '\t' << item.page << '\t' << ToUtf8(item.path) << '\t'
                << (item.favorite ? 1 : 0) << '\t' << (item.pinned ? 1 : 0) << '\t' << item.pinnedAt << '\t'
                << item.sidebarScrollY << '\t' << item.selectedOutlineRow << '\t'
                << item.scrollY << '\t' << item.zoom << '\t' << item.pageOffsetY << '\t'
                << (item.hasPageOffset ? 1 : 0) << '\t' << (item.sidebarRailOpen ? 1 : 0) << '\t'
                << (item.sidebarContentOpen ? 1 : 0) << '\t' << (item.hasSidebarState ? 1 : 0) << '\t'
                << item.sidebarWidth << "\n";
        }
        for (auto const& item : g_favorites)
        {
            out << "favorite=" << item.createdAt << '\t' << item.page << '\t' << item.outlineRow << '\t'
                << item.scrollY << '\t' << item.zoom << '\t' << item.pageOffsetY << '\t'
                << (item.hasPageOffset ? 1 : 0) << '\t' << static_cast<int>(item.kind) << '\t'
                << (item.hasNorm ? 1 : 0) << '\t' << item.norm.x0 << '\t' << item.norm.y0 << '\t'
                << item.norm.x1 << '\t' << item.norm.y1 << '\t'
                << ToUtf8(FavoritePathForState(item.path)) << '\t'
                << ToUtf8(FavoritePathForState(item.title)) << "\n";
        }
    }

    void DropTab(PdfTab& tab)
    {
        tab.textBoxes.clear();
        tab.textBoxesReady.clear();
        if (tab.renderSession)
            tab.renderSession.reset();
        else
        {
            if (tab.doc) g_pdf.dropDocument(tab.ctx, tab.doc);
            if (tab.ctx) g_pdf.dropContext(tab.ctx);
        }
        tab.doc = nullptr;
        tab.ctx = nullptr;
    }

    template <typename TMap>
    size_t ImageCacheBytes(TMap const& images)
    {
        size_t total = 0;
        for (auto const& entry : images) total += entry.second.CacheBytes();
        return total;
    }

