    int PageFromScroll(PdfTab const& tab, int scrollY)
    {
        if (tab.pageCount <= 0) return 0;
        EnsureLayoutCache(tab);
        int probe = scrollY + S(32);
        auto found = std::upper_bound(tab.layoutSpreadEnds.begin(), tab.layoutSpreadEnds.end(), probe);
        if (found == tab.layoutSpreadEnds.end()) return tab.layoutSpreadStarts.back();
        return tab.layoutSpreadStarts[static_cast<size_t>(found - tab.layoutSpreadEnds.begin())];
    }

    int OutlineTargetScrollY(PdfTab const& tab, OutlineItem const& item, int knownPage = -1, int knownPageTop = 0)
    {
        int page = std::clamp(item.page, 0, tab.pageCount - 1);
        int scroll = knownPage == page ? knownPageTop : SpreadTopScroll(tab, page);
        int start = FirstPageInSpread(page);
        int pageOffsetY = std::max(0, (SpreadHeight(tab, start) - PageH(tab, page)) / 2);
        double yPt = std::isfinite(item.yPt) ? item.yPt : 0.0;
        if (yPt < 0.0) yPt = 0.0;
        if (page >= 0 && page < static_cast<int>(tab.pages.size()))
            yPt = std::min(yPt, std::max(0.0, tab.pages[static_cast<size_t>(page)].heightPt - 1.0));
        int yOffset = static_cast<int>(yPt * tab.zoom * static_cast<double>(g_dpi) / 72.0 + 0.5);
        return std::max(0, scroll + pageOffsetY + yOffset - S(24));
    }

    bool OutlineRowVisible(PdfTab const& tab, int row)
    {
        if (row < 0 || row >= static_cast<int>(tab.outline.size())) return false;
        int depth = tab.outline[static_cast<size_t>(row)].depth;
        for (int i = row - 1; i >= 0 && depth > 0; --i)
        {
            int parentDepth = tab.outline[static_cast<size_t>(i)].depth;
            if (parentDepth < depth)
            {
                if (g_collapsedOutlineRows.find(i) != g_collapsedOutlineRows.end()) return false;
                depth = parentDepth;
            }
        }
        return true;
    }

    int OutlineRowFromScroll(PdfTab const& tab, int scrollY)
    {
        if (tab.outline.empty() || tab.pageCount <= 0) return -1;
        int probe = scrollY + S(48);
        int best = -1;
        int lastTarget = std::numeric_limits<int>::min();
        for (int i = 0; i < static_cast<int>(tab.outline.size()); ++i)
        {
            if (!OutlineRowVisible(tab, i)) continue;
            int target = OutlineTargetScrollY(tab, tab.outline[static_cast<size_t>(i)]);
            // PDF outlines are normally ordered by destination, but malformed
            // or lazily resolved destinations can briefly report an earlier
            // target for a later row. Keep the progress sequence monotonic so
            // scrolling cannot make adjacent rows fight over the selection.
            target = std::max(target, lastTarget);
            lastTarget = target;
            if (target <= probe) best = i;
        }
        return best;
    }

    void KeepOutlineSelectionVisible(HWND hwnd, PdfTab const& tab)
    {
        if (!SidebarVisible() || g_sideMode != 0 || g_selectedOutlineRow < 0) return;
        if (tab.outlineLayout.empty()) return;
        auto rowIt = std::find_if(
            tab.outlineLayout.begin(),
            tab.outlineLayout.end(),
            [](OutlineLayoutRow const& row)
            {
                return row.id == g_selectedOutlineRow;
            });
        if (rowIt == tab.outlineLayout.end()) return;
        RECT area = SidebarScrollRect();
        int viewH = std::max<int>(1, area.bottom - area.top);
        int margin = S(20);
        int newScroll = g_sidebarScrollY;
        if (rowIt->top < g_sidebarScrollY + margin)
        {
            newScroll = rowIt->top - margin;
        }
        else if (rowIt->top + rowIt->height > g_sidebarScrollY + viewH - margin)
        {
            newScroll = rowIt->top + rowIt->height - viewH + margin;
        }
        newScroll = ClampSidebarScrollValue(newScroll);
        if (newScroll != g_sidebarScrollY)
        {
            g_sidebarScrollY = newScroll;
        }
        RequestSidebarRepaint(hwnd);
    }

    int ThumbnailBoxHeight(PdfTab const& tab, int page)
    {
        page = std::clamp(page, 0, std::max(0, tab.pageCount - 1));
        double ratioH = tab.pages[static_cast<size_t>(page)].heightPt / std::max(1.0, tab.pages[static_cast<size_t>(page)].widthPt);
        int thumbH = std::max<int>(S(56), static_cast<int>(g_thumbSize * ratioH + 0.5));
        return thumbH + S(58);
    }

    void KeepThumbnailSelectionVisible(HWND hwnd, PdfTab const& tab)
    {
        if (!SidebarVisible() || g_sideMode != 1 || tab.pageCount <= 0) return;
        int page = std::clamp(tab.currentPage, 0, tab.pageCount - 1);
        int itemTop = S(80);
        for (int i = 0; i < page; ++i)
            itemTop += ThumbnailBoxHeight(tab, i) + S(22);
        int itemBottom = itemTop + ThumbnailBoxHeight(tab, page);

        int sidebarH = std::max<int>(1, g_sidebar.bottom - g_sidebar.top);
        int desired = g_sidebarScrollY;
        if (itemTop - g_sidebarScrollY < S(86))
            desired = itemTop - S(92);
        else if (itemBottom - g_sidebarScrollY > sidebarH - S(14))
            desired = itemBottom - sidebarH + S(14);

        desired = ClampSidebarScrollValue(desired);
        if (desired != g_sidebarScrollY)
        {
            g_sidebarScrollY = desired;
            RequestSidebarRepaint(hwnd);
        }
        // During a fast reader scroll the page-change path already queued the
        // thumbnail selection repaint. The idle reconciliation below often
        // finds the same page and sidebar offset; repainting again here makes
        // the selected card visibly blink at the end of a fast scroll.
    }

    int StableOutlineRowDuringMainScroll(PdfTab const& tab, int scrollY);

    void SyncOutlineSelectionFromScroll(HWND hwnd, PdfTab& tab)
    {
        int selected = g_draggingMainScroll
            ? StableOutlineRowDuringMainScroll(tab, g_dragScrollTarget)
            : OutlineRowFromScroll(tab, g_scrollY);
        if (selected == g_selectedOutlineRow) return;
        g_selectedOutlineRow = selected;
        KeepOutlineSelectionVisible(hwnd, tab);
    }

    void SyncSidebarProgressFromScroll(HWND hwnd, PdfTab& tab)
    {
        if (g_sideMode == 0) SyncOutlineSelectionFromScroll(hwnd, tab);
        else if (g_sideMode == 1) KeepThumbnailSelectionVisible(hwnd, tab);
    }

    int StableOutlineRowDuringMainScroll(PdfTab const& tab, int scrollY)
    {
        int selected = OutlineRowFromScroll(tab, scrollY);
        if (g_dragOutlinePreviewRow < 0 || g_dragOutlinePreviewRow >= static_cast<int>(tab.outline.size()))
            return selected;

        // A partially built large-document layout must not erase a valid
        // selection for one drag sample. Once the target is valid again the
        // normal monotonic calculation resumes; at the actual top of a
        // document there is no previous preview row to preserve.
        if (selected < 0)
            return scrollY > S(16) ? g_dragOutlinePreviewRow : selected;

        if (selected > g_dragOutlinePreviewRow)
        {
            int nextTarget = OutlineTargetScrollY(tab, tab.outline[static_cast<size_t>(selected)]);
            // OutlineRowFromScroll intentionally looks a little ahead into
            // the viewport. Add a small dead band around that boundary so a
            // pointer sample cannot toggle between adjacent rows.
            if (scrollY + S(48) < nextTarget + S(12))
                return g_dragOutlinePreviewRow;
        }
        else if (selected < g_dragOutlinePreviewRow)
        {
            int previousTarget = OutlineTargetScrollY(tab, tab.outline[static_cast<size_t>(g_dragOutlinePreviewRow)]);
            if (scrollY + S(48) > previousTarget - S(12))
                return g_dragOutlinePreviewRow;
        }

        return selected;
    }

    void SyncSidebarProgressFromScrollFast(HWND hwnd, PdfTab& tab, int scrollY)
    {
        if (!SidebarVisible()) return;
        if (g_sideMode == 0)
        {
            int selected = StableOutlineRowDuringMainScroll(tab, scrollY);
            if (selected != g_selectedOutlineRow)
            {
                g_selectedOutlineRow = selected;
                g_dragOutlinePreviewRow = selected;
                // Keep the newly selected outline row inside the sidebar
                // viewport while the reader is being dragged. Without this,
                // the selection advances below the first sidebar screen but
                // the visible list appears frozen.
                KeepOutlineSelectionVisible(hwnd, tab);
            }
            else if (g_draggingMainScroll)
            {
                g_dragOutlinePreviewRow = selected;
            }
        }
        else if (g_sideMode == 1)
        {
            // Start the thumbnail request before the selected card is moved
            // into view. The worker stays asynchronous, but the new card no
            // longer has to appear first as an empty placeholder.
            int page = std::clamp(tab.currentPage, 0, std::max(0, tab.pageCount - 1));
            if (tab.pageCount > 0)
                (void)EnsureThumb(tab, page);
            RequestSidebarRepaint(hwnd);
        }
    }

    RECT ThumbnailItemRect(PdfTab const& tab, int page)
    {
        if (tab.pageCount <= 0 || g_sidebar.right <= g_sidebar.left ||
            page < 0 || page >= tab.pageCount)
            return RECT{};

        int y = g_sidebar.top + S(80) - g_sidebarScrollY;
        for (int i = 0; i < page; ++i)
            y += ThumbnailBoxHeight(tab, i) + S(22);
        int boxH = ThumbnailBoxHeight(tab, page);
        int boxW = std::max(g_thumbSize + S(36), S(160));
        return RECT{
            g_sidebar.left + (g_sidebar.right - g_sidebar.left - boxW) / 2,
            y,
            g_sidebar.left + (g_sidebar.right - g_sidebar.left + boxW) / 2,
            y + boxH
        };
    }

    void FocusPageInput(HWND hwnd)
    {
        PdfTab* tab = Active();
        if (!tab) return;
        g_searchInputFocused = false;
        g_pageInputFocused = true;
        g_pageCaretVisible = true;
        g_pageInputText = std::to_wstring(tab->currentPage + 1);
        g_pageCaretIndex = static_cast<int>(g_pageInputText.size());
        g_pageSelectionAnchor = -1;
        SetTimer(hwnd, 10, 500, nullptr);
        RECT client{};
        GetClientRect(hwnd, &client);
        RECT status{ 0, client.bottom - S(34), client.right, client.bottom };
        InvalidateRect(hwnd, &status, FALSE);
    }

    void CancelPageInput(HWND hwnd)
    {
        if (!g_pageInputFocused) return;
        g_pageInputFocused = false;
        g_pageInputText.clear();
        g_pageCaretIndex = 0;
        g_pageSelectionAnchor = -1;
        KillTimer(hwnd, 10);
        RECT client{};
        GetClientRect(hwnd, &client);
        RECT status{ 0, client.bottom - S(34), client.right, client.bottom };
        InvalidateRect(hwnd, &status, FALSE);
    }

    void CommitPageInput(HWND hwnd)
    {
        PdfTab* tab = Active();
        if (tab && !g_pageInputText.empty())
        {
            int page = std::clamp(_wtoi(g_pageInputText.c_str()), 1, tab->pageCount);
            ScrollToPage(*tab, page - 1);
            // Page entry is a navigation transaction, not only a coordinate
            // change. Queue the target viewport and keep the retained frame
            // until its complete visible coverage has been committed.
            g_facingScrollPending = false;
            g_mainScrollPresentationValid = false;
            RequestPageNavigationRepaint(hwnd, *tab, true);
        }
        CancelPageInput(hwnd);
        InvalidateRect(hwnd, nullptr, FALSE);
    }

    void ScrollToOutline(PdfTab& tab, int outlineRow)
    {
        if (outlineRow < 0 || outlineRow >= static_cast<int>(tab.outline.size()))
        {
            return;
        }
        auto const& item = tab.outline[static_cast<size_t>(outlineRow)];
        int page = std::clamp(item.page, 0, tab.pageCount - 1);
        tab.currentPage = page;
        // Use the same target calculation as outline-progress tracking. This
        // keeps double-page centering and malformed destination coordinates
        // consistent with the actual click target.
        g_scrollY = OutlineTargetScrollY(tab, item);
        tab.pendingSessionPosition = false;
        g_outlineNavigationRow = outlineRow;
        g_outlineNavigationRenderVersion = tab.renderVersion;
    }

    void ClearOutlineNavigationOverride()
    {
        g_outlineNavigationRow = -1;
        g_outlineNavigationRenderVersion = 0;
    }

    void RunSearch()
    {
        PdfTab* tab = Active();
        g_searchResults.clear();
        g_searchCurrent = 0;
        g_searchHasRun = true;
        g_searchLastQuery = g_searchQuery;
        if (!tab || g_searchQuery.empty())
        {
            return;
        }

        PdfDocumentLock pdfLock(*tab);
        std::string needle = ToUtf8(g_searchQuery);
        int totalHits = 0;
        for (int page = 0; page < tab->pageCount; ++page)
        {
            int marks[32]{};
            fz_quad boxes[32]{};
            int searchOptions = g_searchMatchCase ? 0 : 1;
            int count = 0;
            if (g_pdf.matchPageNumber)
            {
                count = g_pdf.matchPageNumber(tab->ctx, tab->doc, page, needle.c_str(), marks, boxes, 32, searchOptions);
            }
            else
            {
                count = g_pdf.searchPageNumber(tab->ctx, tab->doc, page, needle.c_str(), marks, boxes, 32);
            }
            if (count > 0)
            {
                for (int hit = 0; hit < count && totalHits < 500; ++hit)
                {
                    ++totalHits;
                    std::wstring snippet = L"\u7b2c" + std::to_wstring(page + 1) + L" \u9875\u7b2c " + std::to_wstring(hit + 1) + L" \u5904\uff1a" + g_searchQuery;
                    int highlightStart = static_cast<int>(snippet.find(g_searchQuery));
                    if (highlightStart < 0) highlightStart = 0;
                    g_searchResults.push_back(SearchResult{
                        L"\u7b2c" + std::to_wstring(page + 1) + L" \u9875\u5305\u542b \"" + g_searchQuery + L"\"",
                        snippet,
                        page,
                        1,
                        hit + 1,
                        boxes[hit],
                        true,
                        highlightStart,
                        static_cast<int>(g_searchQuery.size())
                    });
                }
            }
            if (totalHits >= 500)
            {
                break;
            }
        }
    }

    int SearchHitTotal()
    {
        int total = 0;
        for (auto const& result : g_searchResults) total += std::max(0, result.count);
        return total;
    }

    void LoadInitialPageGeometry(PdfTab& tab)
    {
        tab.pages.assign(static_cast<size_t>(std::max(0, tab.pageCount)), PageInfo{ 612.0, 792.0 });
        if (tab.pageCount <= 0) return;

        // The first page is enough to establish the initial viewport. The
        // complete page-size index is filled by the metadata worker after the
        // window is visible, so a large document does not block first paint.
        fz_page* page = g_pdf.loadPage(tab.ctx, tab.doc, 0);
        if (!page) return;
        fz_rect first = g_pdf.boundPage(tab.ctx, page);
        g_pdf.dropPage(tab.ctx, page);
        PageInfo fallback{
            std::max(1.0, static_cast<double>(first.x1 - first.x0)),
            std::max(1.0, static_cast<double>(first.y1 - first.y0))
        };
        std::fill(tab.pages.begin(), tab.pages.end(), fallback);
    }

    void LoadPageGeometry(PdfTab& tab)
    {
        tab.pages.assign(static_cast<size_t>(std::max(0, tab.pageCount)), PageInfo{ 612.0, 792.0 });
        if (tab.pageCount <= 0)
            return;

        std::vector<fz_rect> bounds(static_cast<size_t>(tab.pageCount));
        int loaded = g_pdf.pageBounds(tab.ctx, tab.doc, bounds.data(), tab.pageCount);
        if (loaded <= 0)
        {
            fz_page* page = g_pdf.loadPage(tab.ctx, tab.doc, 0);
            fz_rect first = g_pdf.boundPage(tab.ctx, page);
            g_pdf.dropPage(tab.ctx, page);
            PageInfo fallback{
                std::max(1.0, static_cast<double>(first.x1 - first.x0)),
                std::max(1.0, static_cast<double>(first.y1 - first.y0))
            };
            std::fill(tab.pages.begin(), tab.pages.end(), fallback);
            return;
        }

        PageInfo fallback{ 612.0, 792.0 };
        for (int i = 0; i < tab.pageCount; ++i)
        {
            if (i < loaded)
            {
                fz_rect const& bound = bounds[static_cast<size_t>(i)];
                double width = static_cast<double>(bound.x1 - bound.x0);
                double height = static_cast<double>(bound.y1 - bound.y0);
                if (std::isfinite(width) && std::isfinite(height) && width >= 1.0 && height >= 1.0)
                    fallback = PageInfo{ width, height };
            }
            tab.pages[static_cast<size_t>(i)] = fallback;
        }
    }
    void ApplyDocumentPosition(PdfTab& tab, int page, int scrollY, double zoom, int pageOffsetY, bool hasPageOffset)
    {
        tab.zoom = std::clamp(zoom, 0.0833, 64.0);
        int restoredPage = std::clamp(page, 0, std::max(0, tab.pageCount - 1));
        if (tab.pageCount > 0) ScrollToPage(tab, restoredPage);
        tab.savedScrollY = std::max(0, scrollY);
        tab.pendingSessionPosition = false;
        tab.pendingSessionPage = restoredPage;
        tab.pendingSessionOffsetY = 0;
        tab.pendingSessionPageOffset = false;
        tab.pendingSessionPageOffsetY = 0;

        if (g_continuousRead && tab.pageCount > 0)
        {
            tab.pendingSessionPosition = true;
            tab.pendingSessionPage = restoredPage;
            tab.pendingSessionPageOffset = hasPageOffset;
            tab.pendingSessionPageOffsetY = hasPageOffset
                ? pageOffsetY
                : tab.savedScrollY - SpreadTopScroll(tab, restoredPage);
            tab.pendingSessionOffsetY = tab.pendingSessionPageOffsetY;
            g_contentHeight = ContinuousContentHeight(tab);
            int maxScroll = std::max<int>(0, g_contentHeight - std::max<int>(1, g_stage.bottom - g_stage.top));
            int initial = tab.pendingSessionPageOffset
                ? PageTopScroll(tab, restoredPage) + tab.pendingSessionOffsetY
                : tab.savedScrollY;
            g_scrollY = std::clamp(initial, 0, maxScroll);
            tab.currentPage = restoredPage;
        }
        else
        {
            g_contentHeight = SinglePageContentHeight(tab);
            g_scrollY = std::clamp(tab.savedScrollY, 0, SinglePageMaxScroll(tab));
        }
    }

    void OpenPdf(HWND hwnd, const std::wstring& path)
    {
        bool openedFromHome = g_active < 0;
        g_pdf.Load();
        auto tab = std::make_unique<PdfTab>();
        tab->renderVersion = ++g_nextRenderVersion;
        tab->renderSession = CreatePageRenderSession(path);
        tab->ctx = tab->renderSession->uiContext;
        tab->doc = tab->renderSession->document;
        tab->pageCount = g_pdf.countPages(tab->ctx, tab->doc);
        tab->path = path;
        tab->name = std::filesystem::path(path).filename().wstring();
        UpdateTabFileStamp(*tab);
        int restorePage = RecentPageForPath(path);
        auto recent = std::find_if(g_recent.begin(), g_recent.end(), [&](auto const& item) { return item.path == path; });
        bool hasRecentPosition = recent != g_recent.end();
        RecentItem recentPosition;
        if (hasRecentPosition) recentPosition = *recent;
        int restoreSidebarScrollY = recent == g_recent.end() ? 0 : recent->sidebarScrollY;
        int restoreSelectedOutlineRow = recent == g_recent.end() ? -1 : recent->selectedOutlineRow;
        LoadInitialPageGeometry(*tab);
        bool outlineLoadedSynchronously = TryLoadSmallDocumentOutline(*tab);
        if (hasRecentPosition && recentPosition.hasSidebarState)
        {
            tab->sidebarRailOpen = recentPosition.sidebarRailOpen;
            tab->sidebarContentOpen = recentPosition.sidebarContentOpen;
            tab->sidebarStateExplicit = true;
        }
        tab->sidebarWidth = recentPosition.sidebarWidth;
        SaveActiveTabProgress();
        g_tabs.push_back(std::move(tab));
        g_active = static_cast<int>(g_tabs.size()) - 1;
        // Opening a new document changes the owner of the reader surface;
        // the previous document's committed frame must not suppress its
        // first normal paint.
        g_pageNavigationPending = false;
        g_facingScrollPending = false;
        g_allowIncompletePageNavigationFrame = false;
        g_stageFrameValid = false;
        g_stageFrameOffsetX = 0;
        g_stageFrameOffsetY = 0;
        g_stageFrameMotionX = 0;
        g_stageFrameMotionY = 0;
        g_mainScrollPresentationValid = false;
        g_tabs.back()->lastActivatedSerial = ++g_tabActivationSerial;
        g_tabs.back()->sidebarScrollY[0] = std::max(0, restoreSidebarScrollY);
        g_tabs.back()->selectedOutlineRow = restoreSelectedOutlineRow;
        g_sidebarKeyboardFocus = false;
        EnsureTabWindowVisible(g_active);
        g_tabListOpen = false;
        if (auto* active = Active())
        {
            if (hasRecentPosition && recentPosition.hasExactPosition)
            {
                ApplyDocumentPosition(*active,
                    recentPosition.page - 1,
                    recentPosition.scrollY,
                    recentPosition.zoom,
                    recentPosition.pageOffsetY,
                    recentPosition.hasPageOffset);
            }
            else
            {
                ScrollToPage(*active, std::clamp(restorePage, 1, active->pageCount) - 1);
            }
        }
        else
        {
            g_scrollY = 0;
        }
        if (Active() && g_viewMode != 0)
            g_scrollX = PreferredFacingScrollX(*Active());
        if (openedFromHome && !(hasRecentPosition && recentPosition.hasSidebarState))
        {
            // Opening a document from the home page should start in the
            // document outline when one exists, independent of the sidebar
            // mode remembered from the previous document.
            g_sidebarRailOpen = true;
            g_sidebarOpen = true;
            g_sideMode = 0;
        }
        if (outlineLoadedSynchronously && Active()->outline.empty() && !Active()->sidebarStateExplicit)
        {
            Active()->sidebarRailOpen = true;
            Active()->sidebarContentOpen = false;
        }
        RestoreActiveTabSidebarState(hwnd);
        UpdateRecent(*Active());
        SetTitle();
        // Starting or replacing the directory watcher can join an old
        // watcher thread. Keep it out of the document-open transaction.
        PostMessageW(hwnd, WM_QUIETPDF_REFRESH_FILE_WATCH, 0, 0);
        // Only the active Tab is allowed to generate work while a new file is
        // being opened. This mirrors SumatraPDF's visible-document-first
        // policy and prevents several large PDFs from warming concurrently.
        PrioritizePageRendersForTab(*Active());
        TrimBackgroundRenderCaches();
        // Small documents have their real MuPDF outline ready before the Tab
        // is published, so reopening them from Recent never shows a false
        // empty sidebar. Large documents stay asynchronous to preserve fast
        // first paint and responsive opening.
        if (!outlineLoadedSynchronously)
            RequestOutlineMetadata(hwnd, *Active());
        RequestAnnotationsMetadata(hwnd, *Active());
        QueueInitialViewportPreview(hwnd, *Active());
        SchedulePagePrefetch(hwnd);
        // Geometry is deliberately queued behind the outline and the visible
        // page. It is only a refinement for scrolling/layout accuracy.
        QueuePageMetadata(hwnd, *Active());
        // Ensure a one-shot cleanup also runs when the first page is already
        // cached and therefore produces no render-completion message.
        g_sharedStoreTrimPending = true;
        ScheduleIdleCacheTrim(hwnd);
        InvalidateRect(hwnd, nullptr, FALSE);
    }

    bool SamePath(std::wstring const& a, std::wstring const& b)
    {
        return _wcsicmp(a.c_str(), b.c_str()) == 0;
    }

    int FindOpenTabByPath(std::wstring const& path)
    {
        for (int i = 0; i < static_cast<int>(g_tabs.size()); ++i)
        {
            if (SamePath(g_tabs[static_cast<size_t>(i)]->path, path))
                return i;
        }
        return -1;
    }

    void OpenOrActivatePdf(HWND hwnd, std::wstring const& path)
    {
        bool activatedFromHome = g_active < 0;
        int existing = FindOpenTabByPath(path);
        if (existing >= 0)
        {
            if (activatedFromHome)
            {
                g_sidebarRailOpen = true;
                g_sidebarOpen = true;
                g_sideMode = 0;
            }
            ActivateTab(hwnd, existing);
            return;
        }
        OpenPdf(hwnd, path);
    }

    void ApplySessionPosition(PdfTab& tab, LastSessionItem const& item)
    {
        ApplyDocumentPosition(tab,
            item.page - 1,
            item.scrollY,
            item.zoom,
            item.pageOffsetY,
            item.hasPageOffset);
        tab.sidebarScrollY[0] = std::max(0, item.sidebarScrollY);
        tab.selectedOutlineRow = item.selectedOutlineRow;
        tab.sidebarRailOpen = item.sidebarRailOpen;
        tab.sidebarContentOpen = item.sidebarContentOpen;
        tab.sidebarWidth = item.sidebarWidth;
        tab.sidebarStateExplicit = item.hasSidebarState;
        TouchRecentProgress(tab, false);
    }

    void CaptureLastSessionFromOpenTabs()
    {
        g_lastSessionTabs.clear();
        g_lastSessionActive = -1;
        for (int i = 0; i < static_cast<int>(g_tabs.size()); ++i)
        {
            auto const& tab = g_tabs[static_cast<size_t>(i)];
            if (!tab || tab->path.empty()) continue;
            LastSessionItem item;
            item.path = tab->path;
            int scrollY = (g_active == i) ? g_scrollY : tab->savedScrollY;
            int page = (g_active == i && g_continuousRead)
                ? PageFromScroll(*tab, scrollY)
                : tab->currentPage;
            item.page = std::max(1, page + 1);
            item.scrollY = std::max(0, scrollY);
            item.zoom = tab->zoom;
            item.pageOffsetY = PageOffsetFromScroll(*tab, page, item.scrollY);
            item.hasPageOffset = g_continuousRead;
            item.sidebarScrollY = (g_active == i) ? g_sidebarScrollY : tab->sidebarScrollY[0];
            item.selectedOutlineRow = (g_active == i) ? g_selectedOutlineRow : tab->selectedOutlineRow;
            item.sidebarRailOpen = (g_active == i) ? g_sidebarRailOpen : tab->sidebarRailOpen;
            item.sidebarContentOpen = (g_active == i) ? g_sidebarOpen : tab->sidebarContentOpen;
            item.sidebarWidth = (g_active == i)
                ? std::max(g_sidebarExpandedWidth, g_sidebarWidth)
                : (tab->sidebarWidth > 0 ? tab->sidebarWidth : g_sidebarExpandedWidth);
            item.hasSidebarState = true;
            g_lastSessionTabs.push_back(item);
        }
        if (!g_lastSessionTabs.empty())
            g_lastSessionActive = std::clamp(g_active, 0, static_cast<int>(g_lastSessionTabs.size()) - 1);
    }

    bool HasOtherQingYueWindows(HWND current)
    {
        HWND found = nullptr;
        while ((found = FindWindowExW(nullptr, found, L"XiaoYuePDFWindow", nullptr)) != nullptr)
        {
            if (found != current)
                return true;
        }
        return false;
    }

    void RestoreLastSessionAndOpenLaunchFiles(HWND hwnd, std::vector<std::wstring> const& launchFiles, bool restoreSavedSession)
    {
        std::vector<int> restoredIndices;
        std::vector<LastSessionItem> savedTabs = restoreSavedSession ? g_lastSessionTabs : std::vector<LastSessionItem>{};
        int savedActive = restoreSavedSession ? g_lastSessionActive : -1;

        for (auto const& item : savedTabs)
        {
            if (item.path.empty() || !std::filesystem::exists(item.path))
                continue;
            if (FindOpenTabByPath(item.path) >= 0)
                continue;
            try
            {
                OpenPdf(hwnd, item.path);
                if (PdfTab* tab = Active())
                {
                    ApplySessionPosition(*tab, item);
                    restoredIndices.push_back(g_active);
                }
            }
            catch (std::exception const&) {}
        }

        if (!restoredIndices.empty())
        {
            int restoredActive = std::clamp(savedActive, 0, static_cast<int>(restoredIndices.size()) - 1);
            g_active = restoredIndices[static_cast<size_t>(restoredActive)];
            RestoreActiveTabPosition(hwnd);
            RestoreActiveTabSidebarState(hwnd);
        }

        for (auto const& path : launchFiles)
        {
            int existing = FindOpenTabByPath(path);
            if (existing >= 0)
            {
                ActivateTab(hwnd, existing);
                continue;
            }
            try { OpenPdf(hwnd, path); }
            catch (std::exception const& e) { MessageBoxA(hwnd, e.what(), "QingYuePDF", MB_ICONERROR); }
        }

        SetTitle();
        StartActiveFileWatcher(hwnd);
        InvalidateRect(hwnd, nullptr, FALSE);
    }

    void OpenDialog(HWND hwnd)
    {
        constexpr DWORD OpenDialogBufferChars = 64 * 1024;
        std::vector<wchar_t> files(OpenDialogBufferChars, L'\0');
        OPENFILENAMEW ofn{};
        ofn.lStructSize = sizeof(ofn);
        ofn.hwndOwner = hwnd;
        ofn.lpstrFile = files.data();
        ofn.nMaxFile = OpenDialogBufferChars;
        ofn.lpstrFilter = L"PDF \u6587\u4ef6 (*.pdf)\0*.pdf\0\u6240\u6709\u6587\u4ef6 (*.*)\0*.*\0";
        ofn.Flags = OFN_PATHMUSTEXIST | OFN_FILEMUSTEXIST | OFN_EXPLORER | OFN_ALLOWMULTISELECT;
        if (!GetOpenFileNameW(&ofn)) return;

        wchar_t const* entry = files.data();
        std::wstring first(entry);
        entry += first.size() + 1;
        if (*entry == L'\0')
        {
            OpenOrActivatePdf(hwnd, first);
            return;
        }

        std::filesystem::path folder(first);
        while (*entry != L'\0')
        {
            OpenOrActivatePdf(hwnd, (folder / entry).wstring());
            entry += wcslen(entry) + 1;
        }
    }

    void DisableNativeScrollbars(HWND hwnd)
    {
        if (!hwnd) return;
        LONG_PTR style = GetWindowLongPtrW(hwnd, GWL_STYLE);
        LONG_PTR stripped = style & ~(WS_VSCROLL | WS_HSCROLL);
        if (stripped != style)
        {
            SetWindowLongPtrW(hwnd, GWL_STYLE, stripped);
            SetWindowPos(hwnd, nullptr, 0, 0, 0, 0,
                SWP_NOMOVE | SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE | SWP_FRAMECHANGED);
        }
        ShowScrollBar(hwnd, SB_BOTH, FALSE);
    }
    void ClampScroll(HWND hwnd)
    {
        PdfTab* tab = Active();
        if (tab)
        {
            g_contentHeight = g_continuousRead ? ContinuousContentHeight(*tab) : SinglePageContentHeight(*tab);
            g_contentWidth = ReadingContentWidth(*tab);
        }
        int maxScroll = std::max<int>(0, g_contentHeight - (g_stage.bottom - g_stage.top));
        int maxScrollX = std::max<int>(0, g_contentWidth - std::max<int>(1, g_stage.right - g_stage.left));
        if (tab && tab->zoomPresentationPending && tab->zoomPresentationAnchorValid)
        {
            g_scrollX = std::clamp(tab->zoomPresentationScrollX, 0, maxScrollX);
            g_scrollY = std::clamp(tab->zoomPresentationScrollY, 0, maxScroll);
        }
        // During a thumb drag the mapping was captured at button-down. An
        // asynchronous layout/render completion must not clamp the live
        // position against a newer extent and move the thumb backwards.
        if (!g_draggingMainScroll)
            g_scrollY = std::clamp(g_scrollY, 0, maxScroll);
        g_scrollX = std::clamp(g_scrollX, 0, maxScrollX);
        if (tab && g_continuousRead)
        {
            tab->currentPage = PageFromScroll(*tab, g_scrollY);
            TouchRecentProgress(*tab, false);
            if (g_outlineNavigationRow >= 0 &&
                g_outlineNavigationRenderVersion == tab->renderVersion)
            {
                g_selectedOutlineRow = g_outlineNavigationRow;
                tab->selectedOutlineRow = g_outlineNavigationRow;
                if (!g_pageNavigationPending && tab->outlineMetadataLoaded)
                    ClearOutlineNavigationOverride();
            }
            else
            {
                SyncSidebarProgressFromScroll(hwnd, *tab);
            }
        }
        DisableNativeScrollbars(hwnd);
    }

    void UpdateVertScrollBar(HWND hwnd)
    {
        PdfTab* tab = Active();
        if (tab)
        {
            g_contentHeight = g_continuousRead ? ContinuousContentHeight(*tab) : SinglePageContentHeight(*tab);
            g_contentWidth = ReadingContentWidth(*tab);
        }
        // Keep the custom scrollbar geometry in the same transaction as the
        // content extent. Zoom can add/remove the horizontal bar and change
        // the reader clip before WM_PAINT gets a chance to call
        // PaintMainScrollBar; leaving the old rectangles here lets the paint
        // code classify the new invalidation against stale geometry.
        RECT client{};
        GetClientRect(hwnd, &client);
        UpdateMainScrollRects(client);
        DisableNativeScrollbars(hwnd);
    }

    bool Hit(RECT r, int x, int y)
    {
        return x >= r.left && x < r.right && y >= r.top && y < r.bottom;
    }

    bool Intersects(RECT a, RECT b)
    {
        RECT out{};
        return IntersectRect(&out, &a, &b) != FALSE;
    }

    RECT UnionRectSafe(RECT a, RECT b)
    {
        if (IsRectEmpty(&a)) return b;
        if (IsRectEmpty(&b)) return a;
        RECT out{};
        UnionRect(&out, &a, &b);
        return out;
    }

    void ResizeSidebarNow(HWND hwnd, int width, bool finalPaint)
    {
        width = std::clamp(width, SidebarMinimumWidth(), S(520));
        g_sidebarTargetWidth = width;
        if (!finalPaint)
        {
            constexpr ULONGLONG frameMs = 16;
            ULONGLONG now = GetTickCount64();
            if (now - g_lastSidebarResizeMs < frameMs)
            {
                if (!g_sidebarResizePending)
                {
                    g_sidebarResizePending = true;
                    SetTimer(hwnd, 1, static_cast<UINT>(frameMs - (now - g_lastSidebarResizeMs)), nullptr);
                }
                return;
            }
        }
        if (width == g_sidebarWidth && !finalPaint) return;

        RECT client{};
        GetClientRect(hwnd, &client);
        g_sidebarWidth = g_sidebarTargetWidth;
        if (g_sidebarWidth >= S(180)) g_sidebarExpandedWidth = g_sidebarWidth;
        if (PdfTab* active = Active())
            active->sidebarWidth = g_sidebarExpandedWidth;
        g_sidebarResizePending = false;
        g_lastSidebarResizeMs = GetTickCount64();
        KillTimer(hwnd, 1);

        int top = g_immersive ? 0 : S(76);
        int bottom = (g_immersive || !g_statusPinned) ? 0 : S(34);
        RECT dirty{ 0, top, client.right, client.bottom - bottom };
        InvalidateRect(hwnd, &dirty, FALSE);
    }

    RECT SidebarScrollRect()
    {
        // Keep the bookmark header outside the scrolling viewport. The extra
        // breathing room prevents the first row and its tree connector from
        // appearing to slide underneath the fixed title/tool row.
        int top = g_sidebar.top + S(g_sideMode == 0 ? 79 : (g_sideMode == 1 ? 80 : (g_sideMode == 2 ? 168 : 96)));
        return RECT{ g_sidebar.left, top, g_sidebar.right, g_sidebar.bottom };
    }

    bool SidebarContentNeedsScroll()
    {
        if (!SidebarVisible() || g_sidebarWidth <= 0) return false;
        if (g_sideMode < 0 || g_sideMode > 3) return false;
        RECT area = SidebarScrollRect();
        int visible = std::max<int>(1, area.bottom - area.top);
        return g_sidebarContentHeight > visible + S(1);
    }

    void UpdateSidebarScrollRects()
    {
        g_sidebarScrollTrackRect = {};
        g_sidebarScrollThumbRect = {};
        if (!SidebarContentNeedsScroll()) return;

        RECT area = SidebarScrollRect();
        int trackW = S(12);
        int gutter = S(2);
        g_sidebarScrollTrackRect = RECT{
            g_sidebar.right - gutter - trackW,
            area.top + S(6),
            g_sidebar.right - gutter,
            area.bottom - S(6)
        };

        int trackH = std::max<int>(1, g_sidebarScrollTrackRect.bottom - g_sidebarScrollTrackRect.top);
        int visible = std::max<int>(1, area.bottom - area.top);
        int thumbH = std::clamp(MulDiv(visible, trackH, std::max(1, g_sidebarContentHeight)), S(28), trackH);
        int maxScroll = std::max<int>(1, g_sidebarContentHeight - visible);
        int travel = std::max<int>(0, trackH - thumbH);
        int scrollY = std::clamp(g_sidebarScrollY, 0, maxScroll);
        int thumbTop = g_sidebarScrollTrackRect.top + MulDiv(scrollY, travel, maxScroll);
        if (scrollY >= maxScroll) thumbTop = g_sidebarScrollTrackRect.bottom - thumbH;
        g_sidebarScrollThumbRect = RECT{
            g_sidebarScrollTrackRect.left,
            thumbTop,
            g_sidebarScrollTrackRect.right,
            thumbTop + thumbH
        };
    }

    void PaintSidebarScrollBar(HDC dc)
    {
        UpdateSidebarScrollRects();
        if (IsRectEmpty(&g_sidebarScrollTrackRect)) return;

        RECT area = SidebarScrollRect();
        bool visible = g_draggingSidebarScroll || Hit(area, g_mousePos.x, g_mousePos.y);
        if (!visible) return;

        bool active = g_draggingSidebarScroll || Hit(g_sidebarScrollTrackRect, g_mousePos.x, g_mousePos.y);
        int centerX = (g_sidebarScrollTrackRect.left + g_sidebarScrollTrackRect.right) / 2;
        int trackW = active
            ? std::max(1, (S(6) * 9) / 10)
            : std::max(2, S(3));
        RECT visualThumb{
            centerX - trackW / 2,
            g_sidebarScrollThumbRect.top,
            centerX + (trackW + 1) / 2,
            g_sidebarScrollThumbRect.bottom
        };
        // The sidebar thumb is an overlay on top of its content. Keep it
        // green in both states, but translucent, so inactive content-area
        // hover never falls back to the dark document scrollbar color.
        BYTE alpha = active ? 188 : 156;
        DrawScrollThumbAA(dc, visualThumb, S(5), T().accent, alpha);
    }

    bool ZoomRenderDeferred()
    {
        return g_zoomRenderDeferUntil != 0 && GetTickCount64() < g_zoomRenderDeferUntil;
    }

