    void RequestPageNavigationRepaint(HWND hwnd, PdfTab& tab, bool waitForComplete)
    {
        g_contentHeight = g_continuousRead
            ? ContinuousContentHeight(tab)
            : SinglePageContentHeight(tab);
        g_contentWidth = ReadingContentWidth(tab);
        // A navigation transaction keeps the last complete viewport on screen
        // until every visible target page pixel is ready.
        g_pageNavigationPending = waitForComplete;
        g_allowIncompletePageNavigationFrame = !waitForComplete;
        UpdateVertScrollBar(hwnd);

        if (UseTiledPageRendering(tab))
            MaintainVisibleTileRenderQueueForScroll(tab);
        else
            MaintainVisiblePageRenderQueueForScroll(tab);

        SchedulePagePrefetch(hwnd);
        RequestStageRepaint(hwnd, true);
    }

    bool UseFacingContinuousPresentation()
    {
        // Facing layouts need the same committed-frame presentation whether
        // the page flow is continuous or discrete. Without this, a double
        // page/book zoom falls back to waiting for a fresh full-page render.
        // Single-page mode remains on the 2.5.9 path.
        return g_viewMode != 0;
    }

    void FinishZoomPresentationForScroll(HWND hwnd, PdfTab& tab)
    {
        if (!tab.zoomPresentationPending) return;

        // A scroll changes the viewport before the target zoom generation can
        // finish. Keeping the zoom gate active here makes PaintPages retain a
        // frame from the old viewport, so a newly exposed facing page becomes
        // the stage background after the drag is released. The zoom fallback
        // remains owned by the tab and supplies a complete page until the
        // target generation is ready.
        tab.zoomPresentationPending = false;
        tab.zoomPresentationAnchorValid = false;
        g_zoomRenderDeferUntil = 0;
        KillTimer(hwnd, 21);
        if (tab.zoomFallbackZoom > 0.0)
            tab.zoomFallbackUntil = GetTickCount64() + 8000;
    }

    bool ShiftStageFrameForScroll(int dx, int dy)
    {
        if (!g_stageFrameValid || !g_stageFrameDc || !g_paintBufferDc || IsRectEmpty(&g_stage) ||
            (dx == 0 && dy == 0))
            return false;

        RECT frameRect = g_stage;
        if (IsRectEmpty(&frameRect)) return false;

        int width = std::max<int>(1, frameRect.right - frameRect.left);
        int height = std::max<int>(1, frameRect.bottom - frameRect.top);
        if (std::abs(dx) >= width || std::abs(dy) >= height)
            return false;

        // Rebase the retained frame itself, using a separate scratch surface.
        // Keeping the frame in the new viewport coordinates means the next
        // scroll can start from a complete frame again; an accumulated visual
        // offset otherwise eventually runs out of source pixels and exposes
        // the stage background in the newly uncovered corner.
        int scratchState = SaveDC(g_paintBufferDc);
        IntersectClipRect(g_paintBufferDc, frameRect.left, frameRect.top, frameRect.right, frameRect.bottom);
        Fill(g_paintBufferDc, frameRect, T().stage);
        RECT destination = frameRect;
        OffsetRect(&destination, dx, dy);
        RECT clippedDestination{};
        if (IntersectRect(&clippedDestination, &destination, &frameRect))
        {
            RECT source = clippedDestination;
            OffsetRect(&source, -dx, -dy);
            BitBlt(g_paintBufferDc,
                clippedDestination.left, clippedDestination.top,
                clippedDestination.right - clippedDestination.left,
                clippedDestination.bottom - clippedDestination.top,
                g_stageFrameDc, source.left, source.top, SRCCOPY);
        }
        RestoreDC(g_paintBufferDc, scratchState);

        bool shifted = BitBlt(g_stageFrameDc, frameRect.left, frameRect.top,
            width, height, g_paintBufferDc, frameRect.left, frameRect.top, SRCCOPY) != FALSE;
        if (shifted)
        {
            g_stageFrameOffsetX = 0;
            g_stageFrameOffsetY = 0;
            g_stageFrameMotionX = 0;
            g_stageFrameMotionY = 0;
        }
        return shifted;
    }

    void ScrollStagePixels(HWND hwnd, int dx, int dy, bool includeStatus)
    {
        PdfTab* tab = Active();
        if (UseFacingContinuousPresentation() && tab && hwnd)
        {
            RECT reader = MainReaderPixelClip();
            int width = std::max<int>(1, reader.right - reader.left);
            int height = std::max<int>(1, reader.bottom - reader.top);
            // Move the already presented pixels as one native window
            // operation. Windows copies the retained pixels immediately and
            // invalidates only the newly exposed edge; it does not make the
            // reader pass through its stage background on every wheel sample.
            // The page renderer then owns only that edge and can fill it from
            // a complete cached page without competing with the input path.
            if (g_stageFrameValid && !IsRectEmpty(&reader) &&
                (dx != 0 || dy != 0) && std::abs(dx) < width && std::abs(dy) < height)
            {
                bool shiftedFrame = ShiftStageFrameForScroll(dx, dy);
                if (shiftedFrame)
                {
                    RECT client{};
                    GetClientRect(hwnd, &client);
                    RECT toggle = SidebarPanelTogglePaintRectForClient(client);
                    RECT immersiveExit = ImmersiveExitPanelPaintRectForClient(client);
                    std::vector<RECT> scrollParts{ reader };
                    auto excludeOverlay = [&](RECT overlay)
                    {
                        if (IsRectEmpty(&overlay)) return;
                        std::vector<RECT> next;
                        next.reserve(scrollParts.size() * 4);
                        for (RECT part : scrollParts)
                        {
                            RECT overlap{};
                            if (!IntersectRect(&overlap, &part, &overlay))
                            {
                                next.push_back(part);
                                continue;
                            }
                            RECT topPart{ part.left, part.top, part.right, overlap.top };
                            RECT bottomPart{ part.left, overlap.bottom, part.right, part.bottom };
                            RECT leftPart{ part.left, overlap.top, overlap.left, overlap.bottom };
                            RECT rightPart{ overlap.right, overlap.top, part.right, overlap.bottom };
                            if (!IsRectEmpty(&topPart)) next.push_back(topPart);
                            if (!IsRectEmpty(&bottomPart)) next.push_back(bottomPart);
                            if (!IsRectEmpty(&leftPart)) next.push_back(leftPart);
                            if (!IsRectEmpty(&rightPart)) next.push_back(rightPart);
                        }
                        scrollParts = std::move(next);
                    };
                    excludeOverlay(toggle);
                    excludeOverlay(immersiveExit);
                    auto scrollRect = [&](RECT part)
                    {
                        if (!IsRectEmpty(&part))
                            ScrollWindowEx(hwnd, dx, dy, &part, nullptr, nullptr,
                                nullptr, SW_INVALIDATE | SW_SCROLLCHILDREN);
                    };
                    // ScrollWindowEx accepts only a rectangular source. Split
                    // the reader around foreground controls so page pixels
                    // never move either control or leave a shifted ghost.
                    for (RECT part : scrollParts) scrollRect(part);
                    // The scrollbar tracks are fixed opaque slots. Do not
                    // restore the shifted page frame into them: that was the
                    // source of stale page strips and duplicate content at
                    // the right and bottom edges during fast scrolling.
                    RECT verticalTrack = g_mainScrollTrackRect;
                    RECT horizontalTrack = g_mainHScrollTrackRect;
                    if (!IsRectEmpty(&verticalTrack) || !IsRectEmpty(&horizontalTrack))
                    {
                        HDC dc = GetDC(hwnd);
                        if (dc)
                        {
                            PaintMainScrollTrackBackground(dc, verticalTrack);
                            PaintMainScrollTrackBackground(dc, horizontalTrack);
                            PaintMainScrollBar(dc, client, g_stage);
                            ReleaseDC(hwnd, dc);
                        }
                    }
                    // The retained frame was rebased before the native move.
                    // Keep it valid so the exposed edge and transparent
                    // scrollbar underlay can be painted into it next.
                }
                else
                {
                    // Never move the window without a matching frame update;
                    // that would expose an unpainted edge on a fast drag.
                    g_stageFrameValid = false;
                    InvalidateRect(hwnd, &reader, FALSE);
                }
            }
            else
            {
                InvalidateRect(hwnd, &reader, FALSE);
            }
                if (includeStatus && !g_immersive)
                {
                    RECT client{};
                    GetClientRect(hwnd, &client);
                RECT status{ 0, client.bottom - S(34), client.right, client.bottom };
                InvalidateRect(hwnd, &status, FALSE);
            }
            return;
        }
        RequestStageRepaint(hwnd, includeStatus);
    }
    void RequestSidebarRepaint(HWND hwnd)
    {
        constexpr ULONGLONG frameMs = 16;
        ULONGLONG now = GetTickCount64();
        if (now - g_lastSidebarRepaintMs >= frameMs)
        {
            RECT area = SidebarScrollRect();
            InvalidateRect(hwnd, &area, FALSE);
            g_lastSidebarRepaintMs = now;
            g_sidebarRepaintPending = false;
        }
        else if (!g_sidebarRepaintPending)
        {
            g_sidebarRepaintPending = true;
            SetTimer(hwnd, 7, static_cast<UINT>(frameMs - (now - g_lastSidebarRepaintMs)), nullptr);
        }
    }

