    {
        if (g_hasContentSelection || g_selectingContent || g_annotationToolbarOpen || g_annotationNoteOpen)
            return false;
        return g_stageLightPaintUntil != 0 && GetTickCount64() < g_stageLightPaintUntil;
    }
    bool StageScrollPaintInProgress()
    {
        return StageLightPaintActive() || MainScrollDragRecentlyMoved() ||
            (UseFacingContinuousPresentation() && g_draggingMainScroll) || g_draggingMainHScroll ||
            g_smoothStageScroll || g_touchPanQueued || g_touchMomentum || g_autoScrollActive;
    }

    void MarkStageScrolling(HWND hwnd)
    {
        ULONGLONG now = GetTickCount64();
        g_stageLightPaintUntil = now + 120;
        g_stageIdleRefreshPending = true;
        KillTimer(hwnd, 8);
        SetTimer(hwnd, 8, 140, nullptr);
    }

    bool TileLevelFullyCached(PdfTab& tab, int page, RECT pageRect, RECT drawRect, int level);

    bool LowZoomVisiblePagesReady(HWND hwnd, PdfTab& tab)
    {
        if (UseTiledPageRendering(tab) || tab.pageCount <= 0) return true;
        int firstPage = g_continuousRead ? std::max(0, FirstVisibleSpreadStart(tab)) :
            FirstPageInSpread(std::clamp(tab.currentPage, 0, tab.pageCount - 1));
        int lastPage = g_continuousRead ? tab.pageCount : NextSpreadStart(tab, firstPage);
        RECT view = g_stage;
        bool hadVisible = false;
        bool ready = true;
        int queued = 0;
        for (int start = firstPage; start < lastPage; start = NextSpreadStart(tab, start))
        {
            int y = g_continuousRead ? SpreadVisualTop(tab, start) : g_stage.top + S(28) - g_scrollY;
            int spreadH = SpreadHeight(tab, start);
            RECT spreadRect{ SpreadX(tab, start), y, SpreadX(tab, start) + SpreadWidth(tab, start), y + spreadH };
            if (g_continuousRead && spreadRect.top > view.bottom + S(8)) break;
            if (!Intersects(spreadRect, view)) continue;
            int count = SpreadPageCount(tab, start);
            for (int j = 0; j < count; ++j)
            {
                int page = start + j;
                RECT pageRect{};
                if (!BuildSpreadPageRect(tab, start, y, page, pageRect)) continue;
                if (!Intersects(pageRect, view)) continue;
                hadVisible = true;
                PageImage* image = FindCachedPage(tab, page);
                if (!image || ((!image->dib && image->bgra.empty()) || image->width <= 0 || image->height <= 0))
                {
                    ready = false;
                    if (queued < std::clamp(VisiblePageCountForCache(tab), 4, 24))
                    {
                        QueuePageRender(hwnd, tab, page, -20 + queued);
                        ++queued;
                    }
                }
            }
        }
        return !hadVisible || ready;
    }
    bool HighZoomVisiblePagesReady(HWND hwnd, PdfTab& tab)
    {
        if (!UseTiledPageRendering(tab) || tab.pageCount <= 0) return true;
        int firstPage = g_continuousRead ? std::max(0, FirstVisibleSpreadStart(tab)) :
            FirstPageInSpread(std::clamp(tab.currentPage, 0, tab.pageCount - 1));
        int lastPage = g_continuousRead ? tab.pageCount : NextSpreadStart(tab, firstPage);
        RECT view = g_stage;
        bool hadVisible = false;
        bool ready = true;
        int queued = 0;
        for (int start = firstPage; start < lastPage; start = NextSpreadStart(tab, start))
        {
            int y = g_continuousRead ? SpreadVisualTop(tab, start) : g_stage.top + S(28) - g_scrollY;
            int spreadH = SpreadHeight(tab, start);
            RECT spreadRect{ SpreadX(tab, start), y, SpreadX(tab, start) + SpreadWidth(tab, start), y + spreadH };
            if (g_continuousRead && spreadRect.top > view.bottom + S(8)) break;
            if (!Intersects(spreadRect, view)) continue;
            int count = SpreadPageCount(tab, start);
            for (int j = 0; j < count; ++j)
            {
                int page = start + j;
                RECT pageRect{};
                if (!BuildSpreadPageRect(tab, start, y, page, pageRect)) continue;
                RECT drawRect{};
                if (!IntersectRect(&drawRect, &pageRect, &view)) continue;
                hadVisible = true;

                bool pageReady = false;
                PageImage* fallback = FindZoomFallbackPage(tab, page);
                if (fallback && (fallback->dib || !fallback->bgra.empty()) && fallback->width > 0 && fallback->height > 0)
                    pageReady = true;

                int pageW = PageW(tab, page);
                int pageH = PageH(tab, page);
                int targetLevel = TileLevelForPage(tab, page, pageW, pageH);
                if (!pageReady && TileLevelFullyCached(tab, page, pageRect, drawRect, 0))
                    pageReady = true;
                for (int level = targetLevel; !pageReady && level >= 1; --level)
                {
                    if (TileLevelFullyCached(tab, page, pageRect, drawRect, level))
                        pageReady = true;
                }

                if (!pageReady)
                {
                    ready = false;
                    QueueZoomPreviewRender(hwnd, tab, page, 10 + queued);
                    int queueBudget = 10;
                    QueueVisibleTilesForPageLevel(hwnd, tab, page, pageRect, drawRect, 0, queued, queueBudget);
                    ++queued;
                }
            }
        }
        return !hadVisible || ready;
    }

    void QueueVisibleCommittedPagesForScroll(HWND hwnd, PdfTab& tab)
    {
        if (!UseTiledPageRendering(tab) || tab.pageCount <= 0) return;

        RECT view = g_stage;
        InflateRect(&view, S(8), S(8));
        int firstVisible = g_continuousRead ? std::max(0, FirstVisibleSpreadStart(tab)) :
            FirstPageInSpread(std::clamp(tab.currentPage, 0, tab.pageCount - 1));
        int queued = 0;
        for (int start = firstVisible; start < tab.pageCount && queued < 2; start = NextSpreadStart(tab, start))
        {
            int y = g_continuousRead ? SpreadVisualTop(tab, start) : g_stage.top + S(28) - g_scrollY;
            RECT spreadRect{ SpreadX(tab, start), y, SpreadX(tab, start) + SpreadWidth(tab, start), y + SpreadHeight(tab, start) };
            if (g_continuousRead && spreadRect.top > view.bottom) break;
            if (!Intersects(spreadRect, view) && (g_continuousRead || start != firstVisible)) continue;

            int count = SpreadPageCount(tab, start);
            for (int j = 0; j < count && queued < 2; ++j)
            {
                int page = start + j;
                RECT pageRect{};
                if (!BuildSpreadPageRect(tab, start, y, page, pageRect) || !Intersects(pageRect, view)) continue;
                if (CanCacheWholePageAtCurrentZoom(tab, page))
                {
                    QueuePageRender(hwnd, tab, page, -32 + queued);
                    ++queued;
                }
            }
            if (!g_continuousRead) break;
        }
    }

    // Sumatra-style scroll priming: queue the cheapest complete representation
    // for the newly visible facing pages before asking the presentation layer
    // to move. A complete coarse tile level is enough to keep the viewport
    // continuous; final tiles can replace it asynchronously afterward.
    void PrimeFacingScrollCoverage(HWND hwnd, PdfTab& tab)
    {
        if (tab.pageCount <= 0) return;

        RECT view = g_stage;
        int padY = std::max<int>(S(48), (g_stage.bottom - g_stage.top) / 5);
        InflateRect(&view, S(8), padY);
        int firstVisible = g_continuousRead
            ? std::max(0, FirstVisibleSpreadStart(tab))
            : FirstPageInSpread(std::clamp(tab.currentPage, 0, tab.pageCount - 1));
        int startAt = firstVisible;
        if (g_continuousRead)
        {
            int previous = PreviousSpreadStart(tab, firstVisible);
            if (previous >= 0) startAt = previous;
        }

        // Build the latest coverage set before touching the worker queue.
        // Repeated pointer samples retain requests shared by adjacent
        // viewports instead of deleting and recreating every pending page.
        std::vector<int> targetPages;
        targetPages.reserve(8);
        for (int start = startAt; start < tab.pageCount && targetPages.size() < 8;
            start = NextSpreadStart(tab, start))
        {
            int y = g_continuousRead ? SpreadVisualTop(tab, start) : g_stage.top + S(28) - g_scrollY;
            if (g_continuousRead && y > view.bottom) break;
            int count = SpreadPageCount(tab, start);
            for (int j = 0; j < count && targetPages.size() < 8; ++j)
            {
                int page = start + j;
                RECT pageRect{};
                RECT visible{};
                if (BuildSpreadPageRect(tab, start, y, page, pageRect) &&
                    IntersectRect(&visible, &pageRect, &view))
                    targetPages.push_back(page);
            }
            if (!g_continuousRead) break;
        }
        CancelStaleFacingPreviews(tab, targetPages);
        if (!tab.zoomPresentationPending)
        {
            for (size_t i = 0; i < targetPages.size(); ++i)
                QueueFacingPreviewRender(hwnd, tab, targetPages[i], -44 + static_cast<int>(i));
        }

        int queued = 0;
        for (int start = startAt; start < tab.pageCount && queued < 8; start = NextSpreadStart(tab, start))
        {
            int y = g_continuousRead ? SpreadVisualTop(tab, start) : g_stage.top + S(28) - g_scrollY;
            if (g_continuousRead && y > view.bottom) break;
            int count = SpreadPageCount(tab, start);
            for (int j = 0; j < count && queued < 8; ++j)
            {
                int page = start + j;
                RECT pageRect{};
                RECT drawRect{};
                if (!BuildSpreadPageRect(tab, start, y, page, pageRect) ||
                    !IntersectRect(&drawRect, &pageRect, &view))
                    continue;

                if (!UseTiledPageRendering(tab))
                {
                    QueuePageRender(hwnd, tab, page, -28 + queued);
                    ++queued;
                    continue;
                }

                int pageW = PageW(tab, page);
                int pageH = PageH(tab, page);
                int targetLevel = TileLevelForPage(tab, page, pageW, pageH);
                int budget = 4;
                if (targetLevel >= 1)
                    QueueVisibleTilesForPageLevel(hwnd, tab, page, pageRect, drawRect,
                        targetLevel, -36 + queued, budget);
                if (budget > 0)
                    QueueVisibleTilesForPageLevel(hwnd, tab, page, pageRect, drawRect,
                        0, -28 + queued, budget);
                queued += 4 - budget;
            }
            if (!g_continuousRead) break;
        }
    }

    bool VisiblePagesReadyForPixelScroll(HWND hwnd, PdfTab& tab)
    {
        if (UseTiledPageRendering(tab))
        {
            ScheduleVisibleTilePrefetch(hwnd, tab);
            return false;
        }
        return LowZoomVisiblePagesReady(hwnd, tab);
    }
    void ScrollStageTo(HWND hwnd, int newScrollY, bool animatedFrame = false, bool immediateRepaint = false, bool dragFrame = false)
    {
        PdfTab* tab = Active();
        // A real document scroll means the user's viewport is authoritative;
        // stop carrying a previous directory click through that scroll.
        if (g_outlineNavigationRow >= 0)
            ClearOutlineNavigationOverride();
        int oldPage = tab ? tab->currentPage : -1;
        if (tab)
        {
            g_contentHeight = g_continuousRead ? ContinuousContentHeight(*tab) : SinglePageContentHeight(*tab);
            g_contentWidth = ReadingContentWidth(*tab);
        }
        int maxScroll = (g_draggingMainScroll && g_mainScrollDragGeometryValid)
            ? std::max<int>(0, g_mainScrollDragMaxScroll)
            : std::max<int>(0, g_contentHeight - std::max<int>(1, g_stage.bottom - g_stage.top));
        g_scrollX = std::clamp(g_scrollX, 0, std::max<int>(0, g_contentWidth - std::max<int>(1, g_stage.right - g_stage.left)));
        int old = g_scrollY;
        g_scrollY = std::clamp(newScrollY, 0, maxScroll);
        if (tab && g_continuousRead)
        {
            tab->currentPage = PageFromScroll(*tab, g_scrollY);
            if (oldPage != tab->currentPage)
            {
                TouchRecentProgress(*tab, false);
                SyncSidebarProgressFromScrollFast(hwnd, *tab, g_scrollY);
            }
            g_sidebarProgressRefreshPending = true;
        }
        int dy = old - g_scrollY;
        if (!animatedFrame)
        {
            g_stageScrollPos = static_cast<double>(g_scrollY);
            g_stageScrollVelocity = 0.0;
            g_stageScrollLastTick = GetTickCount64();
        }

        if (dy != 0)
        {
            g_stageScrollDirection = dy < 0 ? 1 : -1;
            ++g_viewportGeneration;
            if (!g_draggingMainScroll)
            {
                // Publish one scrollbar mapping for the whole movement
                // window. Background layout completion may change the final
                // document extent, but it must not move the thumb while the
                // user is still scrolling.
                g_mainScrollPresentationValid = true;
                g_mainScrollPresentationScrollY = g_scrollY;
                g_mainScrollPresentationMaxScroll = maxScroll;
                g_mainScrollPresentationStageHeight = std::max<int>(1, g_stage.bottom - g_stage.top);
            }
        }

        bool facingContinuous = UseFacingContinuousPresentation();
        // In facing layouts scrolling is a higher-priority presentation input
        // than finishing the previous zoom sample. Release the zoom gate now
        // so the new viewport can use its complete fallback/preview frame.
        if (tab && facingContinuous && tab->zoomPresentationPending)
            FinishZoomPresentationForScroll(hwnd, *tab);

        if (dy == 0)
        {
            UpdateVertScrollBar(hwnd);
            if (immediateRepaint)
            {
                if (!IsRectEmpty(&g_mainScrollTrackRect))
                    RedrawWindow(hwnd, &g_mainScrollTrackRect, nullptr, RDW_INVALIDATE | RDW_UPDATENOW | RDW_NOERASE);
                if (!IsRectEmpty(&g_mainHScrollTrackRect))
                    RedrawWindow(hwnd, &g_mainHScrollTrackRect, nullptr, RDW_INVALIDATE | RDW_UPDATENOW | RDW_NOERASE);
            }
            return;
        }

        if (!immediateRepaint)
            MarkStageScrolling(hwnd);

        bool pageChanged = tab && oldPage != tab->currentPage;
        UpdateVertScrollBar(hwnd);

        // Facing-page scrolling has a retained presentation frame of its own.
        // Prime a complete coarse representation first, then move the frame
        // immediately when that representation covers the new viewport.
        // Single-page reading retains the 2.5.9 path below.
        bool facingFrameShift = facingContinuous && tab;
        if (facingFrameShift)
            PrimeFacingScrollCoverage(hwnd, *tab);
        bool facingCoverageReady = facingFrameShift && !tab->zoomPresentationPending &&
            FacingScrollVisibleContentReady(*tab);
        bool targetReady = tab && !tab->zoomPresentationPending &&
            CurrentZoomVisibleContentReady(*tab);
        bool canShiftFacingFrame = facingFrameShift && facingCoverageReady && g_stageFrameValid &&
            !g_annotationToolbarOpen && !g_annotationNoteOpen &&
            std::abs(dy) < std::max<int>(1, g_stage.bottom - g_stage.top) * 3 / 4;
        bool canPreserveFrame = !facingFrameShift && (targetReady || dragFrame) && g_stageFrameValid &&
            !g_annotationToolbarOpen && !g_annotationNoteOpen &&
            std::abs(dy) < std::max<int>(1, g_stage.bottom - g_stage.top) * 3 / 4;
        if (facingFrameShift)
        {
            // Facing layouts use one compositor-owned frame. Do not combine
            // ScrollWindowEx with that frame: Windows would move the old
            // pixels while the renderer simultaneously paints the new spread,
            // which creates duplicate pages, background strips, and flashes.
            // The thumb is updated immediately; the reader is repainted from
            // the cache as one atomic double-buffered frame when coverage is
            // ready. Until then PaintPages keeps the last complete frame.
            g_pageNavigationPending = false;
            g_allowIncompletePageNavigationFrame = false;
            g_facingScrollPending = !facingCoverageReady;
            if (facingCoverageReady)
            {
                RequestStageRepaint(hwnd, pageChanged);
                RedrawMainScrollBarNow(hwnd);
            }
            else
            {
                if (pageChanged)
                {
                    RECT client{};
                    GetClientRect(hwnd, &client);
                    RECT status{ 0, client.bottom - S(34), client.right, client.bottom };
                    InvalidateRect(hwnd, &status, FALSE);
                }
                RedrawMainScrollBarNow(hwnd);
            }
        }
        else if (canShiftFacingFrame || canPreserveFrame)
        {
            g_pageNavigationPending = dragFrame;
            ScrollStagePixels(hwnd, 0, dy, pageChanged);
            RedrawMainScrollBarNow(hwnd);
        }
        else
        {
            g_pageNavigationPending = true;
            // Present the thumb before invalidating the reader. The latter
            // is intentionally asynchronous and may contain an uncached page.
            RedrawMainScrollBarNow(hwnd);
            RequestStageRepaint(hwnd, pageChanged);
        }
        if (tab)
        {
            if (UseTiledPageRendering(*tab))
                MaintainVisibleTileRenderQueueForScroll(*tab);
            else
                MaintainVisiblePageRenderQueueForScroll(*tab);
            if ((g_pageNavigationPending || g_facingScrollPending) && UseTiledPageRendering(*tab))
                QueueVisibleCommittedPagesForScroll(hwnd, *tab);
        }
        if (tab && !UseTiledPageRendering(*tab) && !StageScrollPaintInProgress())
        {
            SchedulePagePrefetch(hwnd);
        }
    }

    void CommitMainScrollDragTarget(HWND hwnd)
    {
        if (g_active < 0) return;
        int target = g_dragScrollTarget;
        // Rendering is always queued. Synchronously warming a page here
        // blocks the mouse message pump and makes the thumb stop following
        // the pointer on large documents.
        if (PdfTab* tab = Active())
        {
            if (target != g_scrollY)
                ScrollStageTo(hwnd, target, true, false);
            if (UseFacingContinuousPresentation())
            {
                FinishZoomPresentationForScroll(hwnd, *tab);
                // The drag path deliberately shows the last complete frame
                // while the pointer is moving. On release, keep the facing
                // transaction's own coverage gate; do not replace it with
                // the stricter current-zoom page gate, which can restore an
                // old frame over the newly exposed corner at low zoom.
                g_pageNavigationPending = false;
                g_allowIncompletePageNavigationFrame = false;
                PrimeFacingScrollCoverage(hwnd, *tab);
                g_facingScrollPending = !FacingScrollVisibleContentReady(*tab);
                UpdateVertScrollBar(hwnd);
                SchedulePagePrefetch(hwnd);
                RequestStageRepaint(hwnd, true);
            }
            else
            {
                // Single-page mode keeps the established complete viewport
                // submission path unchanged.
                RequestPageNavigationRepaint(hwnd, *tab, true);
            }
            SaveActiveTabProgress();
            if (g_continuousRead) SyncSidebarProgressFromScroll(hwnd, *tab);
        }
    }


    void FlushStageForTouch(HWND hwnd, int deltaY)
    {
        UNREFERENCED_PARAMETER(hwnd);
        UNREFERENCED_PARAMETER(deltaY);
    }

    void ScrollStageXTo(HWND hwnd, int newScrollX)
    {
        PdfTab* tab = Active();
        if (tab) g_contentWidth = ReadingContentWidth(*tab);
        int stageW = std::max<int>(1, g_stage.right - g_stage.left);
        int maxScroll = std::max<int>(0, g_contentWidth - stageW);
        int old = g_scrollX;
        g_scrollX = std::clamp(newScrollX, 0, maxScroll);
        if (old == g_scrollX)
        {
            UpdateVertScrollBar(hwnd);
            return;
        }
        MarkStageScrolling(hwnd);
        bool facingContinuous = UseFacingContinuousPresentation();
        if (facingContinuous && tab && tab->zoomPresentationPending)
            FinishZoomPresentationForScroll(hwnd, *tab);
        UpdateVertScrollBar(hwnd);
        bool facingFrameShift = facingContinuous && tab;
        if (facingFrameShift)
            PrimeFacingScrollCoverage(hwnd, *tab);
        bool facingCoverageReady = facingFrameShift && !tab->zoomPresentationPending &&
            FacingScrollVisibleContentReady(*tab);
        bool targetReady = tab && !tab->zoomPresentationPending &&
            CurrentZoomVisibleContentReady(*tab);
        // Horizontal facing movement uses the same complete-coverage rule as
        // vertical scrolling; the scrollbar never exposes a background strip.
        bool canShiftFacingFrame = facingFrameShift && facingCoverageReady && g_stageFrameValid &&
            !g_annotationToolbarOpen && !g_annotationNoteOpen &&
            std::abs(old - g_scrollX) < std::max<int>(1, g_stage.right - g_stage.left) * 3 / 4;
        bool canPreserveFrame = !facingFrameShift && targetReady && g_stageFrameValid &&
            !g_annotationToolbarOpen && !g_annotationNoteOpen &&
            std::abs(old - g_scrollX) < std::max<int>(1, g_stage.right - g_stage.left) * 3 / 4;
        if (facingFrameShift)
        {
            // Horizontal facing movement follows the same compositor-owned
            // frame rule as vertical movement. Native pixel scrolling is
            // intentionally excluded so the page can never be drawn twice.
            g_pageNavigationPending = false;
            g_facingScrollPending = !facingCoverageReady;
            if (facingCoverageReady)
            {
                RequestStageRepaint(hwnd, false);
                RedrawMainScrollBarNow(hwnd);
            }
            else
            {
                RedrawMainScrollBarNow(hwnd);
            }
        }
        else if (canShiftFacingFrame || canPreserveFrame)
        {
            g_pageNavigationPending = facingContinuous;
            ScrollStagePixels(hwnd, old - g_scrollX, 0, false);
            RedrawMainScrollBarNow(hwnd);
        }
        else
        {
            g_pageNavigationPending = true;
            RedrawMainScrollBarNow(hwnd);
            RequestStageRepaint(hwnd, false);
        }
    }

    void ScrollSidebarTo(HWND hwnd, int newScrollY)
    {
        int old = g_sidebarScrollY;
        int visible = std::max<int>(1, g_sidebar.bottom - SidebarScrollRect().top);
        int maxScroll = std::max<int>(0, g_sidebarContentHeight - visible);
        g_sidebarScrollY = std::clamp(newScrollY, 0, maxScroll);
        if (old == g_sidebarScrollY) return;
        RequestSidebarRepaint(hwnd);
    }

    int WheelPixels(int delta, int pixelsPerNotch, double& remainder)
    {
        double exact = remainder + static_cast<double>(delta) * static_cast<double>(pixelsPerNotch) / static_cast<double>(WHEEL_DELTA);
        int pixels = exact >= 0.0 ? static_cast<int>(std::floor(exact)) : static_cast<int>(std::ceil(exact));
        remainder = exact - static_cast<double>(pixels);
        return pixels;
    }

    void StartSmoothStageScroll(HWND hwnd, int target);
    bool ScrollByPanPixels(HWND hwnd, POINT clientPt, int deltaY, int deltaX = 0);
    void StopAutoScroll(HWND hwnd);
    void QueueTouchPanPixels(HWND hwnd, POINT clientPt, int deltaY, int deltaX = 0);
    bool DrawCachedImage(HDC dc, PageImage& image, RECT dest);

    void StopTouchMomentum(HWND hwnd)
    {
        g_touchMomentum = false;
        g_touchMomentumX = 0.0;
        g_touchMomentumY = 0.0;
        g_touchMomentumRemainderX = 0.0;
        g_touchMomentumRemainderY = 0.0;
        g_touchMomentumBoost = 0.0;
        KillTimer(hwnd, 18);
    }

    void AddTouchMomentumImpulse(HWND hwnd, POINT clientPt, int deltaY, int deltaX)
    {
        constexpr bool touchMomentumEnabled = false;
        if (!touchMomentumEnabled)
        {
            UNREFERENCED_PARAMETER(hwnd);
            UNREFERENCED_PARAMETER(clientPt);
            UNREFERENCED_PARAMETER(deltaY);
            UNREFERENCED_PARAMETER(deltaX);
            return;
        }
        if (deltaY == 0 && deltaX == 0) return;
        ULONGLONG now = GetTickCount64();
        ULONGLONG elapsedMs = g_touchMomentumLastInputMs ? now - g_touchMomentumLastInputMs : 32;
        double frames = std::clamp(static_cast<double>(std::max<ULONGLONG>(1, elapsedMs)) / 16.0, 0.45, 4.0);
        double sampleY = static_cast<double>(deltaY) / frames;
        double sampleX = static_cast<double>(deltaX) / frames;

        if (elapsedMs > 180)
            g_touchMomentumBoost = 0.0;
        g_touchMomentumBoost = std::min(1400.0, g_touchMomentumBoost * 0.72 + static_cast<double>(std::abs(deltaY) + std::abs(deltaX)) * 2.4);
        double multiplier = 1.35 + std::min(3.15, g_touchMomentumBoost / 500.0);

        g_touchMomentumY = std::clamp(sampleY * multiplier, -420.0, 420.0);
        g_touchMomentumX = std::clamp(sampleX * multiplier, -420.0, 420.0);
        g_touchMomentumPoint = clientPt;
        g_touchMomentumLastInputMs = now;
        g_touchMomentumLastTickMs = now;
        g_touchMomentum = std::abs(g_touchMomentumY) >= 0.8 || std::abs(g_touchMomentumX) >= 0.8;
        if (g_touchMomentum)
            SetTimer(hwnd, 18, 16, nullptr);
    }

    void StepTouchMomentum(HWND hwnd)
    {
        if (!g_touchMomentum)
        {
            StopTouchMomentum(hwnd);
            return;
        }

        ULONGLONG now = GetTickCount64();
        if (g_touchMomentumLastInputMs && now - g_touchMomentumLastInputMs < 42)
            return;
        double frames = std::clamp(static_cast<double>(std::max<ULONGLONG>(1, now - g_touchMomentumLastTickMs)) / 16.0, 0.5, 2.5);
        g_touchMomentumLastTickMs = now;

        double moveY = g_touchMomentumY * frames + g_touchMomentumRemainderY;
        double moveX = g_touchMomentumX * frames + g_touchMomentumRemainderX;
        int pixelsY = moveY >= 0.0 ? static_cast<int>(std::floor(moveY)) : static_cast<int>(std::ceil(moveY));
        int pixelsX = moveX >= 0.0 ? static_cast<int>(std::floor(moveX)) : static_cast<int>(std::ceil(moveX));
        g_touchMomentumRemainderY = moveY - static_cast<double>(pixelsY);
        g_touchMomentumRemainderX = moveX - static_cast<double>(pixelsX);

        if (pixelsY != 0 || pixelsX != 0)
            ScrollByPanPixels(hwnd, g_touchMomentumPoint, pixelsY, pixelsX);

        double decay = std::pow(0.955, frames);
        g_touchMomentumY *= decay;
        g_touchMomentumX *= decay;
        if (std::abs(g_touchMomentumY) < 0.32 && std::abs(g_touchMomentumX) < 0.32 &&
            std::abs(g_touchMomentumRemainderY) < 0.7 && std::abs(g_touchMomentumRemainderX) < 0.7)
        {
            StopTouchMomentum(hwnd);
        }
    }

    void CancelStageMotion(HWND hwnd)
    {
        g_smoothStageScroll = false;
        g_stageScrollTarget = g_scrollY;
        g_stageScrollPos = static_cast<double>(g_scrollY);
        g_stageScrollVelocity = 0.0;
        g_stageScrollLastTick = GetTickCount64();
        KillTimer(hwnd, 4);
        g_touchPanQueued = false;
        g_touchPanPendingX = 0;
        g_touchPanPendingY = 0;
        KillTimer(hwnd, 16);
        StopTouchMomentum(hwnd);
        g_stageWheelRemainder = 0.0;
        g_lastTouchFollowSign = 0;
        g_lastTouchFollowPaintMs = 0;
    }

    POINT CurrentZoomAnchorPoint()
    {
        if (Hit(g_stage, g_mousePos.x, g_mousePos.y))
            return g_mousePos;
        return POINT{
            (g_stage.left + g_stage.right) / 2,
            (g_stage.top + g_stage.bottom) / 2
        };
    }

    bool ZoomSourcePagesFullyVisible(PdfTab const& tab)
    {
        RECT reader = MainReaderPixelClip();
        if (IsRectEmpty(&reader) || tab.pageCount <= 0) return false;

        int firstPage = g_continuousRead
            ? std::max(0, FirstVisibleSpreadStart(tab))
            : FirstPageInSpread(std::clamp(tab.currentPage, 0, tab.pageCount - 1));
        int lastPage = g_continuousRead ? tab.pageCount : NextSpreadStart(tab, firstPage);
        bool foundPage = false;
        for (int start = firstPage; start < lastPage; start = NextSpreadStart(tab, start))
        {
            int y = g_continuousRead ? SpreadVisualTop(tab, start) : g_stage.top + S(28) - g_scrollY;
            if (g_continuousRead && y > reader.bottom) break;
            int count = SpreadPageCount(tab, start);
            for (int j = 0; j < count; ++j)
            {
                RECT pageRect{};
                if (!BuildSpreadPageRect(tab, start, y, start + j, pageRect)) continue;
                if (!Intersects(pageRect, reader)) continue;
                foundPage = true;
                if (pageRect.left < reader.left || pageRect.top < reader.top ||
                    pageRect.right > reader.right || pageRect.bottom > reader.bottom)
                    return false;
            }
        }
        return foundPage;
    }

    bool PresentZoomTransform(HWND hwnd, POINT anchor, double scale)
    {
        if (scale <= 0.0 || IsRectEmpty(&g_stage))
            return false;

        RECT client{};
        GetClientRect(hwnd, &client);
        HDC windowDc = GetDC(hwnd);
        if (!windowDc) return false;
        bool ready = EnsurePaintBuffer(windowDc,
            std::max<int>(1, client.right), std::max<int>(1, client.bottom));
        ready = ready && EnsureStageFrameBuffer(windowDc,
            std::max<int>(1, client.right), std::max<int>(1, client.bottom));
        if (!ready)
        {
            ReleaseDC(hwnd, windowDc);
            return false;
        }

        RECT reader = MainReaderPixelClip();
        if (IsRectEmpty(&reader))
        {
            ReleaseDC(hwnd, windowDc);
            return false;
        }

        // A low-zoom render can leave the retained frame invalid for a short
        // interval even though the previous page is already visible in the
        // window. Seed the compositor from that reader-only surface so every
        // wheel sample still gets an immediate proportional transform. The
        // scrollbars are outside `reader`, so their pixels cannot become part
        // of the zoom source; the next complete render replaces this snapshot.
        if (!g_stageFrameValid)
        {
            if (!BitBlt(g_stageFrameDc, reader.left, reader.top,
                reader.right - reader.left, reader.bottom - reader.top,
                windowDc, reader.left, reader.top, SRCCOPY))
            {
                ReleaseDC(hwnd, windowDc);
                return false;
            }
            g_stageFrameValid = true;
            g_stageFrameOffsetX = 0;
            g_stageFrameOffsetY = 0;
            g_stageFrameMotionX = 0;
            g_stageFrameMotionY = 0;
        }

        // Materialize the currently presented frame in a separate buffer. The
        // committed frame includes the page pixels underneath the transparent
        // scrollbar overlays. Transforming only `reader` leaves those pixels
        // at the old zoom, so a subsequent scrollbar-only repaint can expose
        // an old page behind the track. Keep the scrollbar out of the window
        // copy, but keep its underlay in the same transformed frame.
        RECT sourceArea = g_stageFrameValid ? g_stage : reader;
        Fill(g_paintBufferDc, sourceArea, T().stage);
        RECT visibleDest = sourceArea;
        if (g_stageFrameOffsetX > 0) visibleDest.left += g_stageFrameOffsetX;
        else if (g_stageFrameOffsetX < 0) visibleDest.right += g_stageFrameOffsetX;
        if (g_stageFrameOffsetY > 0) visibleDest.top += g_stageFrameOffsetY;
        else if (g_stageFrameOffsetY < 0) visibleDest.bottom += g_stageFrameOffsetY;
        // The custom scrollbars are transparent overlays inside `stage`.
        // Include the full stage in the transform source, including the
        // pixels underneath both tracks. Restricting this copy to `reader`
        // left the track underlay at the theme color (or an older frame) and
        // became visible as a stale page strip after zoom-then-drag.
        RECT visibleSource{};
        if (IntersectRect(&visibleSource, &visibleDest, &sourceArea))
        {
            int sourceX = visibleSource.left - g_stageFrameOffsetX;
            int sourceY = visibleSource.top - g_stageFrameOffsetY;
            BitBlt(g_paintBufferDc, visibleSource.left, visibleSource.top,
                visibleSource.right - visibleSource.left,
                visibleSource.bottom - visibleSource.top,
                g_stageFrameDc, sourceX, sourceY, SRCCOPY);
        }

        RECT transformed{
            anchor.x + static_cast<int>(std::floor((sourceArea.left - anchor.x) * scale)),
            anchor.y + static_cast<int>(std::floor((sourceArea.top - anchor.y) * scale)),
            anchor.x + static_cast<int>(std::ceil((sourceArea.right - anchor.x) * scale)),
            anchor.y + static_cast<int>(std::ceil((sourceArea.bottom - anchor.y) * scale))
        };
        int sourceW = std::max<int>(1, sourceArea.right - sourceArea.left);
        int sourceH = std::max<int>(1, sourceArea.bottom - sourceArea.top);

        // The area outside the transformed reader is part of the viewer
        // surface, not part of the old page. Keeping old pixels there makes a
        // zoom-out appear stuck at the previous size because the old page edge
        // remains visible around the smaller transformed page.
        Fill(g_stageFrameDc, sourceArea, T().stage);
        int frameState = SaveDC(g_stageFrameDc);
        IntersectClipRect(g_stageFrameDc, g_stage.left, g_stage.top, g_stage.right, g_stage.bottom);
        int oldMode = SetStretchBltMode(g_stageFrameDc, COLORONCOLOR);
        StretchBlt(g_stageFrameDc,
            transformed.left, transformed.top,
            transformed.right - transformed.left,
            transformed.bottom - transformed.top,
            g_paintBufferDc, sourceArea.left, sourceArea.top, sourceW, sourceH,
            SRCCOPY);
        SetStretchBltMode(g_stageFrameDc, oldMode);
        RestoreDC(g_stageFrameDc, frameState);

        // Compose the complete presentation frame off-screen. Foreground
        // chrome is part of this one transaction when it lies in the reader
        // (immersive mode); it is never covered and then repainted on the
        // HWND. The old two-submit sequence left the previous page color in
        // the toggle rectangle and made the exit pill flash after zoom.
        int composeState = SaveDC(g_paintBufferDc);
        IntersectClipRect(g_paintBufferDc, g_stage.left, g_stage.top,
            g_stage.right, g_stage.bottom);
        BitBlt(g_paintBufferDc, g_stage.left, g_stage.top,
            g_stage.right - g_stage.left, g_stage.bottom - g_stage.top,
            g_stageFrameDc, g_stage.left, g_stage.top, SRCCOPY);
        PaintMainScrollBar(g_paintBufferDc, client, g_stage);

        RECT toggle = Active() ? SidebarPanelTogglePaintRectForClient(client) : RECT{};
        if (!IsRectEmpty(&toggle) && Intersects(toggle, g_stage))
            PaintSidebarPanelToggle(g_paintBufferDc, client);
        if (g_immersive)
        {
            RECT exit = ImmersiveExitPanelPaintRectForClient(client);
            if (!IsRectEmpty(&exit) && Intersects(exit, g_stage))
            {
                int exitState = SaveDC(g_paintBufferDc);
                IntersectClipRect(g_paintBufferDc, exit.left, exit.top,
                    exit.right, exit.bottom);
                PaintStatus(g_paintBufferDc, client);
                RestoreDC(g_paintBufferDc, exitState);
            }
        }
        RestoreDC(g_paintBufferDc, composeState);

        int windowState = SaveDC(windowDc);
        BitBlt(windowDc, g_stage.left, g_stage.top,
            g_stage.right - g_stage.left, g_stage.bottom - g_stage.top,
            g_paintBufferDc, g_stage.left, g_stage.top, SRCCOPY);
        RestoreDC(windowDc, windowState);
        // The normal-layout rail toggle is outside the reader and remains
        // protected by the page copy. The immersive toggle was composed in
        // the same off-screen frame above, so neither path needs a second
        // window submission.
        ReleaseDC(hwnd, windowDc);
        g_stageFrameOffsetX = 0;
        g_stageFrameOffsetY = 0;
        g_stageFrameMotionX = 0;
        g_stageFrameMotionY = 0;
        return true;
    }

    void ApplyZoomAtPoint(HWND hwnd, PdfTab& tab, POINT clientPt, double newZoom)
    {
        double clampedZoom = std::clamp(newZoom, 0.0833, 64.0);
        if (std::abs(clampedZoom - tab.zoom) < 0.0001) return;
        CancelStageMotion(hwnd);
        double oldZoom = tab.zoom;
        PreservePageCacheForZoomTransition(tab, oldZoom);
        // Keep complete facing previews as a safe page-level handoff while
        // the target zoom is rendered. They are full page images, so mapping
        // them to the new spread geometry cannot create the clipped screen
        // rectangles produced by scaling the old reader screenshot.
        tab.facingPreviewDpi = g_dpi;
        tab.facingPreviewTheme = PdfRenderTheme();
        // Keep the old complete frame visible while the target generation is
        // rendered off-screen. It is replaced only after the target viewport
        // is complete, so no background-filled intermediate frame is shown.
        int anchorPage = std::clamp(tab.currentPage, 0, std::max(0, tab.pageCount - 1));
        double anchorX = 0.5;
        double anchorY = 0.5;
        RECT pageRect{};
        int hoveredPage = -1;
        if (PageRectAtPoint(tab, clientPt.x, clientPt.y, hoveredPage, pageRect))
        {
            anchorPage = hoveredPage;
            int pageW = std::max<int>(1, pageRect.right - pageRect.left);
            int pageH = std::max<int>(1, pageRect.bottom - pageRect.top);
            anchorX = std::clamp(static_cast<double>(clientPt.x - pageRect.left) / static_cast<double>(pageW), 0.0, 1.0);
            anchorY = std::clamp(static_cast<double>(clientPt.y - pageRect.top) / static_cast<double>(pageH), 0.0, 1.0);
        }
        // PaintPages keeps the transformed committed frame intact until the
        // target generation has complete visible coverage, then replaces it.
        CancelObsoletePageRendersForZoom(tab);
        // Keep the last complete presentation frame for one short quiet
        // period. Lower zoom levels often finish rendering faster than the
        // next wheel event arrives; committing each of those intermediate
        // pages exposes their moving edges and causes the down-zoom flicker.
        // The unchanged committed frame keeps every page edge intact while
        // the input path remains free for the next zoom sample.
        g_zoomRenderDeferUntil = GetTickCount64() + kZoomPresentationDebounceMs;
        KillTimer(hwnd, 21);
        SetTimer(hwnd, 21, static_cast<UINT>(kZoomPresentationDebounceMs), nullptr);
        tab.zoom = clampedZoom;
        // Keep one presentation rule for both whole-page and tiled rendering.
        // The old complete result remains the presentation frame; the new
        // result is committed only after the visible viewport is complete.
        tab.zoomPresentationPending = true;
        tab.zoomPresentationAnchorValid = false;
        // A toolbar tooltip is independent foreground chrome. Do not erase it
        // when the reader starts a zoom transaction: the stage can be replaced
        // several times while the pointer remains over the same button, and
        // erasing/repainting the tooltip here makes it flash or clip at every
        // zoom step. Paint's normal foreground pass will keep it on top.
        g_pageNavigationPending = false;
        // Zoom supersedes an in-flight facing scroll. If this flag survives
        // the zoom change, a later partial paint can restore the pre-zoom
        // frame over the new viewport and leave a blank corner or a vanished
        // page until another scroll invalidates the reader.
        g_facingScrollPending = false;
        ++g_viewportGeneration;
        if (!g_continuousRead) tab.currentPage = anchorPage;


        auto restoreHorizontalAnchor = [&]()
        {
            if (UseFacingContinuousPresentation())
            {
                // Match Sumatra's SetZoomVirtual(fixPt): after relayout,
                // preserve the page-space point under the pointer only when
                // the spread is wider than the reader. A spread that fits is
                // centered by SpreadX(), so its scroll offset must stay zero.
                int start = FirstPageInSpread(anchorPage);
                int stageW = std::max<int>(1, g_stage.right - g_stage.left);
                int spreadW = SpreadWidth(tab, start);
                if (spreadW + S(56) <= stageW)
                {
                    g_scrollX = 0;
                    return;
                }

                int pageOffsetX = PageOffsetXInSpread(tab, start, anchorPage);
                int pageW = std::max<int>(1, PageW(tab, anchorPage));
                int desiredX = g_stage.left + S(28) + pageOffsetX +
                    static_cast<int>(anchorX * pageW + 0.5) - clientPt.x;
                int spreadMaxScroll = std::max<int>(0, spreadW + S(56) - stageW);
                g_scrollX = std::clamp(desiredX, 0, spreadMaxScroll);
                return;
            }
            int savedScrollX = g_scrollX;
            g_scrollX = 0;
            RECT newPageRect{};
            int start = FirstPageInSpread(anchorPage);
            bool hasRect = BuildSpreadPageRect(tab, start, 0, anchorPage, newPageRect);
            g_scrollX = savedScrollX;
            if (!hasRect) return;
            int pageW = std::max<int>(1, newPageRect.right - newPageRect.left);
            int desiredX = newPageRect.left + static_cast<int>(anchorX * pageW + 0.5) - clientPt.x;
            // `tab.zoom` already contains the target zoom here. Do not use
            // the previous generation's g_contentWidth, or a zoom-out can
            // retain an oversized horizontal scroll range and move the
            // smaller facing spread partly outside the reader.
            int targetContentWidth = ReadingContentWidth(tab);
            int maxScrollX = std::max<int>(0, targetContentWidth - std::max<int>(1, g_stage.right - g_stage.left));
            g_scrollX = std::clamp(desiredX, 0, maxScrollX);
        };
        if (g_continuousRead)
        {
            g_contentHeight = ContinuousContentHeight(tab);
            g_contentWidth = ReadingContentWidth(tab);
            restoreHorizontalAnchor();
            int start = FirstPageInSpread(anchorPage);
            int spreadTop = SpreadTopScroll(tab, start);
            RECT targetPageRect{};
            int targetPageBaseY = g_stage.top + spreadTop;
            if (!BuildSpreadPageRect(tab, start, targetPageBaseY, anchorPage, targetPageRect))
                targetPageRect = RECT{ g_stage.left, targetPageBaseY,
                    g_stage.left + PageW(tab, anchorPage),
                    targetPageBaseY + PageH(tab, anchorPage) };
            int pageH = std::max<int>(1, targetPageRect.bottom - targetPageRect.top);
            int desiredScroll = targetPageRect.top +
                static_cast<int>(anchorY * pageH + 0.5) - clientPt.y;
            int maxScroll = std::max<int>(0, g_contentHeight - (g_stage.bottom - g_stage.top));
            g_scrollY = std::clamp(desiredScroll, 0, maxScroll);
            tab.currentPage = PageFromScroll(tab, g_scrollY);
            TouchRecentProgress(tab, false);
            SyncSidebarProgressFromScroll(hwnd, tab);
        }
        else
        {
            g_contentHeight = SinglePageContentHeight(tab);
            g_contentWidth = ReadingContentWidth(tab);
            restoreHorizontalAnchor();
            RECT targetPageRect{};
            int start = FirstPageInSpread(anchorPage);
            int targetPageBaseY = g_stage.top + S(28);
            int desiredScroll = targetPageBaseY +
                static_cast<int>(anchorY * std::max<int>(1, PageH(tab, anchorPage)) + 0.5) - clientPt.y;
            if (BuildSpreadPageRect(tab, start, targetPageBaseY, anchorPage, targetPageRect))
                desiredScroll = targetPageRect.top +
                    static_cast<int>(anchorY * (targetPageRect.bottom - targetPageRect.top) + 0.5) - clientPt.y;
            g_scrollY = std::clamp(desiredScroll, 0, SinglePageMaxScroll(tab));
            TouchRecentProgress(tab, false);
            KeepThumbnailSelectionVisible(hwnd, tab);
        }

        // The target viewport is now fully determined. Keep this exact scroll
        // position for the lifetime of the zoom handoff. Render completion is
        // asynchronous, and a late layout/clamp pass must not reinterpret the
        // new page geometry and move the document under the pointer.
        tab.zoomPresentationScrollX = g_scrollX;
        tab.zoomPresentationScrollY = g_scrollY;
        tab.zoomPresentationAnchorValid = true;

        if (g_viewMode != 0 && UseTiledPageRendering(tab))
        {
            // Zooming must compete only for the target-resolution visible
            // tiles. PrimeFacingScrollCoverage intentionally queues a coarse
            // scroll handoff first, which kept 50%-74% facing pages blurry
            // until the worker happened to finish level 0.
            if (tab.zoomPresentationPending)
                QueueVisibleZoomContent(tab);
            else
                PrimeFacingScrollCoverage(hwnd, tab);
        }
        else if (!UseTiledPageRendering(tab))
            WarmZoomPreviewPagesForCurrentView(tab, anchorPage);
        UpdateVertScrollBar(hwnd);

        // Compose the new facing layout only from complete page-level sources.
        // If an old page is not available in full, leave the previous complete
        // frame untouched until the worker supplies a valid replacement.
        // The transition surface must be made from complete cached pages at
        // the target geometry. A transformed screenshot of the old viewport
        // has no pixels for a page portion that was previously outside the
        // viewport, so it exposes the reader background at the lower/right
        // edge during zoom. This page-level handoff works for single, double,
        // and book layouts and keeps the layout's own centering rules.
        PresentZoomFallbackLayout(hwnd, tab);

        // The reader, fixed tracks and foreground chrome are one zoom frame.
        // Invalidating the old/new tracks separately queued extra paints that
        // alternated with the complete frame and made the thumb blink.
        InvalidateRect(hwnd, &g_stage, FALSE);
        RECT client{};
        GetClientRect(hwnd, &client);
        RECT status{ 0, client.bottom - S(34), client.right, client.bottom };
        InvalidateRect(hwnd, &status, FALSE);
        SchedulePagePrefetch(hwnd);
        ScheduleIdleCacheTrim(hwnd);
    }

    void FinishGestureZoom(HWND hwnd)
    {
        if (!g_gestureZooming) return;
        g_gestureZooming = false;
        g_gestureZoomRenderSuppressed = false;
        g_gestureZoomStartDistance = 0.0;
        g_gestureZoomStartValue = 0.0;
        if (PdfTab* tab = Active())
        {
            // Only the final gesture value enters the normal render queue.
            // The committed frame remains visible until this generation is
            // complete, so the release cannot expose partially rendered tiles.
            SchedulePagePrefetch(hwnd);
            if (UseTiledPageRendering(*tab))
                HighZoomVisiblePagesReady(hwnd, *tab);
            ScheduleIdleCacheTrim(hwnd);
        }
        RequestStageRepaint(hwnd, true);
    }

    void CloseCustomZoomDialog(HWND hwnd)
    {
        g_hasPressedButton = false;
        HideCaret(hwnd);
        DestroyCaret();
        g_customZoomOpen = false;
        g_customZoomFocused = false;
        g_customZoomText.clear();
        g_customZoomCaretIndex = 0;
        InvalidateRect(hwnd, nullptr, FALSE);
    }

    void OpenCustomZoomDialog(HWND hwnd)
    {
        PdfTab* tab = Active();
        if (!tab) return;
        int pct = static_cast<int>(tab->zoom * 100.0 + 0.5);
        g_customZoomText = std::to_wstring(std::clamp(pct, 1, 1600));
        g_customZoomCaretIndex = g_customZoomText.size();
        g_customZoomOpen = true;
        g_customZoomFocused = true;
        CreateCaret(hwnd, nullptr, std::max(1, S(1)), S(24));
        ShowCaret(hwnd);
        InvalidateRect(hwnd, nullptr, FALSE);
    }

    void CommitCustomZoomDialog(HWND hwnd)
    {
        PdfTab* tab = Active();
        if (!tab || g_customZoomText.empty())
        {
            CloseCustomZoomDialog(hwnd);
            return;
        }
        double pct = _wtof(g_customZoomText.c_str());
        pct = std::clamp(pct, 8.33, 1600.0);
        ApplyZoomAtPoint(hwnd, *tab, CurrentZoomAnchorPoint(), pct / 100.0);
        CloseCustomZoomDialog(hwnd);
    }

    void UpdateCustomZoomCaret(HWND hwnd)
    {
        if (!g_customZoomOpen || !g_customZoomFocused || IsRectEmpty(&g_zoomDialogInputRect)) return;
        g_customZoomCaretIndex = std::min(g_customZoomCaretIndex, g_customZoomText.size());
        HDC dc = GetDC(hwnd);
        if (!dc) return;
        HFONT font = Font(13, FW_SEMIBOLD);
        HGDIOBJ oldFont = SelectObject(dc, font);
        SIZE prefixSize{};
        GetTextExtentPoint32W(dc, g_customZoomText.c_str(), static_cast<int>(g_customZoomCaretIndex), &prefixSize);
        SelectObject(dc, oldFont);
        DeleteObject(font);
        ReleaseDC(hwnd, dc);
        int x = std::clamp(g_zoomDialogInputRect.left + S(14) + prefixSize.cx,
            g_zoomDialogInputRect.left + S(14), g_zoomDialogInputRect.right - S(48));
        SetCaretPos(x, g_zoomDialogInputRect.top + S(9));
    }

    size_t CustomZoomCaretIndexAtX(HWND hwnd, int x)
    {
        HDC dc = GetDC(hwnd);
        if (!dc) return g_customZoomText.size();
        HFONT font = Font(13, FW_SEMIBOLD);
        HGDIOBJ oldFont = SelectObject(dc, font);
        int relativeX = std::max<int>(0, x - (g_zoomDialogInputRect.left + S(14)));
        size_t result = g_customZoomText.size();
        for (size_t i = 0; i < g_customZoomText.size(); ++i)
        {
            SIZE before{}, after{};
            GetTextExtentPoint32W(dc, g_customZoomText.c_str(), static_cast<int>(i), &before);
            GetTextExtentPoint32W(dc, g_customZoomText.c_str(), static_cast<int>(i + 1), &after);
            if (relativeX < (before.cx + after.cx) / 2) { result = i; break; }
        }
        SelectObject(dc, oldFont);
        DeleteObject(font);
        ReleaseDC(hwnd, dc);
        return result;
    }

    bool ScrollSinglePageByPixels(HWND hwnd, PdfTab& tab, int deltaY)
    {
        if (deltaY == 0) return true;
        int maxScroll = SinglePageMaxScroll(tab);
        if (deltaY > 0)
        {
            if (maxScroll > 0 && g_scrollY < maxScroll)
            {
                ScrollStageTo(hwnd, std::min(maxScroll, g_scrollY + deltaY));
                return true;
            }
            if (tab.currentPage < tab.pageCount - 1)
            {
                tab.currentPage = std::min(tab.pageCount - 1, NextSpreadStart(tab, FirstPageInSpread(tab.currentPage)));
                g_scrollY = 0;
                g_contentHeight = SinglePageContentHeight(tab);
                TouchRecentProgress(tab, false);
                KeepThumbnailSelectionVisible(hwnd, tab);
                UpdateVertScrollBar(hwnd);
                InvalidateRect(hwnd, nullptr, FALSE);
                SchedulePagePrefetch(hwnd);
            }
            return true;
        }

        if (maxScroll > 0 && g_scrollY > 0)
        {
            ScrollStageTo(hwnd, std::max(0, g_scrollY + deltaY));
            return true;
        }
        if (tab.currentPage > 0)
        {
            int previous = 0;
            for (int start = 0; start < tab.currentPage; start = NextSpreadStart(tab, start))
                previous = start;
            tab.currentPage = previous;
            g_contentHeight = SinglePageContentHeight(tab);
            g_scrollY = SinglePageMaxScroll(tab);
            TouchRecentProgress(tab, false);
            KeepThumbnailSelectionVisible(hwnd, tab);
            UpdateVertScrollBar(hwnd);
            InvalidateRect(hwnd, nullptr, FALSE);
            SchedulePagePrefetch(hwnd);
        }
        return true;
    }

    bool ScrollByWheelDelta(HWND hwnd, POINT clientPt, int delta, bool ctrlDown)
    {
        PdfTab* tab = Active();
        if (g_favoriteListOpen && Hit(g_favoriteListRect, clientPt.x, clientPt.y))
        {
            int pixels = WheelPixels(delta, S(52), g_stageWheelRemainder);
            if (pixels != 0) ScrollFavoriteListTo(hwnd, g_favoriteListScrollY - pixels);
            return true;
        }
        if (g_tabListOpen && Hit(g_tabListRect, clientPt.x, clientPt.y))
        {
            int pixels = WheelPixels(delta, S(52), g_stageWheelRemainder);
            if (pixels != 0) ScrollTabListTo(hwnd, g_tabListScrollY - pixels);
            return true;
        }
        if (ctrlDown && tab)
        {
            StopTouchMomentum(hwnd);
            ApplyZoomAtPoint(hwnd, *tab, clientPt, tab->zoom + (delta > 0 ? 0.08 : -0.08));
            return true;
        }

        if (tab && (GetKeyState(VK_SHIFT) & 0x8000))
        {
            StopTouchMomentum(hwnd);
            int pixels = WheelPixels(delta, S(64), g_stageWheelRemainder);
            if (pixels != 0)
            {
                ScrollStageXTo(hwnd, g_scrollX - pixels);
            }
            return true;
        }

        if (SidebarVisible() && Hit(g_sidebar, clientPt.x, clientPt.y))
        {
            int pixels = WheelPixels(delta, S(52), g_sidebarWheelRemainder);
            if (pixels != 0)
            {
                g_smoothSidebarScroll = false;
                KillTimer(hwnd, 5);
                ScrollSidebarTo(hwnd, g_sidebarScrollY - pixels);
            }
            return true;
        }

        if (tab && std::abs(delta) < WHEEL_DELTA)
        {
            StopTouchMomentum(hwnd);
            int pixels = WheelPixels(delta, S(48), g_stageWheelRemainder);
            if (pixels != 0)
            {
                g_smoothStageScroll = false;
                KillTimer(hwnd, 4);
                ScrollByPanPixels(hwnd, clientPt, pixels, 0);
            }
            return true;
        }

        if (tab && !g_continuousRead)
        {
            StopTouchMomentum(hwnd);
            int pixels = WheelPixels(delta, S(48), g_stageWheelRemainder);
            if (pixels != 0)
            {
                int maxScroll = SinglePageMaxScroll(*tab);
                int desired = g_scrollY - pixels;
                if (desired >= 0 && desired <= maxScroll)
                {
                    g_smoothStageScroll = false;
                    KillTimer(hwnd, 4);
                    ScrollStageTo(hwnd, desired);
                }
                else
                {
                    g_smoothStageScroll = false;
                    KillTimer(hwnd, 4);
                    ScrollSinglePageByPixels(hwnd, *tab, -pixels);
                }
            }
            return true;
        }

        if (!tab)
        {
            int pixels = WheelPixels(delta, S(52), g_stageWheelRemainder);
            if (pixels != 0) ScrollHomeTo(hwnd, g_homeScrollY - pixels);
            return true;
        }

        int pixels = WheelPixels(delta, S(48), g_stageWheelRemainder);
        if (pixels != 0)
        {
            StopTouchMomentum(hwnd);
            g_smoothStageScroll = false;
            KillTimer(hwnd, 4);
            ScrollStageTo(hwnd, g_scrollY - pixels);
        }
        return true;
    }

    bool ScrollByPanPixels(HWND hwnd, POINT clientPt, int deltaY, int deltaX)
    {
        if (deltaY == 0 && deltaX == 0) return true;
        if (g_favoriteListOpen && Hit(g_favoriteListRect, clientPt.x, clientPt.y))
        {
            if (deltaY != 0) ScrollFavoriteListTo(hwnd, g_favoriteListScrollY - deltaY);
            return true;
        }
        if (g_tabListOpen && Hit(g_tabListRect, clientPt.x, clientPt.y))
        {
            if (deltaY != 0) ScrollTabListTo(hwnd, g_tabListScrollY - deltaY);
            return true;
        }
        if (SidebarVisible() && Hit(g_sidebar, clientPt.x, clientPt.y))
        {
            g_smoothSidebarScroll = false;
            KillTimer(hwnd, 5);
            if (deltaY != 0) ScrollSidebarTo(hwnd, g_sidebarScrollY - deltaY);
            return true;
        }

        PdfTab* tab = Active();
        if (!tab)
        {
            if (deltaY != 0) ScrollHomeTo(hwnd, g_homeScrollY - deltaY);
            return true;
        }
        if (tab && deltaX != 0)
        {
            ScrollStageXTo(hwnd, g_scrollX - deltaX);
        }
        if (tab && !g_continuousRead)
        {
            g_smoothStageScroll = false;
            KillTimer(hwnd, 4);
            if (deltaY != 0)
            {
                return ScrollSinglePageByPixels(hwnd, *tab, -deltaY);
            }
            return true;
        }

        g_smoothStageScroll = false;
        KillTimer(hwnd, 4);
        if (deltaY != 0)
        {
            ScrollStageTo(hwnd, g_scrollY - deltaY);
        }
        return true;
    }

    double AutoScrollAxisSpeed(int delta)
    {
        int deadZone = std::max(4, S(7));
        int distance = std::abs(delta);
        if (distance <= deadZone) return 0.0;
        double speed = static_cast<double>(distance - deadZone) / 10.0;
        speed = std::min(speed, 85.0);
        return delta < 0 ? -speed : speed;
    }

    void UpdateAutoScrollSpeed(HWND hwnd)
    {
        POINT pt{};
        if (!GetCursorPos(&pt)) return;
        ScreenToClient(hwnd, &pt);
        g_mousePos = pt;
        g_autoScrollXSpeed = AutoScrollAxisSpeed(pt.x - g_autoScrollAnchor.x);
        g_autoScrollYSpeed = AutoScrollAxisSpeed(pt.y - g_autoScrollAnchor.y);
    }

    void StopAutoScroll(HWND hwnd)
    {
        if (!g_autoScrollActive) return;
        g_autoScrollActive = false;
        g_autoScrollXSpeed = 0.0;
        g_autoScrollYSpeed = 0.0;
        g_autoScrollXAccum = 0.0;
        g_autoScrollYAccum = 0.0;
        g_autoScrollLastTick = 0;
        KillTimer(hwnd, 19);
        SetCursor(LoadCursorW(nullptr, IDC_ARROW));
    }

    void ToggleAutoScroll(HWND hwnd, POINT anchor)
    {
        if (g_autoScrollActive)
        {
            StopAutoScroll(hwnd);
            return;
        }
        PdfTab* tab = Active();
        if (!tab || !Hit(g_stage, anchor.x, anchor.y)) return;
        CancelStageMotion(hwnd);
        ClearTextSelection();
        ClearAnnotationFocus();
        g_autoScrollActive = true;
        g_autoScrollAnchor = anchor;
        g_autoScrollXSpeed = 0.0;
        g_autoScrollYSpeed = 0.0;
        g_autoScrollXAccum = 0.0;
        g_autoScrollYAccum = 0.0;
        g_autoScrollLastTick = GetTickCount64();
        UpdateAutoScrollSpeed(hwnd);
        SetTimer(hwnd, 19, 10, nullptr);
        SetCursor(LoadCursorW(nullptr, IDC_SIZEALL));
    }

    void StepAutoScroll(HWND hwnd)
    {
        PdfTab* tab = Active();
        if (!g_autoScrollActive || !tab)
        {
            StopAutoScroll(hwnd);
            return;
        }

        UpdateAutoScrollSpeed(hwnd);
        ULONGLONG now = GetTickCount64();
        ULONGLONG elapsedMs = g_autoScrollLastTick ? now - g_autoScrollLastTick : 10;
        g_autoScrollLastTick = now;
        double scale = std::clamp(static_cast<double>(std::max<ULONGLONG>(1, elapsedMs)) / 20.0, 0.05, 3.0);
        g_autoScrollXAccum += g_autoScrollXSpeed * scale;
        g_autoScrollYAccum += g_autoScrollYSpeed * scale;
        int dx = g_autoScrollXAccum >= 0.0 ? static_cast<int>(std::floor(g_autoScrollXAccum)) : static_cast<int>(std::ceil(g_autoScrollXAccum));
        int dy = g_autoScrollYAccum >= 0.0 ? static_cast<int>(std::floor(g_autoScrollYAccum)) : static_cast<int>(std::ceil(g_autoScrollYAccum));
        g_autoScrollXAccum -= static_cast<double>(dx);
        g_autoScrollYAccum -= static_cast<double>(dy);

        if (dx != 0)
            ScrollStageXTo(hwnd, g_scrollX + dx);
        if (dy != 0)
        {
            if (g_continuousRead) ScrollStageTo(hwnd, g_scrollY + dy, true, false);
            else ScrollSinglePageByPixels(hwnd, *tab, dy);
        }
    }

    void UpdateSelectionAutoScroll(HWND hwnd, int x, int y)
    {
        if (!g_selectingContent || !g_continuousRead || !Active())
        {
            if (g_selectionAutoScroll)
            {
                g_selectionAutoScroll = false;
                KillTimer(hwnd, 23);
            }
            return;
        }

        int edge = std::max<int>(S(24), std::min<int>(S(72), (g_stage.bottom - g_stage.top) / 8));
        bool nearTop = y < g_stage.top + edge;
        bool nearBottom = y > g_stage.bottom - edge;
        if (!nearTop && !nearBottom)
        {
            if (g_selectionAutoScroll)
            {
                g_selectionAutoScroll = false;
                KillTimer(hwnd, 23);
            }
            return;
        }

        g_selectionAutoScroll = true;
        SetTimer(hwnd, 23, 16, nullptr);
    }

    void StepSelectionAutoScroll(HWND hwnd)
    {
        if (!g_selectionAutoScroll || !g_selectingContent || !g_continuousRead)
        {
            KillTimer(hwnd, 23);
            g_selectionAutoScroll = false;
            return;
        }
        PdfTab* tab = Active();
        if (!tab)
        {
            KillTimer(hwnd, 23);
            g_selectionAutoScroll = false;
            return;
        }

        POINT cursor{};
        if (!GetCursorPos(&cursor)) return;
        ScreenToClient(hwnd, &cursor);
        int edge = std::max<int>(S(24), std::min<int>(S(72), (g_stage.bottom - g_stage.top) / 8));
        int delta = 0;
        if (cursor.y < g_stage.top + edge)
        {
            int distance = g_stage.top + edge - cursor.y;
            delta = -std::clamp(S(4) + distance / 3, S(4), S(34));
        }
        else if (cursor.y > g_stage.bottom - edge)
        {
            int distance = cursor.y - (g_stage.bottom - edge);
            delta = std::clamp(S(4) + distance / 3, S(4), S(34));
        }
        else
        {
            KillTimer(hwnd, 23);
            g_selectionAutoScroll = false;
            return;
        }

        int oldScroll = g_scrollY;
        ScrollStageTo(hwnd, g_scrollY + delta, true, false);
        if (oldScroll == g_scrollY)
        {
            KillTimer(hwnd, 23);
            g_selectionAutoScroll = false;
            return;
        }

        g_selectionEnd = cursor;
        UpdateSelectionEndpointPage(*tab, cursor.x, cursor.y);
        if (RefreshTextSelection(*tab))
        {
            RememberDragTextSelection();
            g_hasContentSelection = true;
            g_selectionIsImage = false;
        }
        InvalidateRect(hwnd, &g_stage, FALSE);
    }
    void QueueTouchPanPixels(HWND hwnd, POINT clientPt, int deltaY, int deltaX)
    {
        if (deltaY == 0 && deltaX == 0) return;
        g_touchPanPendingY += deltaY;
        g_touchPanPendingX += deltaX;
        g_touchPanPoint = clientPt;
        if (!g_touchPanQueued)
        {
            g_touchPanQueued = true;
            SetTimer(hwnd, 16, 8, nullptr);
        }
    }

    void FlushTouchPan(HWND hwnd)
    {
        if (!g_touchPanQueued) return;
        int dx = g_touchPanPendingX;
        int dy = g_touchPanPendingY;
        g_touchPanPendingX = 0;
        g_touchPanPendingY = 0;
        g_touchPanQueued = false;
        KillTimer(hwnd, 16);
        if (dx != 0 || dy != 0)
        {
            ScrollByPanPixels(hwnd, g_touchPanPoint, dy, dx);
            FlushStageForTouch(hwnd, dy);
            AddTouchMomentumImpulse(hwnd, g_touchPanPoint, dy, dx);
        }
    }

    int ClampStageScrollValue(int value)
    {
        PdfTab* tab = Active();
        if (tab)
        {
            g_contentHeight = g_continuousRead ? ContinuousContentHeight(*tab) : SinglePageContentHeight(*tab);
        }
        int maxScroll = std::max<int>(0, g_contentHeight - std::max<int>(1, g_stage.bottom - g_stage.top));
        return std::clamp(value, 0, maxScroll);
    }

    int ClampSidebarScrollValue(int value)
    {
        int visible = std::max<int>(1, g_sidebar.bottom - SidebarScrollRect().top);
        int maxScroll = std::max<int>(0, g_sidebarContentHeight - visible);
        return std::clamp(value, 0, maxScroll);
    }

    int ActiveSidebarModeIndex()
    {
        return std::clamp(g_sideMode, 0, 3);
    }

    void SaveActiveTabSearchState(PdfTab& tab)
    {
        tab.searchQuery = g_searchQuery;
        tab.searchLastQuery = g_searchLastQuery;
        tab.searchResults = g_searchResults;
        tab.searchCurrent = g_searchCurrent;
        tab.searchHasRun = g_searchHasRun;
        tab.searchMatchCase = g_searchMatchCase;
    }

    void RestoreActiveTabSearchState(PdfTab& tab)
    {
        g_searchQuery = tab.searchQuery;
        g_searchLastQuery = tab.searchLastQuery;
        g_searchResults = tab.searchResults;
        g_searchCurrent = std::clamp(tab.searchCurrent, 0,
            std::max(0, static_cast<int>(g_searchResults.size()) - 1));
        g_searchHasRun = tab.searchHasRun;
        g_searchMatchCase = tab.searchMatchCase;
        g_searchInputFocused = false;
        g_searchCaretIndex = static_cast<int>(g_searchQuery.size());
        g_searchSelectionAnchor = -1;
        g_searchCaretVisible = true;
        g_searchResultRects.clear();
        g_searchResultIds.clear();
    }

    void SaveActiveTabSidebarState(PdfTab& tab)
    {
        tab.sidebarScrollY[ActiveSidebarModeIndex()] = std::max(0, g_sidebarScrollY);
        tab.selectedOutlineRow = g_selectedOutlineRow;
        tab.collapsedOutlineRows = g_collapsedOutlineRows;
        tab.sidebarRailOpen = g_sidebarRailOpen;
        tab.sidebarContentOpen = g_sidebarOpen;
        tab.sidebarMode = ActiveSidebarModeIndex();
        tab.sidebarWidth = std::clamp(
            std::max(g_sidebarExpandedWidth, g_sidebarWidth),
            SidebarMinimumWidth(), S(520));
        tab.sidebarStateExplicit = true;
        SaveActiveTabSearchState(tab);
    }

    void SaveActiveTabProgress()
    {
        PdfTab* tab = Active();
        if (!tab) return;
        tab->savedScrollY = g_scrollY;
        if (g_continuousRead)
            tab->currentPage = PageFromScroll(*tab, g_scrollY);
        SaveActiveTabSidebarState(*tab);
        TouchRecentProgress(*tab, false);
    }

    void RestoreActiveTabSidebarState(HWND hwnd)
    {
        KillTimer(hwnd, 5);
        g_smoothSidebarScroll = false;
        g_draggingSidebarScroll = false;
        // A restored outline row is authoritative until the user starts a
        // real document scroll. Without this short-lived override, the first
        // paint can derive a neighboring row from fallback page geometry and
        // visibly move the saved selection before metadata settles.
        ClearOutlineNavigationOverride();

        PdfTab* tab = Active();
        if (!tab)
        {
            g_sideMode = 0;
            g_sidebarRailOpen = true;
            g_sidebarOpen = true;
            g_sidebarScrollY = 0;
            g_sidebarScrollTargetY = 0;
            g_selectedOutlineRow = -1;
            g_collapsedOutlineRows.clear();
            return;
        }

        g_sideMode = std::clamp(tab->sidebarMode, 0, 3);
        RestoreActiveTabSearchState(*tab);

        int restoredWidth = tab->sidebarWidth > 0
            ? tab->sidebarWidth
            : g_sidebarExpandedWidth;
        restoredWidth = std::clamp(restoredWidth, SidebarMinimumWidth(), S(520));
        g_sidebarExpandedWidth = restoredWidth;
        g_sidebarWidth = restoredWidth;
        g_sidebarTargetWidth = restoredWidth;
        tab->sidebarWidth = restoredWidth;
        g_sidebarAnimating = false;
        KillTimer(hwnd, 11);

        int mode = ActiveSidebarModeIndex();
        g_sidebarRailOpen = tab->sidebarRailOpen;
        g_sidebarOpen = tab->sidebarContentOpen;
        g_sidebarScrollY = std::max(0, tab->sidebarScrollY[mode]);
        g_sidebarScrollTargetY = g_sidebarScrollY;
        g_selectedOutlineRow = tab->selectedOutlineRow;
        g_collapsedOutlineRows = tab->collapsedOutlineRows;

        if (g_sideMode == 0 && !tab->outlineMetadataLoaded && g_selectedOutlineRow >= 0)
        {
            // Keep the persisted row authoritative while the worker is still
            // building the outline. Fallback page geometry can run first,
            // but it must not replace the saved item with a neighbor.
            g_outlineNavigationRow = g_selectedOutlineRow;
            g_outlineNavigationRenderVersion = tab->renderVersion;
        }
        else if (g_sideMode == 0 && tab->outlineMetadataLoaded && !tab->outline.empty())
        {
            if (g_selectedOutlineRow < 0 || g_selectedOutlineRow >= static_cast<int>(tab->outline.size()))
                g_selectedOutlineRow = OutlineRowFromScroll(*tab, g_scrollY);
            tab->selectedOutlineRow = g_selectedOutlineRow;
            if (g_selectedOutlineRow >= 0)
            {
                g_outlineNavigationRow = g_selectedOutlineRow;
                g_outlineNavigationRenderVersion = tab->renderVersion;
            }
        }
        else if (g_sideMode == 0 && tab->outlineMetadataLoaded)
        {
            g_selectedOutlineRow = -1;
            tab->selectedOutlineRow = -1;
            ClearOutlineNavigationOverride();
        }

        InvalidateSidebarChrome(hwnd);
    }

    void SwitchSidebarMode(HWND hwnd, int mode)
    {
        mode = std::clamp(mode, 0, 3);
        if (!Active()) return;
        if (mode == g_sideMode) return;
        if (PdfTab* tab = Active()) SaveActiveTabSidebarState(*tab);
        if (g_favoriteListOpen)
            CloseFavoriteList(hwnd);
        else
            g_hoverFavoriteItem = -1;
        if (mode != 0)
        {
            g_outlineSearchFocused = false;
            g_outlineSearchExpanded = false;
            g_outlineSearchCaretVisible = true;
            KillTimer(hwnd, 13);
        }
        g_sideMode = mode;
        if (PdfTab* tab = Active()) tab->sidebarMode = mode;
        RestoreActiveTabSidebarState(hwnd);
    }

    int SidebarRailItemAtPoint(HWND hwnd, int x, int y)
    {
        if (!Active() || !SidebarRailVisible()) return -1;
        RECT client{};
        if (!hwnd || !GetClientRect(hwnd, &client)) return -1;
        int tabWidth = S(34);
        int tabGap = S(5);
        int railWidth = S(44);
        int tabLeft = std::max<int>(0, (railWidth - tabWidth) / 2);
        if (x < tabLeft || x >= tabLeft + tabWidth) return -1;
        // Use the same freshly rebuilt client geometry as the paint pass. In
        // particular, do not let a stale toolbar/sidebar snapshot decide
        // whether a rapid click belongs to the rail.
        int relativeY = y - g_sidebar.top - S(10);
        int stride = tabWidth + tabGap;
        if (relativeY < 0 || relativeY >= stride * 4) return -1;
        int item = relativeY / stride;
        if (relativeY % stride >= tabWidth) return -1;
        return item;
    }

    bool HandleSidebarRailClick(HWND hwnd, int item)
    {
        if (item < 0 || item >= 4 || !Active() || !SidebarRailVisible()) return false;

        int tabWidth = S(34);
        int tabGap = S(5);
        int railWidth = S(44);
        int tabLeft = std::max<int>(0, (railWidth - tabWidth) / 2);
        RECT pressedRect{
            tabLeft,
            g_sidebar.top + S(10) + item * (tabWidth + tabGap),
            tabLeft + tabWidth,
            g_sidebar.top + S(10) + item * (tabWidth + tabGap) + tabWidth };
        g_pressedButtonRect = pressedRect;
        g_hasPressedButton = true;
        SetTimer(hwnd, 2, 90, nullptr);

        bool sameMode = item == g_sideMode;
        if (sameMode)
        {
            // The active rail button is the direct toggle for its content
            // panel after the panel's close button has hidden that panel.
            g_sidebarOpen = !g_sidebarOpen;
        }
        else
        {
            g_sidebarRailOpen = true;
            SwitchSidebarMode(hwnd, item);
            g_sidebarOpen = true;
        }
        g_sidebarRailOpen = true;
        if (g_immersive)
        {
            g_immersiveSidebarOpen = true;
            g_lastImmersiveSidebarOpen = true;
        }
        if (PdfTab* active = Active()) SaveActiveTabSidebarState(*active);
        g_searchInputFocused = g_sideMode == 2;
        if (g_searchInputFocused)
        {
            g_searchCaretIndex = static_cast<int>(g_searchQuery.size());
            g_searchCaretVisible = true;
            SetTimer(hwnd, 12, 500, nullptr);
        }
        InvalidateRect(hwnd, nullptr, FALSE);
        UpdateWindow(hwnd);
        return true;
    }

    bool HandleSidebarControlClick(HWND hwnd, int x, int y)
    {
        if (!Active()) return false;

        // WM_LBUTTONDBLCLK is the second press of a fast double click. It
        // must have exactly the same target priority as WM_LBUTTONDOWN;
        // otherwise the page double-click handler consumes it and the user
        // has to click a second time to toggle the sidebar.
        RefreshReaderHitGeometry(hwnd);
        if (int railItem = SidebarRailItemAtPoint(hwnd, x, y); railItem >= 0)
        {
            HandleSidebarRailClick(hwnd, railItem);
            return true;
        }
        if (SidebarVisible() && Hit(g_sidebarContentCloseRect, x, y))
        {
            g_pressedButtonRect = g_sidebarContentCloseRect;
            g_hasPressedButton = true;
            SetTimer(hwnd, 2, 90, nullptr);
            g_sidebarOpen = false;
            CloseFavoriteList(hwnd);
            SaveActiveTabSidebarState(*Active());
            InvalidateRect(hwnd, nullptr, FALSE);
            UpdateWindow(hwnd);
            return true;
        }

        RECT client{};
        if (GetClientRect(hwnd, &client))
        {
            RECT panelToggle = SidebarPanelToggleRectForClient(client);
            if (Hit(panelToggle, x, y))
            {
                g_pressedButtonRect = panelToggle;
                g_hasPressedButton = true;
                SetTimer(hwnd, 2, 90, nullptr);
                InvalidateRect(hwnd, &panelToggle, FALSE);
                Command(hwnd, CmdSidebarPanelToggle);
                UpdateWindow(hwnd);
                return true;
            }
        }
        if (g_sideMode == 0 && SidebarVisible() &&
            !IsRectEmpty(&g_outlineToggleAllRect) &&
            Hit(g_outlineToggleAllRect, x, y))
        {
            g_pressedButtonRect = g_outlineToggleAllRect;
            g_hasPressedButton = true;
            SetTimer(hwnd, 2, 90, nullptr);
            InvalidateRect(hwnd, &g_outlineToggleAllRect, FALSE);
            Command(hwnd, CmdOutlineToggleAll);
            return true;
        }
        return false;
    }

    void RestoreActiveTabPosition(HWND hwnd)
    {
        PdfTab* tab = Active();
        if (!tab)
        {
            g_scrollY = 0;
            return;
        }
        if (g_continuousRead)
        {
            g_contentHeight = ContinuousContentHeight(*tab);
            int maxScroll = std::max<int>(0, g_contentHeight - std::max<int>(1, g_stage.bottom - g_stage.top));
            int desired = tab->savedScrollY;
            if (tab->pendingSessionPosition && tab->metadataGeometryComplete)
            {
                int page = std::clamp(tab->pendingSessionPage, 0, tab->pageCount - 1);
                desired = (tab->pendingSessionPageOffset
                    ? PageTopScroll(*tab, page)
                    : SpreadTopScroll(*tab, page)) + tab->pendingSessionOffsetY;
                tab->currentPage = page;
                tab->pendingSessionPosition = false;
                tab->pendingSessionPageOffset = false;
            }
            g_scrollY = std::clamp(desired, 0, maxScroll);
            if (!tab->pendingSessionPosition)
                tab->currentPage = PageFromScroll(*tab, g_scrollY);
        }
        else
        {
            g_contentHeight = SinglePageContentHeight(*tab);
            g_scrollY = std::clamp(tab->savedScrollY, 0, SinglePageMaxScroll(*tab));
        }
        UpdateVertScrollBar(hwnd);
        SchedulePagePrefetch(hwnd);
    }

    void ActivateTab(HWND hwnd, int index)
    {
        if (index < 0 || index >= static_cast<int>(g_tabs.size()))
            return;
        if (g_active == index)
        {
            EnsureTabWindowVisible(g_active);
            g_tabListOpen = false;
            return;
        }
        SaveActiveTabProgress();
        // A page-number editor belongs to the old Tab. Clear it before the
        // status bar is rebuilt so old and new page indicators cannot overlap.
        g_pageInputFocused = false;
        g_pageInputText.clear();
        g_pageCaretIndex = 0;
        g_pageSelectionAnchor = -1;
        KillTimer(hwnd, 10);
        g_active = index;
        g_tabs[static_cast<size_t>(index)]->lastActivatedSerial = ++g_tabActivationSerial;
        g_sidebarKeyboardFocus = false;
        EnsureTabWindowVisible(g_active);
        g_tabListOpen = false;
        RestoreActiveTabPosition(hwnd);
        if (PdfTab* target = Active(); target && g_viewMode != 0)
            g_scrollX = PreferredFacingScrollX(*target);
        RestoreActiveTabSidebarState(hwnd);
        // A pending page-navigation commit belongs to the previous Tab. Do
        // not make the new Tab wait for that old viewport to become complete.
        g_pageNavigationPending = false;
        g_facingScrollPending = false;
        g_stageIdleRefreshPending = false;
        g_stageLightPaintUntil = 0;
        g_smoothStageScroll = false;
        KillTimer(hwnd, 4);
        if (PdfTab* target = Active())
        {
            ResumeActiveTabMetadata(hwnd, *target);
            // Do not cancel a MuPDF render or walk every inactive Tab while
            // processing the mouse click. Those are maintenance operations,
            // so defer them until the newly selected Tab has had a chance to
            // paint its already committed frame.
            // Initial raster scheduling and cache arbitration are deliberately
            // posted after the cached frame has been presented. This keeps a
            // large PDF from making the tab click wait on the shared worker.
            SetTimer(hwnd, 25, 1, nullptr);
        }
        ScheduleIdleCacheTrim(hwnd);
        SetTitle();
        // File watcher replacement can join the old directory thread. Keep
        // that housekeeping out of the visible tab-switch transaction.
        PostMessageW(hwnd, WM_QUIETPDF_REFRESH_FILE_WATCH, 0, 0);
        // The committed stage frame belongs to the previous Tab. It cannot
        // gate the first paint of the newly selected document.
        g_stageFrameValid = false;
        g_stageFrameOffsetX = 0;
        g_stageFrameOffsetY = 0;
        g_stageFrameMotionX = 0;
        g_stageFrameMotionY = 0;
        g_mainScrollPresentationValid = false;
        PresentCachedTabFrame(hwnd);
        PresentTabChrome(hwnd);
        InvalidateRect(hwnd, &g_stage, FALSE);
    }

    void StartSmoothStageScroll(HWND hwnd, int target)
    {
        g_stageScrollTarget = ClampStageScrollValue(target);
        if (!g_smoothStageScroll)
        {
            g_stageScrollPos = static_cast<double>(g_scrollY);
            g_stageScrollVelocity = 0.0;
        }
        g_stageScrollLastTick = GetTickCount64();
        g_smoothStageScroll = true;
        SetTimer(hwnd, 4, 16, nullptr);
    }

    void StartSmoothSidebarScroll(HWND hwnd, int target)
    {
        g_sidebarScrollTargetY = ClampSidebarScrollValue(target);
        g_smoothSidebarScroll = true;
        SetTimer(hwnd, 5, 12, nullptr);
    }

    void StartSidebarPanelAnimation(HWND hwnd, bool open)
    {
        bool wasOpen = g_sidebarOpen;
        g_sidebarRailOpen = true;
        if (open)
        {
            g_sidebarOpen = true;
            if (!wasOpen || g_sidebarWidth <= S(44)) g_sidebarWidth = 0;
            g_sidebarTargetWidth = std::clamp(g_sidebarExpandedWidth, SidebarMinimumWidth(), S(520));
        }
        else
        {
            if (g_sidebarWidth > S(120)) g_sidebarExpandedWidth = g_sidebarWidth;
            g_sidebarTargetWidth = 0;
        }
        g_sidebarAnimating = true;
        g_sidebarAnimationStartWidth = g_sidebarWidth;
        g_sidebarAnimationStartMs = GetTickCount64();
        SetTimer(hwnd, 11, 16, nullptr);
        InvalidateRect(hwnd, nullptr, FALSE);
    }

    bool HitSidebarSplitter(int x, int y)
    {
        return SidebarVisible() && Active() &&
            std::abs(x - g_sidebarWidth) <= S(5) &&
            y >= g_sidebar.top && y <= g_sidebar.bottom;
    }

    void ClampSidebarScroll()
    {
        int visible = std::max<int>(1, g_sidebar.bottom - SidebarScrollRect().top);
        int maxScroll = std::max<int>(0, g_sidebarContentHeight - visible);
        g_sidebarScrollY = std::clamp(g_sidebarScrollY, 0, maxScroll);
    }

    void PaintToolbar(HDC dc, RECT client)
    {
        if (g_immersive) return;
        RECT bar{ 0, 0, client.right, S(38) };
        if (IsGraphiteTheme()) Fill(dc, bar, RGB(29, 32, 36));
        else GlassSurface(dc, bar, g_statusPinned ? 154 : 188);
        HPEN pen = CreatePen(PS_SOLID, 1, ChromeDividerColor());
        auto oldPen = SelectObject(dc, pen);
        MoveToEx(dc, 0, bar.bottom - 1, nullptr);
        LineTo(dc, client.right, bar.bottom - 1);
        SelectObject(dc, oldPen);
        DeleteObject(pen);
        HFONT f = Font(9);
        auto oldFont = SelectObject(dc, f);
        int x = S(18);
        auto add = [&](int id, const wchar_t* text, int w, const wchar_t* tip)
        {
            RECT r{ x, S(4), x + S(w), S(34) };
            AddButton(id, r, text, tip);
            DrawFlatMenuItem(dc, { id, r, text, tip });
            x += S(w + 16);
        };
        add(CmdHome, L"\u9996\u9875", 42, L"");
        add(CmdOpen, L"\u6253\u5f00", 42, L"");
        add(CmdSearch, L"\u67e5\u627e", 42, L"");
        add(CmdBookmark, L"\u4e66\u7b7e", 42, L"");
        add(CmdTheme, L"\u4e3b\u9898", 42, L"");
        add(CmdView, L"\u89c6\u56fe", 42, L"");
        add(CmdSettings, L"\u5e2e\u52a9", 42, L"");
        SelectObject(dc, oldFont);
        DeleteObject(f);
    }

    void PaintTabs(HDC dc, RECT client)
    {
        g_tabRects.clear();
        g_tabRectIds.clear();
        g_tabTitleTruncated.clear();
        g_tabNavPrevRect = {};
        g_tabNavNextRect = {};
        g_tabCountRect = {};
        if (g_immersive) return;
        RECT bar{ 0, S(38), client.right, S(76) };
        if (IsGraphiteTheme()) Fill(dc, bar, RGB(35, 39, 44));
        else GlassSurface(dc, bar, 142);
        HPEN pen = CreatePen(PS_SOLID, 1, ChromeDividerColor());
        auto oldPen = SelectObject(dc, pen);
        MoveToEx(dc, 0, bar.bottom - 1, nullptr);
        LineTo(dc, client.right, bar.bottom - 1);
        SelectObject(dc, oldPen);
        DeleteObject(pen);
        HFONT f = Font(9);
        auto oldFont = SelectObject(dc, f);
        int top = S(46);
        int bottom = S(71);
        int left = S(8);
        int gap = S(6);
        int countW = S(60);
        int plusW = S(26);
        int navW = S(24);
        g_tabCountRect = RECT{ client.right - S(10) - countW, top, client.right - S(10), bottom };
        bool showNav = static_cast<int>(g_tabs.size()) > MaxVisibleTabs;
        if (showNav)
        {
            g_tabNavNextRect = RECT{ g_tabCountRect.left - S(8) - navW, top, g_tabCountRect.left - S(8), bottom };
            g_tabNavPrevRect = RECT{ g_tabNavNextRect.left - S(4) - navW, top, g_tabNavNextRect.left - S(4), bottom };
        }
        int controlsLeft = showNav ? g_tabNavPrevRect.left : g_tabCountRect.left;
        int tabRight = controlsLeft - S(12) - plusW - gap;
        int totalTabs = static_cast<int>(g_tabs.size());
        int visibleCount = std::min(totalTabs, MaxVisibleTabs);
        EnsureTabWindowVisible(g_active);
        int start = std::clamp(g_tabVisibleStart, 0, std::max(0, totalTabs - visibleCount));
        int tabW = visibleCount > 0
            ? std::clamp((tabRight - left - gap * std::max(0, visibleCount - 1)) / visibleCount, S(98), S(170))
            : S(138);
        int plusLeft = visibleCount > 0 ? left + visibleCount * (tabW + gap) : left;
        plusLeft = std::clamp(plusLeft, left, controlsLeft - S(12) - plusW);
        RECT plusRect{ plusLeft, top, plusLeft + plusW, bottom };

        std::vector<int> tabSlots;
        bool draggingVisible = g_tabDragFloating &&
            g_draggingTabIndex >= start &&
            g_draggingTabIndex < start + visibleCount &&
            g_draggingTabIndex >= 0 &&
            g_draggingTabIndex < totalTabs;
        if (draggingVisible)
        {
            int insertAt = std::clamp(g_tabDragInsertIndex, start, start + visibleCount);
            for (int actual = start; actual < start + visibleCount && actual < totalTabs; ++actual)
            {
                if (actual == insertAt) tabSlots.push_back(-1);
                if (actual != g_draggingTabIndex) tabSlots.push_back(actual);
            }
            if (insertAt == start + visibleCount) tabSlots.push_back(-1);
            while (static_cast<int>(tabSlots.size()) > visibleCount) tabSlots.pop_back();
        }
        else
        {
            for (int actual = start; actual < start + visibleCount && actual < totalTabs; ++actual)
                tabSlots.push_back(actual);
        }

        for (int i = 0; i < visibleCount && i < static_cast<int>(tabSlots.size()); ++i)
        {
            int actualIndex = tabSlots[static_cast<size_t>(i)];
            int x = left + i * (tabW + gap);
            RECT r{ x, top, x + tabW, bottom };
            if (actualIndex < 0)
            {
                COLORREF gapFill = MixColor(T().panel, T().stage, IsDarkTheme() ? 0.34 : 0.58);
                COLORREF gapLine = MixColor(T().line, T().panel, IsDarkTheme() ? 0.30 : 0.42);
                RoundFillAA(dc, r, S(9), gapFill, gapLine);
                continue;
            }
            if (actualIndex >= totalTabs) break;
            g_tabRects.push_back(r);
            g_tabRectIds.push_back(actualIndex);
            bool active = actualIndex == g_active;
            bool hovered = actualIndex == g_hoverTab;
            if (IsGlassTheme() || IsAuroraTheme())
            {
                if (active || hovered)
                {
                    if (IsAuroraTheme())
                    {
                        COLORREF tabFill = active ? MixColor(T().panel2, T().accent, 0.055) : SidebarHoverFill();
                        COLORREF tabLine = active ? MixColor(T().line, T().accent, 0.18) : MixColor(T().line, T().panel, 0.22);
                        RoundFillAA(dc, r, S(9), tabFill, tabLine);
                    }
                    else
                    {
                        AlphaFill(dc, r, RGB(255, 255, 255), active ? 132 : 112);
                        RoundFillAA(dc, r, S(9),
                            active ? RGB(239, 246, 251) : RGB(255, 255, 255),
                            active ? RGB(198, 211, 224) : RGB(230, 235, 241));
                        AlphaFill(dc, RECT{ r.left + S(1), r.top + S(1), r.right - S(1), r.top + S(8) }, RGB(255, 255, 255), 36);
                    }
                }
                else
                {
                    if (IsAuroraTheme())
                    {
                        RoundFillAA(dc, r, S(9), T().panel, MixColor(T().line, T().panel, 0.28));
                    }
                    else
                    {
                        constexpr COLORREF tabBarFill = RGB(250, 251, 253);
                        RoundFillAA(dc, r, S(9), tabBarFill, RGB(230, 235, 241));
                    }
                }
            }
            else
            {
                COLORREF fill{};
                COLORREF line{};
                if (IsGraphiteTheme())
                {
                    fill = active ? RGB(44, 48, 54) : (hovered ? RGB(44, 48, 53) : RGB(35, 39, 44));
                    line = RGB(48, 52, 58);
                }
                else
                {
                    fill = (active || hovered) ? T().panel2 : T().panel;
                    line = (active || hovered) ? T().line : MixColor(T().line, T().panel, IsDarkTheme() ? 0.20 : 0.14);
                }
                RoundFillAA(dc, r, S(9), fill, line);
            }
            PdfTab const& tab = *g_tabs[static_cast<size_t>(actualIndex)];
            bool dirty = tab.dirty;
            RECT text{ r.left + S(11), r.top, r.right - S(dirty ? 42 : 28), r.bottom };
            Text(dc, tab.name, text, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS, T().text);
            SIZE nameSize{};
            GetTextExtentPoint32W(dc, tab.name.c_str(), static_cast<int>(tab.name.size()), &nameSize);
            g_tabTitleTruncated.push_back(nameSize.cx > std::max<int>(0, static_cast<int>(text.right - text.left)));
            if (dirty)
            {
                RECT mark{ r.right - S(42), r.top + S(2), r.right - S(27), r.bottom - S(2) };
                HFONT markFont = Font(10, FW_SEMIBOLD);
                HGDIOBJ oldMarkFont = SelectObject(dc, markFont);
                Text(dc, L"*", mark, DT_CENTER | DT_VCENTER | DT_SINGLELINE, IsDarkTheme() ? RGB(255, 210, 92) : RGB(216, 143, 35));
                SelectObject(dc, oldMarkFont);
                DeleteObject(markFont);
            }
            RECT close{ r.right - S(24), r.top + S(2), r.right - S(4), r.bottom - S(2) };
            bool closeHover = g_hoverTabClose == actualIndex;
            int closeCx = (close.left + close.right) / 2;
            int closeCy = (close.top + close.bottom) / 2;
            if (closeHover)
            {
                DrawFilledCircle(dc, closeCx, closeCy, S(6.7f), RGB(255, 92, 92));
                DrawCloseGlyph(dc, close, RGB(255, 255, 255));
            }
            else if (hovered)
            {
                DrawCloseGlyph(dc, close, MixColor(T().muted, T().text, 0.12));
            }
            else if (active)
            {
                COLORREF activeDot = IsGraphiteTheme() ? RGB(254, 105, 0) : T().accent;
                DrawFilledCircle(dc, closeCx, closeCy, S(3.2f), activeDot);
            }
            if (false && closeHover)
            {
                RoundFill(dc, close, S(14), RGB(255, 92, 92), RGB(255, 92, 92));
                Text(dc, L"\u00d7", close, DT_CENTER | DT_VCENTER | DT_SINGLELINE, RGB(255, 255, 255));
            }
            else if (false && active)
            {
                HBRUSH dot = CreateSolidBrush(RGB(35, 200, 75));
                auto oldBrush = SelectObject(dc, dot);
                auto oldDotPen = SelectObject(dc, GetStockObject(NULL_PEN));
                Ellipse(dc, close.left + S(9), close.top + S(9), close.left + S(17), close.top + S(17));
                SelectObject(dc, oldDotPen);
                SelectObject(dc, oldBrush);
                DeleteObject(dot);
            }
        }

        auto drawUtilityButton = [&](RECT r, bool active, bool showIdleBorder = false)
        {
            bool hover = Hit(r, g_mousePos.x, g_mousePos.y);
            bool pressed = g_hasPressedButton && EqualRect(&g_pressedButtonRect, &r);
            COLORREF fill = active ? MixColor(T().panel2, T().accent, IsDarkTheme() ? 0.24 : 0.10) : T().panel;
            COLORREF line = active ? MixColor(T().line, T().accent, 0.40) : T().line;
            if (IsGlassTheme() || IsAuroraTheme())
            {
                if (IsAuroraTheme())
                {
                    COLORREF utilFill = active ? MixColor(T().panel2, T().accent, 0.06) : (hover ? SidebarHoverFill() : T().panel);
                    COLORREF utilLine = active ? MixColor(T().line, T().accent, 0.20) : MixColor(T().line, T().panel, 0.22);
                    RoundFillAA(dc, r, S(9), utilFill, utilLine);
                }
                else
                {
                    constexpr COLORREF tabBarFill = RGB(250, 251, 253);
                    COLORREF utilFill = pressed ? RGB(232, 236, 241)
                        : (active ? RGB(247, 250, 253) : (hover ? RGB(255, 255, 255) : tabBarFill));
                    COLORREF utilLine = pressed ? RGB(202, 210, 220)
                        : (active ? RGB(208, 218, 228) : (hover ? RGB(228, 234, 241) : (showIdleBorder ? T().line : tabBarFill)));
                    RoundFillAA(dc, r, S(9), utilFill, utilLine);
                }
            }
            else
            {
                if (IsGraphiteTheme())
                {
                    COLORREF utilityFill = pressed ? RGB(77, 83, 91) : (active ? RGB(44, 48, 54) : (hover ? RGB(44, 48, 53) : RGB(35, 39, 44)));
                    RoundFillAA(dc, r, S(9), utilityFill, RGB(48, 52, 58));
                }
                else
                    RoundFillAA(dc, r, S(9), pressed ? T().panel2 : (hover ? T().panel2 : fill), hover ? MixColor(line, T().text, 0.08) : line);
            }
        };

        AddButton(CmdOpen, plusRect, L"+", L"\u6253\u5f00\u65b0\u6587\u6863");
        drawUtilityButton(plusRect, false, true);
        DrawPlusGlyph(dc, plusRect, T().muted);

        if (showNav)
        {
            AddButton(CmdTabNavPrev, g_tabNavPrevRect, L"", L"\u4e0a\u4e00\u4e2a\u6807\u7b7e\u9875");
            AddButton(CmdTabNavNext, g_tabNavNextRect, L"", L"\u4e0b\u4e00\u4e2a\u6807\u7b7e\u9875");
            drawUtilityButton(g_tabNavPrevRect, false);
            drawUtilityButton(g_tabNavNextRect, false);
            DrawTabArrowGlyph(dc, g_tabNavPrevRect, false, T().muted);
            DrawTabArrowGlyph(dc, g_tabNavNextRect, true, T().muted);
        }

        AddButton(CmdTabListToggle, g_tabCountRect, L"", L"\u5168\u90e8\u6807\u7b7e\u9875");
        drawUtilityButton(g_tabCountRect, g_tabListOpen, true);
        RECT countText{ g_tabCountRect.left + S(6), g_tabCountRect.top, g_tabCountRect.right - S(18), g_tabCountRect.bottom };
        HFONT countFont = Font(9);
        HGDIOBJ oldCountFont = SelectObject(dc, countFont);
        Text(dc, std::to_wstring(totalTabs), countText, DT_CENTER | DT_VCENTER | DT_SINGLELINE, T().text);
        SelectObject(dc, oldCountFont);
        DeleteObject(countFont);
        DrawDownCaret(dc, g_tabCountRect.right - S(12), (g_tabCountRect.top + g_tabCountRect.bottom) / 2, T().muted);
        SelectObject(dc, oldFont);
        DeleteObject(f);
    }


    void PaintTabDragOverlay(HDC dc)
    {
        int totalTabs = static_cast<int>(g_tabs.size());
        if (!(g_tabDragFloating && g_draggingTabIndex >= 0 && g_draggingTabIndex < totalTabs))
            return;

        RECT r = g_tabDragCurrentRect;
        OffsetRect(&r, 0, g_tabDetachArmed ? S(2) : 0);
        DrawRoundedShadow(dc, r, S(10.0f), S(2), S(5), S(8), IsDarkTheme() ? 54 : 32);
        COLORREF floatFill = IsAuroraTheme() ? MixColor(T().panel2, T().accent, 0.06) : T().panel2;
        COLORREF floatLine = MixColor(T().line, T().accent, g_tabDetachArmed ? 0.46 : 0.22);
        RoundFill(dc, r, S(9), floatFill, floatLine);
        PdfTab const& tab = *g_tabs[static_cast<size_t>(g_draggingTabIndex)];
        HFONT f = Font(9);
        HGDIOBJ oldFont = SelectObject(dc, f);
        RECT textRect{ r.left + S(11), r.top, r.right - S(tab.dirty ? 42 : 28), r.bottom };
        Text(dc, tab.name, textRect, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS, T().text);
        if (tab.dirty)
        {
            RECT mark{ r.right - S(42), r.top + S(2), r.right - S(27), r.bottom - S(2) };
            HFONT markFont = Font(10, FW_SEMIBOLD);
            HGDIOBJ oldMarkFont = SelectObject(dc, markFont);
            Text(dc, L"*", mark, DT_CENTER | DT_VCENTER | DT_SINGLELINE, IsDarkTheme() ? RGB(255, 210, 92) : RGB(216, 143, 35));
            SelectObject(dc, oldMarkFont);
            DeleteObject(markFont);
        }
        RECT close{ r.right - S(24), r.top + S(2), r.right - S(4), r.bottom - S(2) };
        DrawSoftCircle(dc, (close.left + close.right) / 2, (close.top + close.bottom) / 2, S(3), T().accent);
        SelectObject(dc, oldFont);
        DeleteObject(f);
    }

    void PaintTabListOverlay(HDC dc, RECT client)
    {
        g_tabListItemRects.clear();
        g_tabListItemIds.clear();
        g_tabListRect = {};
        g_tabListScrollTrackRect = {};
        g_tabListScrollThumbRect = {};
        g_tabListContentHeight = 0;
        if (!g_tabListOpen || g_immersive || g_tabs.empty()) return;

        int rowH = S(31);
        int panelW = std::clamp<int>(client.right / 3, S(240), S(332));
        int availableHeight = std::max<int>(S(56),
            static_cast<int>(client.bottom - g_tabCountRect.bottom - S(18)));
        g_tabListContentHeight = static_cast<int>(g_tabs.size()) * rowH;
        int panelH = std::min(availableHeight,
            std::max<int>(S(56), g_tabListContentHeight + S(12)));
        int left = std::max<int>(S(8), static_cast<int>(g_tabCountRect.right - panelW));
        g_tabListRect = RECT{ left, g_tabCountRect.bottom + S(6), left + panelW, g_tabCountRect.bottom + S(6) + panelH };
        g_tabListScrollY = ClampTabListScrollValue(client, g_tabListScrollY);

        if (!IsDarkTheme())
            DrawRoundedShadow(dc, g_tabListRect, S(10.0f), S(1), S(4), S(5), 22);
        // The tab list spans multiple surfaces (tab bar and reader area). A
        // flat opaque surface prevents the underlying surfaces from showing
        // through as an unintended horizontal color split.
        FlatRoundedSurface(dc, g_tabListRect, S(11.0f));

        RECT content{ g_tabListRect.left + S(8), g_tabListRect.top + S(6), g_tabListRect.right - S(8), g_tabListRect.bottom - S(6) };
        bool needsScroll = g_tabListContentHeight > (content.bottom - content.top);
        if (needsScroll) content.right -= S(10);

        int saved = SaveDC(dc);
        IntersectClipRect(dc, content.left, content.top, content.right, content.bottom);
        HFONT font = Font(9);
        HGDIOBJ oldFont = SelectObject(dc, font);
        int y = content.top - g_tabListScrollY;
        for (int i = 0; i < static_cast<int>(g_tabs.size()); ++i)
        {
            RECT row{ content.left, y, content.right, y + rowH - S(2) };
            if (row.bottom >= content.top - rowH && row.top <= content.bottom)
            {
                g_tabListItemRects.push_back(row);
                g_tabListItemIds.push_back(i);
                bool active = i == g_active;
                bool hover = i == g_hoverTabListItem;
                if (active || hover)
                {
                    COLORREF fill = active ? MixColor(T().panel2, T().accent, IsDarkTheme() ? 0.22 : 0.10) : SidebarHoverFill();
                    COLORREF line = active ? MixColor(T().line, T().accent, 0.36) : fill;
                    RoundFill(dc, row, S(8), fill, line);
                }
                RECT mark{ row.left + S(10), row.top + S(8), row.left + S(20), row.bottom - S(8) };
                if (active) DrawSoftCircle(dc, (mark.left + mark.right) / 2, (mark.top + mark.bottom) / 2, S(3), T().accent);
                RECT text{ row.left + S(24), row.top, row.right - S(12), row.bottom };
                Text(dc, g_tabs[static_cast<size_t>(i)]->name, text, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS, T().text);
            }
            y += rowH;
        }
        SelectObject(dc, oldFont);
        DeleteObject(font);
        RestoreDC(dc, saved);

        if (needsScroll)
        {
            g_tabListScrollTrackRect = RECT{ g_tabListRect.right - S(10), content.top, g_tabListRect.right - S(6), content.bottom };
            int trackH = std::max<int>(1, g_tabListScrollTrackRect.bottom - g_tabListScrollTrackRect.top);
            int thumbH = std::clamp(MulDiv(content.bottom - content.top, trackH, std::max(1, g_tabListContentHeight)), S(28), trackH);
            int maxScroll = std::max<int>(1, g_tabListContentHeight - (content.bottom - content.top));
            int travel = std::max<int>(0, trackH - thumbH);
            int thumbTop = g_tabListScrollTrackRect.top + MulDiv(g_tabListScrollY, travel, maxScroll);
            g_tabListScrollThumbRect = RECT{ g_tabListScrollTrackRect.left, thumbTop, g_tabListScrollTrackRect.right, thumbTop + thumbH };
            bool active = g_draggingTabListScroll || Hit(g_tabListRect, g_mousePos.x, g_mousePos.y);
            int centerX = (g_tabListScrollTrackRect.left + g_tabListScrollTrackRect.right) / 2;
            int visualW = active ? S(4) : std::max(2, S(2));
            RECT thumb{ centerX - visualW / 2, g_tabListScrollThumbRect.top, centerX + (visualW + 1) / 2, g_tabListScrollThumbRect.bottom };
            DrawScrollThumbAA(dc, thumb, S(5), ScrollThumbColor(active));
        }
    }

    void PaintHome(HDC dc, RECT client)
    {
        g_recentRects.clear();
        HFONT titleFont = Font(24, FW_SEMIBOLD);
        auto oldFont = SelectObject(dc, titleFont);
        RECT title{ S(42), S(118), client.right - S(42), S(164) };
        Text(dc, L"\u6700\u8fd1\u9605\u8bfb", title, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().text);
        SelectObject(dc, oldFont);
        DeleteObject(titleFont);
        HFONT f = Font(10);
        oldFont = SelectObject(dc, f);
        RECT openCard{ S(42), S(188), S(212), S(398) };
        g_recentRects.push_back(openCard);
        RoundFill(dc, openCard, S(8), T().panel2, T().line);
        RECT openText{ openCard.left + S(16), openCard.top + S(72), openCard.right - S(16), openCard.bottom - S(20) };
        Text(dc, L"\u6253\u5f00 PDF\n\n\u62d6\u5165\u6587\u4ef6\u6216\u70b9\u51fb\u8fd9\u91cc\u5f00\u59cb\u9605\u8bfb", openText, DT_CENTER | DT_WORDBREAK, T().text);
        int x = S(238);
        int y = S(188);
        for (size_t i = 0; i < g_recent.size() && i < 12; ++i)
        {
            RECT card{ x, y, x + S(170), y + S(210) };
            g_recentRects.push_back(card);
            RoundFill(dc, card, S(8), T().panel, T().line);
            RECT cover{ card.left + S(42), card.top + S(20), card.right - S(42), card.top + S(134) };
            RoundFill(dc, cover, S(4), T().paper, T().line);
            Text(dc, L"PDF", cover, DT_CENTER | DT_VCENTER | DT_SINGLELINE, T().accent);
            RECT name{ card.left + S(12), card.top + S(146), card.right - S(12), card.top + S(174) };
            Text(dc, g_recent[i].name, name, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS, T().text);
            RECT meta{ card.left + S(12), card.top + S(174), card.right - S(12), card.bottom - S(10) };
            Text(dc, L"\u7b2c" + std::to_wstring(g_recent[i].page) + L" \u9875", meta, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().muted);
            x += S(196);
            if (x + S(170) > client.right - S(36))
            {
                x = S(42);
                y += S(236);
            }
        }
        SelectObject(dc, oldFont);
        DeleteObject(f);
    }

    void AddHomeHit(RECT r, int recentIndex, HomeAction action, std::wstring tip)
    {
        g_homeHits.push_back(HomeHit{ r, recentIndex, action, std::move(tip) });
    }

    bool HomeHitHovered(size_t index)
    {
        return g_hoverHomeHit == static_cast<int>(index);
    }

    void DrawHomeIconButton(HDC dc, RECT hot, HomeAction action, bool active, size_t hitIndex, bool visible = false, int iconInset = 6, bool hoverBackground = true)
    {
        bool hover = HomeHitHovered(hitIndex);
        bool pressed = g_hasPressedButton && EqualRect(&g_pressedButtonRect, &hot);
        if (!visible && !hover && !active && !pressed) return;
        COLORREF fill = pressed ? MixColor(T().accent, T().paper, IsDarkTheme() ? 0.34 : 0.70)
            : (active ? MixColor(T().accent, T().paper, IsDarkTheme() ? 0.24 : 0.78) : (hover ? SidebarHoverFill() : T().panel2));
        COLORREF line = fill;
        if (action == HomeAction::Remove)
        {
            fill = pressed ? RGB(255, 224, 224) : (hover ? RGB(255, 238, 238) : T().panel2);
            line = fill;
        }
        if (pressed || active || (hover && hoverBackground)) RoundFill(dc, hot, S(7), fill, line);
        RECT icon{ hot.left + S(iconInset), hot.top + S(iconInset), hot.right - S(iconInset), hot.bottom - S(iconInset) };
        COLORREF color = action == HomeAction::Remove
            ? (hover || pressed ? RGB(238, 73, 78) : RGB(225, 92, 92))
            : (pressed || hover || active ? T().accent : SidebarIconColor());
        DrawHomeIcon(dc, icon, action, color, active);
    }

    void DrawHomeTextButton(HDC dc, RECT r, HomeAction action, const std::wstring& label, size_t hitIndex)
    {
        bool hover = HomeHitHovered(hitIndex);
        if (hover) RoundFill(dc, r, S(8), SidebarHoverFill(), SidebarHoverFill());
        RECT icon{ r.left + S(8), r.top + S(7), r.left + S(26), r.bottom - S(7) };
        DrawHomeIcon(dc, icon, action, SidebarIconColor());
        RECT text{ r.left + S(31), r.top, r.right - S(8), r.bottom };
        Text(dc, label, text, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS, T().muted);
    }

    void SetImeCompositionPoint(HWND hwnd, POINT pt)
    {
        HIMC imc = ImmGetContext(hwnd);
        if (!imc) return;

        COMPOSITIONFORM composition{};
        composition.dwStyle = CFS_POINT;
        composition.ptCurrentPos = pt;
        ImmSetCompositionWindow(imc, &composition);

        CANDIDATEFORM candidate{};
        candidate.dwIndex = 0;
        candidate.dwStyle = CFS_CANDIDATEPOS;
        candidate.ptCurrentPos = POINT{ pt.x, pt.y + S(4) };
        ImmSetCandidateWindow(imc, &candidate);
        ImmReleaseContext(hwnd, imc);
    }
    void PaintHomeHeader(HDC dc, RECT client)
    {
        int tileW = S(152);
        int gapX = S(28);
        int boundaryLeft = S(42);
        int boundaryRight = std::max<int>(boundaryLeft + tileW, client.right - S(42));
        int availableW = std::max<int>(tileW, boundaryRight - boundaryLeft);
        int columns = std::max<int>(1, (availableW + gapX) / (tileW + gapX));
        int contentW = columns * tileW + std::max(0, columns - 1) * gapX;
        int contentLeft = boundaryLeft + std::max(0, (availableW - contentW) / 2);
        int contentRight = contentLeft + contentW;

        HFONT titleFont = Font(22, FW_SEMIBOLD);
        HGDIOBJ oldFont = SelectObject(dc, titleFont);
        RECT title{ contentLeft, S(104), contentRight, S(146) };
        Text(dc, L"\u6700\u8fd1\u9605\u8bfb", title, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().text);
        SelectObject(dc, oldFont);
        DeleteObject(titleFont);

        HFONT f = Font(9);
        oldFont = SelectObject(dc, f);
        g_homeSearchRect = RECT{ contentLeft, S(158), std::min<int>(contentRight, contentLeft + S(518)), S(204) };
        RoundFill(dc, g_homeSearchRect, S(10), T().paper, g_homeSearchFocused ? T().accent : T().line);
        RECT searchIcon{ g_homeSearchRect.left + S(14), g_homeSearchRect.top + S(13), g_homeSearchRect.left + S(31), g_homeSearchRect.bottom - S(13) };
        DrawSideTabIcon(dc, searchIcon, SideTabIcon::Search, MixColor(T().muted, T().text, 0.06));
        g_homeSearchClearRect = RECT{ g_homeSearchRect.right - S(36), g_homeSearchRect.top + S(9), g_homeSearchRect.right - S(8), g_homeSearchRect.bottom - S(9) };
        RECT inputText{ g_homeSearchRect.left + S(40), g_homeSearchRect.top, g_homeSearchRect.right - (g_homeSearchQuery.empty() ? S(14) : S(42)), g_homeSearchRect.bottom };
        HFONT searchFont = Font(11);
        HGDIOBJ oldSearchFont = SelectObject(dc, searchFont);
        std::wstring shown = g_homeSearchQuery.empty() ? L"\u641c\u7d22\u6587\u6863" : g_homeSearchQuery;
        PaintEditorSelection(dc, g_homeSearchQuery, inputText, g_homeSearchCaretIndex,
            g_homeSearchSelectionAnchor, false);
        Text(dc, shown, inputText, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS,
            g_homeSearchQuery.empty() ? MixColor(T().muted, T().paper, 0.16) : T().text);
        if (g_homeSearchFocused && g_homeSearchCaretVisible)
        {
            g_homeSearchCaretIndex = std::clamp(g_homeSearchCaretIndex, 0, static_cast<int>(g_homeSearchQuery.size()));
            int caretX = CaretXCurrentFont(dc, g_homeSearchQuery, inputText, g_homeSearchCaretIndex, false) + S(2);
            caretX = std::clamp<int>(caretX, inputText.left + S(1), inputText.right - S(2));
            HPEN caretPen = CreatePen(PS_SOLID, std::max(1, S(1)), T().text);
            HGDIOBJ oldCaret = SelectObject(dc, caretPen);
            MoveToEx(dc, caretX, g_homeSearchRect.top + S(11), nullptr);
            LineTo(dc, caretX, g_homeSearchRect.bottom - S(11));
            if (g_hwnd) SetImeCompositionPoint(g_hwnd, POINT{ caretX, g_homeSearchRect.bottom - S(9) });
            SelectObject(dc, oldCaret);
            DeleteObject(caretPen);
        }
        if (!g_homeSearchQuery.empty())
        {
            if (Hit(g_homeSearchClearRect, g_mousePos.x, g_mousePos.y)) RoundFill(dc, g_homeSearchClearRect, S(7), SidebarHoverFill(), SidebarHoverFill());
            Text(dc, L"\u00d7", g_homeSearchClearRect, DT_CENTER | DT_VCENTER | DT_SINGLELINE, T().muted);
        }
        SelectObject(dc, oldSearchFont);
        DeleteObject(searchFont);

        int right = contentRight;
        RECT clear{ right - S(112), S(168), right, S(200) };
        AddHomeHit(clear, -1, HomeAction::ClearAll, L"\u6e05\u9664\u8bb0\u5f55");
        size_t clearIndex = g_homeHits.size() - 1;
        DrawHomeTextButton(dc, clear, HomeAction::ClearAll, L"\u6e05\u9664\u8bb0\u5f55", clearIndex);
        RECT view{ clear.left - S(126), S(168), clear.left - S(12), S(200) };
        AddHomeHit(view, -1, HomeAction::ToggleView, g_homeListView ? L"\u5207\u6362\u89c6\u56fe" : L"\u5207\u6362\u5217\u8868");
        size_t viewIndex = g_homeHits.size() - 1;
        DrawHomeTextButton(dc, view, HomeAction::ToggleView, g_homeListView ? L"\u5207\u6362\u89c6\u56fe" : L"\u5207\u6362\u5217\u8868", viewIndex);
        SelectObject(dc, oldFont);
        DeleteObject(f);
    }

    void PaintHomeGrid(HDC dc, RECT client)
    {
        g_recentRects.clear();
        g_homeHits.clear();
        g_homeRecentIds = FilteredHomeRecentIds();
        g_homeContentHeight = ComputeHomeGridContentHeight(client, g_homeRecentIds.size());
        g_homeScrollY = ClampHomeScrollValue(client, g_homeScrollY);
        PaintHomeHeader(dc, client);
        RECT viewport = HomeContentViewportRect(client);
        g_homeThumbProtectedKeys.clear();
        RECT paintWindow{ viewport.left, viewport.top - S(80), viewport.right, viewport.bottom + S(80) };

        HFONT f = Font(9);
        HGDIOBJ oldFont = SelectObject(dc, f);
        int tileW = S(152);
        int coverH = S(198);
        int nameH = S(42);
        int tileH = coverH + nameH + S(10);
        int gapX = S(28);
        int gapY = S(28);
        int gridLeft = S(42);
        int gridRight = std::max<int>(gridLeft + tileW, client.right - S(42));
        int availableW = std::max<int>(tileW, gridRight - gridLeft);
        int columns = std::max<int>(1, (availableW + gapX) / (tileW + gapX));
        int gridW = columns * tileW + std::max(0, columns - 1) * gapX;
        int startX = gridLeft + std::max(0, (availableW - gridW) / 2);
        bool emptySearch = !g_homeSearchQuery.empty() && g_homeRecentIds.empty();
        int x = startX;
        int y = viewport.top + (emptySearch ? S(102) : S(16)) - g_homeScrollY;
        int lastBottom = y;
        int maxRight = startX + gridW;
        auto advance = [&]()
        {
            x += tileW + gapX;
            if (x + tileW > maxRight)
            {
                x = startX;
                y += tileH + gapY;
            }
        };
        auto drawCoverFrame = [&](RECT cover, bool active)
        {
            DrawContactShadow(dc, cover, active ? 30 : 22);
            DrawRoundedShadow(dc, cover, S(5.0f), S(1), S(2), S(4), active ? 22 : 14);
            RoundFill(dc, cover, S(5), T().paper, active ? T().accent : T().line);
        };

        int saved = SaveDC(dc);
        IntersectClipRect(dc, viewport.left, viewport.top, viewport.right, viewport.bottom);
        RECT activeClip{};
        GetClipBox(dc, &activeClip);

        RECT openTile{ x, y, x + tileW, y + tileH };
        g_recentRects.push_back(openTile);
        RECT openCover{ openTile.left, openTile.top, openTile.right, openTile.top + coverH };
        bool drawOpenTile = Intersects(openTile, activeClip);
        if (drawOpenTile) drawCoverFrame(openCover, false);
        HFONT plusFont = drawOpenTile ? Font(30, FW_LIGHT) : nullptr;
        HGDIOBJ oldPlus = plusFont ? SelectObject(dc, plusFont) : nullptr;
        RECT plus{ openCover.left, openCover.top + S(42), openCover.right, openCover.top + S(92) };
        if (drawOpenTile) Text(dc, L"+", plus, DT_CENTER | DT_VCENTER | DT_SINGLELINE, T().accent);
        if (oldPlus) SelectObject(dc, oldPlus);
        if (plusFont) DeleteObject(plusFont);
        RECT openMain{ openCover.left + S(10), openCover.top + S(100), openCover.right - S(10), openCover.top + S(128) };
        if (drawOpenTile) Text(dc, L"\u6253\u5f00 PDF", openMain, DT_CENTER | DT_VCENTER | DT_SINGLELINE, T().text);
        RECT openSub{ openCover.left + S(14), openCover.top + S(132), openCover.right - S(14), openCover.bottom - S(18) };
        if (drawOpenTile) Text(dc, L"\u62d6\u5165\u6587\u4ef6\u6216\u70b9\u51fb\u6253\u5f00", openSub, DT_CENTER | DT_WORDBREAK, T().muted);
        RECT openName{ openTile.left, openCover.bottom + S(8), openTile.right, openTile.bottom };
        if (drawOpenTile) Text(dc, L"\u6253\u5f00\u6587\u6863", openName, DT_CENTER | DT_TOP | DT_SINGLELINE, T().muted);
        lastBottom = std::max(lastBottom, static_cast<int>(openTile.bottom));
        advance();

        for (size_t displayIndex = 0; displayIndex < g_homeRecentIds.size(); ++displayIndex)
        {
            int recentIndex = g_homeRecentIds[displayIndex];
            RecentItem const& item = g_recent[static_cast<size_t>(recentIndex)];
            RECT tile{ x, y, x + tileW, y + tileH };
            g_recentRects.push_back(tile);
            bool visibleTile = Intersects(tile, paintWindow);
            if (!visibleTile)
            {
                lastBottom = std::max(lastBottom, static_cast<int>(tile.bottom));
                if (tile.top > paintWindow.bottom) break;
                advance();
                continue;
            }
            RECT cover{ tile.left, tile.top, tile.right, tile.top + coverH };
            bool drawTile = Intersects(tile, activeClip);
            bool hovered = Hit(cover, g_mousePos.x, g_mousePos.y);
            if (drawTile && g_homeScrollLightPaint)
                RoundFill(dc, cover, S(5), T().paper, hovered || item.pinned ? T().accent : T().line);
            else if (drawTile)
                drawCoverFrame(cover, hovered || item.pinned);
            RECT inner{ cover.left + S(7), cover.top + S(7), cover.right - S(7), cover.bottom - S(7) };
            RECT preload{ viewport.left, viewport.top - S(260), viewport.right, viewport.bottom + S(260) };
            bool nearViewport = Intersects(tile, preload);
            if (nearViewport) g_homeThumbProtectedKeys.insert(HomeThumbKey(item, inner.right - inner.left, PdfRenderTheme()));
            PageImage* thumb = nearViewport ? LoadHomeThumb(item, inner.right - inner.left) : nullptr;
            if (drawTile && thumb && (thumb->dib || !thumb->bgra.empty())) DrawImageFit(dc, *thumb, inner);
            else if (drawTile)
            {
                HFONT pdfFont = Font(18, FW_SEMIBOLD);
                HGDIOBJ oldPdfFont = SelectObject(dc, pdfFont);
                Text(dc, L"PDF", inner, DT_CENTER | DT_VCENTER | DT_SINGLELINE, T().accent);
                SelectObject(dc, oldPdfFont);
                DeleteObject(pdfFont);
            }

            RECT starHot{ cover.right - S(39), cover.top + S(9), cover.right - S(9), cover.top + S(39) };
            AddHomeHit(starHot, recentIndex, HomeAction::Favorite, item.favorite ? L"\u53d6\u6d88\u6536\u85cf" : L"\u6536\u85cf");
            if (drawTile) DrawHomeIconButton(dc, starHot, HomeAction::Favorite, item.favorite, g_homeHits.size() - 1, hovered, 5, false);

            RECT dock{ cover.left + S(17), cover.bottom - S(45), cover.left + S(120), cover.bottom - S(13) };
            if (drawTile && (hovered || item.pinned))
            {
                if (drawTile && g_homeScrollLightPaint)
                    RoundFill(dc, dock, S(11), MixColor(T().panel, T().paper, 0.36), MixColor(T().line, T().paper, 0.18));
                else
                    GlassRoundedSurface(dc, dock, IsDarkTheme() ? 196 : 208, S(11.0f));
            }
            HomeAction actions[] = { HomeAction::Pin, HomeAction::Folder, HomeAction::Remove };
            const wchar_t* tips[] = { item.pinned ? L"\u53d6\u6d88\u7f6e\u9876" : L"\u7f6e\u9876", L"\u6253\u5f00\u6587\u4ef6\u5939", L"\u5220\u9664\u8bb0\u5f55" };
            for (int a = 0; a < 3; ++a)
            {
                RECT hot{ dock.left + S(5) + a * S(32), dock.top + S(3), dock.left + S(5) + a * S(32) + S(26), dock.top + S(29) };
                AddHomeHit(hot, recentIndex, actions[a], tips[a]);
                if (drawTile) DrawHomeIconButton(dc, hot, actions[a], actions[a] == HomeAction::Pin && item.pinned, g_homeHits.size() - 1, hovered, 4, false);
            }

            RECT name{ tile.left, cover.bottom + S(7), tile.right, tile.bottom };
            if (drawTile)
            {
                std::wstring shownName = FitHomeTitleToLines(dc, item.name, name.right - name.left, 2);
                int textHeight = MeasureTextHeight(dc, shownName, name.right - name.left,
                    DT_CENTER | DT_WORDBREAK | DT_NOPREFIX);
                int nameHeight = static_cast<int>(name.bottom - name.top);
                int verticalInset = std::max(0, (nameHeight - textHeight) / 2);
                name.top += verticalInset;
                Text(dc, shownName, name, DT_CENTER | DT_WORDBREAK | DT_NOPREFIX, T().text);
            }
            lastBottom = std::max(lastBottom, static_cast<int>(tile.bottom));
            advance();
        }
        if (emptySearch)
        {
            // Align the empty state with the same content column as the
            // opening tile instead of anchoring it to the window edge.
            RECT empty{ startX, viewport.top + S(16) - g_homeScrollY,
                client.right - S(42), viewport.top + S(82) - g_homeScrollY };
            Text(dc, L"\u6ca1\u6709\u627e\u5230\u5339\u914d\u7684\u6587\u6863", empty, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().muted);
            lastBottom = std::max(lastBottom, static_cast<int>(empty.bottom));
        }
        RestoreDC(dc, saved);
        SelectObject(dc, oldFont);
        DeleteObject(f);
    }

    void PaintHomeList(HDC dc, RECT client)
    {
        g_recentRects.clear();
        g_homeHits.clear();
        g_homeRecentIds = FilteredHomeRecentIds();
        g_homeContentHeight = ComputeHomeListContentHeight(g_homeRecentIds.size(), !g_homeSearchQuery.empty() && g_homeRecentIds.empty());
        g_homeScrollY = ClampHomeScrollValue(client, g_homeScrollY);
        PaintHomeHeader(dc, client);
        RECT viewport = HomeContentViewportRect(client);

        HFONT f = Font(9);
        HGDIOBJ oldFont = SelectObject(dc, f);
        int tileW = S(152);
        int gapX = S(28);
        int boundaryLeft = S(42);
        int boundaryRight = std::max<int>(boundaryLeft + tileW, client.right - S(42));
        int availableW = std::max<int>(tileW, boundaryRight - boundaryLeft);
        int columns = std::max<int>(1, (availableW + gapX) / (tileW + gapX));
        int contentW = columns * tileW + std::max(0, columns - 1) * gapX;
        int contentLeft = boundaryLeft + std::max(0, (availableW - contentW) / 2);
        int contentRight = contentLeft + contentW;
        int left = contentLeft + S(10);
        int headerTop = viewport.top + S(8);
        int rowH = S(48);
        int actionX = contentRight - S(144);
        int sizeX = actionX - S(126);
        int nameW = std::max<int>(S(300), (sizeX - left) * 34 / 100);
        int dateX = left + nameW;
        int dirX = dateX + S(180);
        Text(dc, L"\u6587\u6863\u540d\u79f0", RECT{ left, headerTop, dateX - S(20), headerTop + S(28) }, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().text);
        Text(dc, L"\u9605\u8bfb\u65f6\u95f4", RECT{ dateX, headerTop, dirX - S(20), headerTop + S(28) }, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().text);
        Text(dc, L"\u6240\u5728\u4e66\u7b7e", RECT{ dirX, headerTop, sizeX - S(20), headerTop + S(28) }, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().text);
        Text(dc, L"\u5927\u5c0f", RECT{ sizeX, headerTop, actionX - S(16), headerTop + S(28) }, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().text);
        RECT rowsViewport{ viewport.left, headerTop + S(34), viewport.right, viewport.bottom };
        RECT rowPaintWindow{ rowsViewport.left, rowsViewport.top - S(60), rowsViewport.right, rowsViewport.bottom + S(60) };
        int y = rowsViewport.top - g_homeScrollY;
        int lastBottom = y;
        g_recentRects.push_back(RECT{});
        int saved = SaveDC(dc);
        IntersectClipRect(dc, rowsViewport.left, rowsViewport.top, rowsViewport.right, rowsViewport.bottom);
        for (size_t displayIndex = 0; displayIndex < g_homeRecentIds.size(); ++displayIndex)
        {
            int recentIndex = g_homeRecentIds[displayIndex];
            RecentItem const& item = g_recent[static_cast<size_t>(recentIndex)];
            RECT row{ contentLeft, y, contentRight, y + rowH };
            g_recentRects.push_back(row);
            bool visibleRow = Intersects(row, rowPaintWindow);
            if (!visibleRow)
            {
                lastBottom = std::max(lastBottom, static_cast<int>(row.bottom));
                y += rowH;
                if (row.top > rowPaintWindow.bottom) break;
                continue;
            }
            bool rowHover = Hit(row, g_mousePos.x, g_mousePos.y);
            if (rowHover) RoundFill(dc, row, S(7), SidebarHoverFill(), SidebarHoverFill());
            RECT name{ left, row.top, dateX - S(20), row.bottom };
            Text(dc, item.name, name, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS, T().text);
            Text(dc, FormatDate(item.openedAt), RECT{ dateX, row.top, dirX - S(20), row.bottom }, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().muted);
            Text(dc, std::filesystem::path(item.path).parent_path().wstring(), RECT{ dirX, row.top, sizeX - S(20), row.bottom }, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS, T().muted);
            Text(dc, FormatFileSize(item.path), RECT{ sizeX, row.top, actionX - S(16), row.bottom }, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().muted);
            HomeAction actions[] = { HomeAction::Pin, HomeAction::Folder, HomeAction::Favorite, HomeAction::Remove };
            const wchar_t* tips[] = { item.pinned ? L"\u53d6\u6d88\u7f6e\u9876" : L"\u7f6e\u9876", L"\u6253\u5f00\u6587\u4ef6\u5939", item.favorite ? L"\u53d6\u6d88\u6536\u85cf" : L"\u6536\u85cf", L"\u5220\u9664\u8bb0\u5f55" };
            for (int a = 0; a < 4; ++a)
            {
                RECT hot{ actionX + a * S(38), row.top + S(8), actionX + a * S(38) + S(30), row.top + S(38) };
                AddHomeHit(hot, recentIndex, actions[a], tips[a]);
                bool active = (actions[a] == HomeAction::Pin && item.pinned) || (actions[a] == HomeAction::Favorite && item.favorite);
                DrawHomeIconButton(dc, hot, actions[a], active, g_homeHits.size() - 1, rowHover, 5, true);
            }
            lastBottom = std::max(lastBottom, static_cast<int>(row.bottom));
            y += rowH;
        }
        if (!g_homeSearchQuery.empty() && g_homeRecentIds.empty())
        {
            RECT empty{ left, rowsViewport.top + S(8) - g_homeScrollY, contentRight, rowsViewport.top + S(64) - g_homeScrollY };
            Text(dc, L"\u6ca1\u6709\u627e\u5230\u5339\u914d\u7684\u6587\u6863", empty, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().muted);
            lastBottom = std::max(lastBottom, static_cast<int>(empty.bottom));
        }
        RestoreDC(dc, saved);
        SelectObject(dc, oldFont);
        DeleteObject(f);
    }

    void PaintClearRecentDialog(HDC dc, RECT client)
    {
        if (!ConfirmationDialogOpen()) return;
        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        Gdiplus::SolidBrush scrim(GdiColor(RGB(20, 24, 28), IsDarkTheme() ? 128 : 82));
        g.FillRectangle(&scrim, 0, 0, client.right, client.bottom);

        int w = S(420);
        int h = S(214);
        RECT panel{ (client.right - w) / 2, (client.bottom - h) / 2, (client.right + w) / 2, (client.bottom + h) / 2 };
        DrawRoundedShadow(dc, panel, S(14.0f), S(1), S(5), S(7), IsDarkTheme() ? 58 : 38);
        GlassRoundedSurface(dc, panel, IsDarkTheme() ? 232 : 248, S(14.0f), false);

        g_clearDialogCloseRect = RECT{ panel.right - S(42), panel.top + S(14), panel.right - S(14), panel.top + S(42) };
        if (Hit(g_clearDialogCloseRect, g_mousePos.x, g_mousePos.y)) RoundFill(dc, g_clearDialogCloseRect, S(7), SidebarHoverFill(), SidebarHoverFill());
        HFONT closeFont = Font(18, FW_LIGHT);
        HGDIOBJ oldClose = SelectObject(dc, closeFont);
        Text(dc, L"\u00d7", g_clearDialogCloseRect, DT_CENTER | DT_VCENTER | DT_SINGLELINE, T().muted);
        SelectObject(dc, oldClose);
        DeleteObject(closeFont);

        RECT icon{ panel.left + S(36), panel.top + S(70), panel.left + S(86), panel.top + S(120) };
        Gdiplus::SolidBrush iconBg(GdiColor(MixColor(T().accent, RGB(255, 255, 255), IsDarkTheme() ? 0.18 : 0.36), 210));
        g.FillEllipse(&iconBg, Rf(icon));
        HFONT bangFont = Font(26, FW_SEMIBOLD);
        HGDIOBJ oldBang = SelectObject(dc, bangFont);
        Text(dc, L"!", icon, DT_CENTER | DT_VCENTER | DT_SINGLELINE, ForegroundOn(T().accent));
        SelectObject(dc, oldBang);
        DeleteObject(bangFont);

        HFONT titleFont = SystemUiFont(10, FW_SEMIBOLD);
        HGDIOBJ oldFont = SelectObject(dc, titleFont);
        RECT title{ panel.left + S(112), panel.top + S(60), panel.right - S(34), panel.top + S(92) };
        const wchar_t* dialogTitle = g_confirmDeleteAllAnnotations ? L"确定要删除所有注释吗？" : L"确定要清空最近使用记录吗？";
        Text(dc, dialogTitle, title, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().text);
        SelectObject(dc, oldFont);
        DeleteObject(titleFont);
        HFONT bodyFont = SystemUiFont(10);
        oldFont = SelectObject(dc, bodyFont);
        RECT body{ panel.left + S(112), panel.top + S(92), panel.right - S(34), panel.top + S(130) };
        const wchar_t* dialogBody = g_confirmDeleteAllAnnotations
            ? L"这会删除当前文档中的全部注释。保存 PDF 后，此操作无法撤销。"
            : L"这会删除首页记录、阅读进度和封面缓存，不会删除 PDF 文件。";
        Text(dc, dialogBody, body, DT_LEFT | DT_WORDBREAK, T().muted);

        g_clearDialogConfirmRect = RECT{ panel.right - S(198), panel.bottom - S(58), panel.right - S(106), panel.bottom - S(24) };
        g_clearDialogCancelRect = RECT{ panel.right - S(94), panel.bottom - S(58), panel.right - S(24), panel.bottom - S(24) };
        bool confirmHover = Hit(g_clearDialogConfirmRect, g_mousePos.x, g_mousePos.y);
        bool cancelHover = Hit(g_clearDialogCancelRect, g_mousePos.x, g_mousePos.y);
        COLORREF confirmColor = g_confirmDeleteAllAnnotations ? RGB(210, 67, 67) : T().accent;
        RoundFill(dc, g_clearDialogConfirmRect, S(8), confirmHover ? MixColor(confirmColor, RGB(255, 255, 255), 0.16) : confirmColor, confirmColor);
        Text(dc, g_confirmDeleteAllAnnotations ? L"删除" : L"确定", g_clearDialogConfirmRect, DT_CENTER | DT_VCENTER | DT_SINGLELINE, ForegroundOn(confirmColor));
        RoundFill(dc, g_clearDialogCancelRect, S(8), cancelHover ? SidebarHoverFill() : T().panel2, T().line);
        Text(dc, L"\u53d6\u6d88", g_clearDialogCancelRect, DT_CENTER | DT_VCENTER | DT_SINGLELINE, T().muted);
        SelectObject(dc, oldFont);
        DeleteObject(bodyFont);
    }

    void PaintCustomZoomDialog(HDC dc, RECT client)
    {
        g_zoomDialogRect = {};
        g_zoomDialogInputRect = {};
        g_zoomDialogConfirmRect = {};
        g_zoomDialogCancelRect = {};
        if (!g_customZoomOpen) return;

        Gdiplus::Graphics g(dc);
        g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        g.SetPixelOffsetMode(Gdiplus::PixelOffsetModeHalf);
        Gdiplus::SolidBrush scrim(GdiColor(RGB(18, 22, 28), IsDarkTheme() ? 98 : 58));
        g.FillRectangle(&scrim, Rf(client));

        int panelW = S(246);
        int panelH = S(166);
        int left = client.left + (client.right - client.left - panelW) / 2;
        int top = client.top + (client.bottom - client.top - panelH) / 2;
        g_zoomDialogRect = RECT{ left, top, left + panelW, top + panelH };

        DrawRoundedShadow(dc, g_zoomDialogRect, S(12.0f), S(1), S(3), S(4), IsDarkTheme() ? 40 : 22);
        GlassRoundedSurface(dc, g_zoomDialogRect, IsDarkTheme() ? 234 : 244, S(12.0f), false);

        HFONT titleFont = Font(10, FW_SEMIBOLD);
        HGDIOBJ oldFont = SelectObject(dc, titleFont);
        RECT title{ g_zoomDialogRect.left + S(18), g_zoomDialogRect.top + S(14), g_zoomDialogRect.right - S(18), g_zoomDialogRect.top + S(36) };
        Text(dc, L"\u81ea\u5b9a\u4e49\u7f29\u653e", title, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().text);
        SelectObject(dc, oldFont);
        DeleteObject(titleFont);

        HFONT hintFont = Font(7);
        oldFont = SelectObject(dc, hintFont);
        RECT hint{ g_zoomDialogRect.left + S(18), g_zoomDialogRect.top + S(37), g_zoomDialogRect.right - S(18), g_zoomDialogRect.top + S(53) };
        Text(dc, L"\u8f93\u5165\u9875\u9762\u7f29\u653e\u6bd4\u4f8b", hint, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().muted);
        SelectObject(dc, oldFont);
        DeleteObject(hintFont);

        g_zoomDialogInputRect = RECT{ g_zoomDialogRect.left + S(18), g_zoomDialogRect.top + S(58), g_zoomDialogRect.right - S(18), g_zoomDialogRect.top + S(100) };
        bool inputHover = Hit(g_zoomDialogInputRect, g_mousePos.x, g_mousePos.y);
        COLORREF inputFill = MixColor(T().paper, T().panel2, IsDarkTheme() ? 0.18 : 0.08);
        COLORREF inputLine = g_customZoomFocused
            ? T().accent
            : (inputHover ? MixColor(T().line, T().accent, 0.28) : T().line);
        Gdiplus::SolidBrush inputBrush(GdiColor(inputFill, IsDarkTheme() ? 224 : 238));
        Gdiplus::Pen inputBorder(
            GdiColor(inputLine, g_customZoomFocused ? 220 : (inputHover ? 180 : 138)),
            std::max<Gdiplus::REAL>(1.0f, S(g_customZoomFocused ? 1.2f : 1.0f)));
        FillGdiRoundRect(g, inputBrush, Rf(g_zoomDialogInputRect), S(8.0f));
        DrawGdiRoundRect(g, inputBorder, Rf(g_zoomDialogInputRect), S(8.0f));

        RECT inputTextRect{ g_zoomDialogInputRect.left + S(14), g_zoomDialogInputRect.top, g_zoomDialogInputRect.right - S(48), g_zoomDialogInputRect.bottom };
        HFONT inputFont = Font(13, FW_SEMIBOLD);
        oldFont = SelectObject(dc, inputFont);
        std::wstring inputText = g_customZoomText.empty() ? L"" : g_customZoomText;
        PaintEditorSelection(dc, inputText, inputTextRect,
            static_cast<int>(g_customZoomCaretIndex), g_customZoomSelectionAnchor, false);
        Text(dc, inputText, inputTextRect, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().text);
        if (g_customZoomFocused)
        {
            SIZE prefixSize{};
            GetTextExtentPoint32W(dc, inputText.c_str(), static_cast<int>(std::min(g_customZoomCaretIndex, inputText.size())), &prefixSize);
            SetCaretPos(std::clamp(inputTextRect.left + prefixSize.cx, inputTextRect.left, inputTextRect.right), g_zoomDialogInputRect.top + S(9));
        }
        SelectObject(dc, oldFont);
        DeleteObject(inputFont);

        HFONT pctFont = Font(10, FW_SEMIBOLD);
        oldFont = SelectObject(dc, pctFont);
        RECT pctRect{ g_zoomDialogInputRect.right - S(44), g_zoomDialogInputRect.top, g_zoomDialogInputRect.right - S(14), g_zoomDialogInputRect.bottom };
        Text(dc, L"%", pctRect, DT_RIGHT | DT_VCENTER | DT_SINGLELINE, MixColor(T().muted, T().text, 0.16));
        SelectObject(dc, oldFont);
        DeleteObject(pctFont);

        HFONT rangeFont = Font(7);
        oldFont = SelectObject(dc, rangeFont);
        RECT range{ g_zoomDialogRect.left + S(19), g_zoomDialogRect.top + S(103), g_zoomDialogRect.right - S(18), g_zoomDialogRect.top + S(120) };
        Text(dc, L"\u652f\u6301 8.33% - 1600%", range, DT_LEFT | DT_VCENTER | DT_SINGLELINE, T().muted);
        SelectObject(dc, oldFont);
        DeleteObject(rangeFont);

        int buttonW = S(72);
        int buttonH = S(30);
        int buttonGap = S(8);
        int buttonBottom = g_zoomDialogRect.bottom - S(14);
        g_zoomDialogConfirmRect = RECT{ g_zoomDialogRect.right - S(18) - buttonW, buttonBottom - buttonH, g_zoomDialogRect.right - S(18), buttonBottom };
        g_zoomDialogCancelRect = RECT{ g_zoomDialogConfirmRect.left - buttonGap - buttonW, buttonBottom - buttonH, g_zoomDialogConfirmRect.left - buttonGap, buttonBottom };
        auto drawDialogButton = [&](RECT r, const wchar_t* label, bool primary)
        {
            bool hover = Hit(r, g_mousePos.x, g_mousePos.y);
            bool pressed = hover && g_hasPressedButton && EqualRect(&g_pressedButtonRect, &r);
            COLORREF fill = primary
                ? (pressed ? MixColor(T().accent, RGB(0, 0, 0), 0.16) : (hover ? MixColor(T().accent, RGB(255, 255, 255), 0.12) : T().accent))
                : (pressed ? MixColor(T().panel2, T().accent, 0.16) : (hover ? MixColor(T().panel2, T().accent, 0.08) : T().panel2));
            COLORREF line = primary ? MixColor(T().accent, T().text, 0.08) : (hover || pressed ? MixColor(T().line, T().accent, 0.24) : T().line);
            Gdiplus::SolidBrush fillBrush(GdiColor(fill, primary ? 250 : 238));
            Gdiplus::Pen borderPen(GdiColor(line, primary ? 205 : (hover || pressed ? 175 : 130)), std::max<Gdiplus::REAL>(1.0f, S(1.0f)));
            FillGdiRoundRect(g, fillBrush, Rf(r), S(6.0f));
            DrawGdiRoundRect(g, borderPen, Rf(r), S(6.0f));
            g.Flush();

            RECT labelRect = r;
            if (pressed) OffsetRect(&labelRect, 0, S(1));
            HFONT buttonFont = Font(8, FW_SEMIBOLD);
            HGDIOBJ oldButtonFont = SelectObject(dc, buttonFont);
            Text(dc, label, labelRect, DT_CENTER | DT_VCENTER | DT_SINGLELINE,
                primary ? ForegroundOn(T().accent) : (hover || pressed ? T().text : T().muted));
            SelectObject(dc, oldButtonFont);
            DeleteObject(buttonFont);
        };
        drawDialogButton(g_zoomDialogCancelRect, L"\u53d6\u6d88", false);
        drawDialogButton(g_zoomDialogConfirmRect, L"\u786e\u5b9a", true);
    }
