                bool floating = g_tabDragFloating;
                g_draggingTab = false;
                g_tabDetachArmed = false;
                g_tabDragFloating = false;
                g_draggingTabIndex = -1;
                g_tabDragInsertIndex = -1;
                ReleaseCapture();
                if (detach)
                    DetachTabToNewWindow(hwnd, index);
